import { addDays, addWeeks, subWeeks } from 'date-fns';
import {
    computeWeekAnchor,
    groupTablesByZone,
    mapTableToZoneTable,
    type ZoneTable,
} from '@/modules/commerce/relation/reservations/hooks/useReservationsPage';
import type { Table } from '@nexus/contracts';

const makeTable = (overrides: Partial<Table> = {}): Table => ({
    id: 't1',
    number: '1',
    seats: 4,
    status: 'free',
    zoneId: 'STANDARD',
    ...overrides,
} as Table);

describe('computeWeekAnchor', () => {
    const base = new Date('2025-03-10');

    it('retourne la base si weekOffset = 0', () => {
        expect(computeWeekAnchor(base, 0)).toEqual(base);
    });

    it('avance de N semaines si weekOffset > 0', () => {
        expect(computeWeekAnchor(base, 2)).toEqual(addWeeks(base, 2));
    });

    it('recule de N semaines si weekOffset < 0', () => {
        expect(computeWeekAnchor(base, -1)).toEqual(subWeeks(base, 1));
    });

    it('weekOffset = 1 → base + 7 jours', () => {
        const result = computeWeekAnchor(base, 1);
        expect(result).toEqual(addDays(base, 7));
    });
});

describe('mapTableToZoneTable', () => {
    it('mappe statut free → available', () => {
        const t = makeTable({ status: 'free' });
        expect(mapTableToZoneTable(t).status).toBe('available');
    });

    it('mappe statut seated → occupied', () => {
        const t = makeTable({ status: 'seated' as Table['status'] });
        expect(mapTableToZoneTable(t).status).toBe('occupied');
    });

    it('mappe tout autre statut → reserved', () => {
        const t = makeTable({ status: 'reserved' as Table['status'] });
        expect(mapTableToZoneTable(t).status).toBe('reserved');
    });

    it('détecte type vip depuis zoneId VIP', () => {
        const t = makeTable({ zoneId: 'VIP' });
        expect(mapTableToZoneTable(t).type).toBe('vip');
    });

    it('détecte type terrace depuis zoneId contenant "terrace"', () => {
        const t = makeTable({ zoneId: 'zone-terrasse' });
        expect(mapTableToZoneTable(t).type).toBe('terrace');
    });

    it('type standard par défaut', () => {
        const t = makeTable({ zoneId: 'STANDARD' });
        expect(mapTableToZoneTable(t).type).toBe('standard');
    });

    it('seats par défaut à 4 si absent', () => {
        const t = makeTable({ seats: undefined as unknown as number });
        expect(mapTableToZoneTable(t).seats).toBe(4);
    });
});

describe('groupTablesByZone', () => {
    it('groupe les tables par zoneId', () => {
        const tables = [
            makeTable({ id: 't1', number: '1', zoneId: 'VIP' }),
            makeTable({ id: 't2', number: '2', zoneId: 'STANDARD' }),
            makeTable({ id: 't3', number: '3', zoneId: 'VIP' }),
        ];
        const result = groupTablesByZone(tables);

        expect(result['VIP']).toHaveLength(2);
        expect(result['STANDARD']).toHaveLength(1);
    });

    it('utilise "STANDARD" comme zone par défaut si zoneId absent', () => {
        const t = makeTable({ zoneId: undefined });
        const result = groupTablesByZone([t]);
        expect(result['STANDARD']).toHaveLength(1);
    });

    it('retourne un objet vide pour un tableau vide', () => {
        expect(groupTablesByZone([])).toEqual({});
    });

    it('chaque table est convertie en ZoneTable', () => {
        const t = makeTable({ number: '5', zoneId: 'VIP', status: 'free', seats: 6 });
        const result = groupTablesByZone([t]);
        const zt = result['VIP'][0] as ZoneTable;
        expect(zt.number).toBe('5');
        expect(zt.seats).toBe(6);
        expect(zt.type).toBe('vip');
        expect(zt.status).toBe('available');
    });
});

import { describe, it, expect } from 'vitest';
import { aggregateRecipeIngredients } from '@/modules/logistics/services/StockEngine';
import type { Recipe } from '@nexus/contracts';

const makeRecipe = (ingredients: { id: string; name: string; quantity: number }[]): Recipe =>
    ({ id: 'r1', name: 'Test Recipe', ingredients } as unknown as Recipe);

describe('aggregateRecipeIngredients', () => {
    it("initialise les ingredients depuis la recette", () => {
        const recipe = makeRecipe([
            { id: 'ing-1', name: 'Farine', quantity: 0.2 },
            { id: 'ing-2', name: 'Sel',    quantity: 0.01 },
        ]);
        const result = aggregateRecipeIngredients(recipe, []);

        expect(result.get('ing-1')).toEqual({ id: 'ing-1', name: 'Farine', quantity: 0.2 });
        expect(result.get('ing-2')).toEqual({ id: 'ing-2', name: 'Sel',    quantity: 0.01 });
    });

    it("modifier add incremente la quantite", () => {
        const recipe = makeRecipe([{ id: 'ing-1', name: 'Mozza', quantity: 0.15 }]);
        const modifiers = [{ action: 'add', ingredientId: 'ing-1', name: 'Mozza extra', quantityImpact: 0.05 }];

        const result = aggregateRecipeIngredients(recipe, modifiers);
        expect(result.get('ing-1')?.quantity).toBeCloseTo(0.2);
    });

    it("modifier remove supprime l'ingredient", () => {
        const recipe = makeRecipe([{ id: 'ing-1', name: 'Anchois', quantity: 0.03 }]);
        const modifiers = [{ action: 'remove', ingredientId: 'ing-1', name: 'Anchois' }];

        const result = aggregateRecipeIngredients(recipe, modifiers);
        expect(result.has('ing-1')).toBe(false);
    });

    it("modifier add sur ingredient inexistant le cree", () => {
        const recipe = makeRecipe([]);
        const modifiers = [{ action: 'add', ingredientId: 'ing-new', name: 'Truffe', quantityImpact: 0.01 }];

        const result = aggregateRecipeIngredients(recipe, modifiers);
        expect(result.get('ing-new')).toEqual({ id: 'ing-new', name: 'Truffe', quantity: 0.01 });
    });

    it("modifier sans ingredientId est ignore", () => {
        const recipe = makeRecipe([{ id: 'ing-1', name: 'Sel', quantity: 0.01 }]);
        const modifiers = [{ action: 'add', name: 'Extra sans id', quantityImpact: 5 }];

        const result = aggregateRecipeIngredients(recipe, modifiers);
        expect(result.size).toBe(1);
    });

    it("recette sans ingredients retourne une Map vide", () => {
        const recipe = makeRecipe([]);
        expect(aggregateRecipeIngredients(recipe, []).size).toBe(0);
    });

    it("plusieurs modifiers s'appliquent dans l'ordre", () => {
        const recipe = makeRecipe([{ id: 'ing-1', name: 'Parmesan', quantity: 0.1 }]);
        const modifiers = [
            { action: 'add',    ingredientId: 'ing-1', name: 'Parmesan', quantityImpact: 0.05 },
            { action: 'remove', ingredientId: 'ing-1', name: 'Parmesan' },
        ];

        const result = aggregateRecipeIngredients(recipe, modifiers);
        expect(result.has('ing-1')).toBe(false);
    });
});

import { describe, it, expect } from 'vitest';
import { TaxCalculator } from '@/infrastructure/services/finance/TaxCalculator';
import type { CartItem } from '@/modules/ops/workflow/engine/types';

function cartItem(overrides: Partial<CartItem> = {}): CartItem {
  return {
    productId: 'prod_1',
    name: 'Test Item',
    quantity: 1,
    unitPriceInMicrounits: 120000000, // 12.00€ TTC
    taxRate: '0.10',
    discountInMicrounits: 0 as any,
    ...overrides,
  } as CartItem;
}

describe('TaxCalculator', () => {
  describe('computeTvaBreakdown', () => {
    it('calculates TVA at 10% for a single item', () => {
      const items = [cartItem()];
      const breakdown = TaxCalculator.computeTvaBreakdown(items);
      // TVA = TTC × r/(1+r) = 120_000_000 × 0.10/1.10 = 10_909_091
      expect(breakdown['0.10']).toBe(10909091);
    });

    it('handles multiple tax rates', () => {
      const items = [
        cartItem({ taxRate: '0.055', unitPriceInMicrounits: 100000000 as any }),
        cartItem({ taxRate: '0.20', unitPriceInMicrounits: 200000000 as any }),
      ];
      const breakdown = TaxCalculator.computeTvaBreakdown(items);
      expect(breakdown['0.055']).toBeDefined();
      expect(breakdown['0.20']).toBeDefined();
      expect(Object.keys(breakdown)).toHaveLength(2);
    });

    it('defaults to 10% when taxRate is missing', () => {
      const items = [cartItem({ taxRate: undefined })];
      const breakdown = TaxCalculator.computeTvaBreakdown(items);
      expect(breakdown['0.10']).toBeDefined();
    });

    it('subtracts discounts from TVA base', () => {
      const withDiscount = [cartItem({ discountInMicrounits: 10000000 as any })];
      const withoutDiscount = [cartItem({ discountInMicrounits: 0 as any })];
      const tvaWith = TaxCalculator.computeTvaBreakdown(withDiscount)['0.10']!;
      const tvaWithout = TaxCalculator.computeTvaBreakdown(withoutDiscount)['0.10']!;
      expect(tvaWith).toBeLessThan(tvaWithout);
    });

    it('returns empty breakdown for empty cart', () => {
      expect(TaxCalculator.computeTvaBreakdown([])).toEqual({});
    });

    it('handles quantity > 1', () => {
      const items = [cartItem({ quantity: 3 })];
      const breakdown = TaxCalculator.computeTvaBreakdown(items);
      // 3 × 12.00€ TTC = 360_000_000 → TVA = 360_000_000 × 0.10/1.10
      expect(breakdown['0.10']).toBe(Math.round(360000000 * 0.10 / 1.10));
    });
  });

  describe('calculateTotals', () => {
    it('returns correct TTC, TVA, and HT', () => {
      const items = [cartItem()];
      const totals = TaxCalculator.calculateTotals(items);
      expect(totals.totalTTCInMicrounits).toBe(120000000);
      expect(totals.totalTVAInMicrounits).toBe(10909091);
      expect(totals.totalHTInMicrounits).toBe(120000000 - 10909091);
    });

    it('HT + TVA = TTC (accounting identity)', () => {
      const items = [
        cartItem({ unitPriceInMicrounits: 150000000 as any, taxRate: '0.20' }),
        cartItem({ unitPriceInMicrounits: 80000000 as any, taxRate: '0.055' }),
      ];
      const totals = TaxCalculator.calculateTotals(items);
      expect(totals.totalHTInMicrounits + totals.totalTVAInMicrounits).toBe(totals.totalTTCInMicrounits);
    });

    it('applies discounts to TTC', () => {
      const items = [cartItem({ discountInMicrounits: 20000000 as any })];
      const totals = TaxCalculator.calculateTotals(items);
      expect(totals.totalTTCInMicrounits).toBe(100000000); // 12€ - 2€ = 10€
    });

    it('returns zeros for empty cart', () => {
      const totals = TaxCalculator.calculateTotals([]);
      expect(totals.totalTTCInMicrounits).toBe(0);
      expect(totals.totalTVAInMicrounits).toBe(0);
      expect(totals.totalHTInMicrounits).toBe(0);
    });
  });
});

