  config: z.record(z.string(), z.unknown()).optional()
});

const PluginDeleteSchema = z.object({
  tenantId: z.string().min(1),
  pluginId: z.string().min(1)
});

export async function GET(req: NextRequest): Promise<NextResponse> {
  const caller = await requireMccLevel(req, 'mcc_support');
  if (isDenied(caller)) return caller as NextResponse;

  const tenantId = req.nextUrl.searchParams.get('tenantId');

  // Fetch dynamic catalog
  const catalogDoc = await Nexus.adapter.get('mcc/empire/plugin-catalog') as { items?: Record<string, any> } | null;
  const dynamicCatalog = catalogDoc?.items || {};

  if (!tenantId) return NextResponse.json({ catalog: dynamicCatalog });

  const config = await Nexus.adapter.get(`tenants/${tenantId}/tenantConfig`) as { plugins?: Record<string, any> } | null;
  return NextResponse.json({ tenantId, activePlugins: config?.plugins || {}, catalog: dynamicCatalog });
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const caller = await requireMccLevel(req, 'fleet_admin');
  if (isDenied(caller)) return caller as NextResponse;

  let body: z.infer<typeof PluginPostSchema>;
  try {
    body = PluginPostSchema.parse(await req.json());
  } catch (err) {
    return NextResponse.json({ error: 'Validation failed', details: err }, { status: 400 });
  }

  const { tenantId, pluginId, config = {} } = body;

  // Verify plugin exists in dynamic catalog
  const catalogDoc = await Nexus.adapter.get('mcc/empire/plugin-catalog') as { items?: Record<string, any> } | null;
  const pluginInfo = catalogDoc?.items?.[pluginId];

  if (!pluginInfo) {
    return NextResponse.json({ error: 'Plugin not found in catalog' }, { status: 404 });
  }

  // Retrieve current config to log the 'before' state
  const currentConfig = await Nexus.adapter.get(`tenants/${tenantId}/tenantConfig`) as { plugins?: Record<string, any> } | null;
  const beforePlugins = currentConfig?.plugins || {};

  const pluginPayload = {
    active: true,
    activatedAt: new Date().toISOString(),
    config
  };

  // Merge deeply into tenantConfig
  await Nexus.adapter.set(
    `tenants/${tenantId}/tenantConfig`,
    { plugins: { [pluginId]: pluginPayload } },
    { merge: true }
  );

  // TODO: Trigger a billing recalculation/proration event here if necessary

  await ChangelogService.record({
    tenantId,
    action: 'PLUGIN_ACTIVATED',
    key: `plugins.${pluginId}`,
    before: beforePlugins[pluginId] || null,
    after: pluginPayload,
    description: `Activation du module ${pluginInfo.name} par ${caller.uid}`,
    appliedBy: caller.uid,
    scope: 'tenant',
  });

  logger.info(`[PluginEngine] Plugin ${pluginId} activé sur ${tenantId} par ${caller.uid}`);
  return NextResponse.json({ success: true, tenantId, pluginId, payload: pluginPayload });
}

export async function DELETE(req: NextRequest): Promise<NextResponse> {
  const caller = await requireMccLevel(req, 'fleet_admin');
  if (isDenied(caller)) return caller as NextResponse;

  let body: z.infer<typeof PluginDeleteSchema>;
  try {
    body = PluginDeleteSchema.parse(await req.json());
  } catch (err) {
    return NextResponse.json({ error: 'Validation failed', details: err }, { status: 400 });
  }

  const { tenantId, pluginId } = body;

  const currentConfig = await Nexus.adapter.get(`tenants/${tenantId}/tenantConfig`) as { plugins?: Record<string, any> } | null;
  const beforePlugins = currentConfig?.plugins || {};

  // We set active: false rather than deleting the key to preserve history and config
  const pluginPayload = {
    ...(beforePlugins[pluginId] || {}),
    active: false,
    deactivatedAt: new Date().toISOString()
  };

  await Nexus.adapter.set(
    `tenants/${tenantId}/tenantConfig`,
    { plugins: { [pluginId]: pluginPayload } },
    { merge: true }
  );

  await ChangelogService.record({
    tenantId,
    action: 'PLUGIN_DEACTIVATED',
    key: `plugins.${pluginId}`,
    before: beforePlugins[pluginId] || null,
    after: pluginPayload,
    description: `Désactivation du module ${pluginId} par ${caller.uid}`,
    appliedBy: caller.uid,
    scope: 'tenant',
  });

  logger.info(`[PluginEngine] Plugin ${pluginId} désactivé sur ${tenantId} par ${caller.uid}`);
  return NextResponse.json({ success: true, tenantId, pluginId });
}

/**
 * POST /api/admin/hr/payroll/provider/connect
 * Connecte un provider paie field-based (Silae, PayFit, ADP…).
 * Les providers OAuth (Merge.dev) utilisent leurs propres routes link-token/exchange.
 *
 * Body : { provider: string, fields: Record<string, string> }
 * - Construit la PayrollProviderConfig à partir des champs
 * - Appelle connector.ping() pour valider la connexion
 * - Persiste dans tenants/{id}/settings/payroll si ok
 */
import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { PayrollConnectorFactory } from '@/modules/human/connectors/payroll/PayrollConnectorFactory';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

export async function POST(req: NextRequest): Promise<NextResponse> {
    const caller = await requireTenantAdmin(req);
    if (isDenied(caller)) return caller as NextResponse;

    const { provider, fields } = await req.json() as {
        provider?: string;
        fields?: Record<string, string>;
    };

    if (!provider) {
        return NextResponse.json({ error: 'provider requis' }, { status: 400 });
    }

    let connector;
    try {
        connector = PayrollConnectorFactory.get(provider);
    } catch {
        return NextResponse.json(
            { error: `Provider inconnu : "${provider}". Disponibles : ${PayrollConnectorFactory.list().join(', ')}` },
            { status: 400 },
        );
    }

    // Construire la config depuis les champs du formulaire
    const config = { provider, ...(fields ?? {}) };

    // Vérifier la connexion avant de sauvegarder (réinstancier avec la config fournie)
    // On re-get pour que le provider utilise les bonnes credentials (via env ou config)
    // Pour les providers qui lisent les credentials depuis process.env, le ping réussira
    // si les env vars sont correctement définies. Les fields sont stockés et lus au prochain init.
    const ping = await connector.ping();
    if (!ping.ok) {
        return NextResponse.json({
            error: `Connexion ${provider} échouée — vérifiez vos identifiants`,
        }, { status: 422 });
    }

    // Sauvegarder dans Nexus
    const path = Nexus.getTenantPath('settings/payroll', caller.tenantId);
    await Nexus.adapter.set(path, {
        ...config,
        connectedAt: new Date().toISOString(),
        ...(ping.info ? { providerInfo: ping.info } : {}),
    }, { merge: true });

    logger.info('[HR/Payroll] Provider connecté', {
        tenantId: caller.tenantId,
        provider,
        info: ping.info,
    });

    return NextResponse.json({
        success: true,
        provider,
        info: ping.info,
        message: `${provider} connecté${ping.info ? ` — ${ping.info}` : ''}`,
    });
}

/**
 * POST /api/admin/hr/payroll/provider/sync
 * Synchronise une période pré-paie via le provider configuré pour ce tenant.
 * Agnostique : lit provider depuis tenants/{id}/settings/payroll, route via factory.
 *
 * Body : { periode: 'YYYY-MM' }
 */
import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { PayrollConnectorFactory } from '@/modules/human/connectors/payroll/PayrollConnectorFactory';
import { PrepaieBuilder } from '@/modules/human/remuneration/payroll/PrepaieBuilder';
import type { PayrollProviderConfig } from '@/modules/human/remuneration/payroll/types';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

export async function POST(req: NextRequest): Promise<NextResponse> {
    const caller = await requireTenantAdmin(req);
    if (isDenied(caller)) return caller as NextResponse;

    const { periode } = await req.json() as { periode?: string };
    const month = periode ?? new Date().toISOString().slice(0, 7);

    if (!/^\d{4}-\d{2}$/.test(month)) {
        return NextResponse.json({ error: 'periode must be YYYY-MM' }, { status: 400 });
    }

    const configPath = Nexus.getTenantPath('settings/payroll', caller.tenantId);
    const config = await Nexus.adapter.get<PayrollProviderConfig>(configPath);
    const providerId = config?.provider ?? process.env.PAYROLL_DEFAULT_PROVIDER;

    if (!providerId) {
        return NextResponse.json({
            error: 'Aucun provider paie configuré — connectez un prestataire dans Paramètres > Paie',
        }, { status: 422 });
    }

    let connector;
    try {
        connector = PayrollConnectorFactory.get(providerId);
    } catch {
        return NextResponse.json(
            { error: `Provider "${providerId}" inconnu. Vérifiez la configuration.` },
            { status: 422 },
        );
    }

    try {
        const summary = await PrepaieBuilder.build(caller.tenantId, month);
        const result = await connector.syncPeriod(summary);

        const periodPath = Nexus.getTenantPath(`payrollPeriods/${month}`, caller.tenantId);
        await Nexus.adapter.set(periodPath, {
            ...summary,
            provider: connector.id,
            syncStatus: result.success ? 'synced' : 'error',
            syncedAt: new Date().toISOString(),
            syncErrors: result.errors,
        }, { merge: true });

        logger.info(`[HR/Payroll] Sync ${month} via ${connector.id}`, {
            tenantId: caller.tenantId,
            ...result,
        });

        return NextResponse.json({
            success: result.success,
            provider: connector.id,
            periode: month,
            employeesUpserted: result.employeesUpserted,
            variablesAccepted: result.variablesAccepted,
            errors: result.errors,
        });
    } catch (err) {
        logger.error('[HR/Payroll] Sync failed', err);
        return NextResponse.json({ error: 'Erreur interne lors de la synchronisation' }, { status: 500 });
    }
}

