    }

    const verified = p.verifySignature
        ? await p.verifySignature(rawBody, req.headers)
        : checkFallbackWebhookSecret(req.headers, providerId);

    if (!verified) {
        logger.warn(`[reservations/webhook] Signature invalide — provider=${providerId}`);
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    if (!p.verifySignature && !process.env.CONNECTORS_WEBHOOK_SECRET) {
        logger.warn(`[reservations/webhook] provider=${providerId} sans HMAC et sans CONNECTORS_WEBHOOK_SECRET — webhook non sécurisé`);
    }

    try {
        const reservation = p.onCreate(payload);

        if (!reservation.tenantId) {
            logger.warn('[reservations/webhook] tenantId manquant dans le payload', providerId);
            return NextResponse.json({ error: 'tenantId requis dans le payload' }, { status: 422 });
        }

        // Idempotency check: si une réservation avec le même externalId existe déjà
        if (reservation.externalId) {
            const existing = await Nexus.adapter.query<{ id: string; status?: string }>(
                `tenants/${reservation.tenantId}/reservations`,
                { where: [{ field: 'externalId', operator: '==', value: reservation.externalId }] }
            );
            if (existing && existing.length > 0) {
                const existingRes = existing[0];
                // Si le statut n'a pas changé, c'est un doublon pur
                if (existingRes.status === reservation.status) {
                    logger.info(`[reservations/webhook] Doublon détecté provider=${providerId} externalId=${reservation.externalId}`);
                    return NextResponse.json({ received: true, duplicate: true, id: existingRes.id });
                }
                // Statut différent : mise à jour de la réservation existante
                await Nexus.adapter.update(
                    `tenants/${reservation.tenantId}/reservations/${existingRes.id}`,
                    { ...reservation, updatedAt: Date.now() }
                );
                logger.info(`[reservations/webhook] Mise à jour via webhook provider=${providerId} id=${existingRes.id}`);
                return NextResponse.json({ received: true, updated: true, id: existingRes.id });
            }
        }

        await Nexus.adapter.set(
            `tenants/${reservation.tenantId}/reservations/${reservation.id}`,
            reservation
        );

        logger.info(`[reservations/webhook] provider=${providerId} id=${reservation.id} tenant=${reservation.tenantId}`);
        return NextResponse.json({ received: true, id: reservation.id });
    } catch (err) {
        logger.error(`[reservations/webhook] provider=${providerId}`, err);
        return NextResponse.json({ error: 'Erreur interne' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { Resend } from 'resend';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

const resend = process.env.RESEND_API_KEY ? new Resend(process.env.RESEND_API_KEY) : null;
const FROM_EMAIL = process.env.RESEND_FROM_EMAIL ?? 'noreply@restaurant-os.app';

const AutomationConfigSchema = z.object({
    enabled: z.boolean(),
    delayDays: z.number().int().min(0).max(365),
    subject: z.string().min(1).max(200),
    body: z.string().min(1),
});

const BodySchema = z.object({
    automation: z.enum(['birthday', 'winback', 'postvisit']),
    config: AutomationConfigSchema,
});

interface Customer {
    id: string;
    email?: string;
    firstName?: string;
    lastName?: string;
    lastVisitDate?: string;
    birthDate?: string;
}

function interpolate(template: string, vars: Record<string, string>): string {
    return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? '');
}

function isBirthdayToday(birthDate?: string): boolean {
    if (!birthDate) return false;
    const today = new Date();
    const bd = new Date(birthDate);
    return bd.getMonth() === today.getMonth() && bd.getDate() === today.getDate();
}

function daysSince(date?: string): number {
    if (!date) return 9999;
    return Math.floor((Date.now() - new Date(date).getTime()) / 86_400_000);
}

export async function POST(req: NextRequest) {
    const auth = await requireTenantAdmin(req);
    if (isDenied(auth)) return auth;

    const parsed = BodySchema.safeParse(await req.json().catch(() => null));
    if (!parsed.success) {
        return NextResponse.json({ error: 'Payload invalide' }, { status: 400 });
    }

    // tenantId vient TOUJOURS du token (SovereignGuard) — jamais du body client
    const tenantId = auth.tenantId;
    const { automation, config } = parsed.data;

    let targets: Array<Customer & { email: string }> = [];

    if (automation === 'birthday') {
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {});
        targets = raw
            .filter((c): c is Customer & { email: string } => !!c.email)
            .filter(c => isBirthdayToday(c.birthDate));
    } else if (automation === 'winback') {
        const cutoff = new Date(Date.now() - config.delayDays * 86_400_000).toISOString();
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {
            where: [{ field: 'lastVisitDate', operator: '<=', value: cutoff }],
        });
        targets = raw.filter((c): c is Customer & { email: string } => !!c.email);
    } else if (automation === 'postvisit') {
        const delay = config.delayDays;
        const windowStart = new Date(Date.now() - (delay + 1) * 86_400_000).toISOString();
        const windowEnd = new Date(Date.now() - delay * 86_400_000).toISOString();
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {
            where: [
                { field: 'lastVisitDate', operator: '>=', value: windowStart },
                { field: 'lastVisitDate', operator: '<', value: windowEnd },
            ],
        });
        targets = raw.filter((c): c is Customer & { email: string } => !!c.email);
    }

    if (!targets.length) {
        return NextResponse.json({ sent: 0, message: 'Aucun client ciblé pour ce scénario' });
    }

    if (!resend) {
        logger.warn('[automations/run] RESEND_API_KEY not set — skipping real send');
        return NextResponse.json({ sent: targets.length, dry: true });
    }

    const BATCH = 50;
    let sent = 0;

    for (let i = 0; i < targets.length; i += BATCH) {
        const batch = targets.slice(i, i + BATCH);
        try {
            await resend.batch.send(
                batch.map(c => ({
                    from: FROM_EMAIL,
                    to: c.email!,
                    subject: interpolate(config.subject, { firstName: c.firstName ?? 'cher client', delayDays: String(config.delayDays) }),
                    text: interpolate(config.body, { firstName: c.firstName ?? 'cher client', delayDays: String(config.delayDays) }),
                }))
            );
            sent += batch.length;
        } catch (err) {
            logger.error('[automations/run] Batch error', err);
        }
    }

    logger.info(`[automations/run] ${automation}: ${sent}/${targets.length} emails sent for tenant ${tenantId}`);
    return NextResponse.json({ sent });
}

import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/axiom';

/**
 * 🔗 API: Mock OAuth 2.0 pour la connexion UberEats / Deliveroo
 * 
 * Dans la vraie vie : 
 * 1. Redirige vers https://auth.uber.com/oauth/v2/authorize
 * 2. Reçoit le code de callback
 * 3. Échange le code contre un AccessToken
 * 4. Sauvegarde dans Firestore
 */
export async function POST(req: NextRequest) {
  // Seul un administrateur peut connecter une plateforme
  const caller = await requireTenantRole(req, 'manager');
  if (isDenied(caller)) return caller;

  try {
    const body = await req.json();
    const { platform, storeId } = body; // ex: 'ubereats', 'store_123'

    if (platform !== 'ubereats' && platform !== 'deliveroo') {
        return NextResponse.json({ error: 'Plateforme non supportée.' }, { status: 400 });
    }

    const tenantId = caller.tenantId;

    logger.info(`[OAuth Mock] Connexion de la plateforme ${platform} demandée par ${caller.uid} (Tenant: ${tenantId})`);

    // Génération d'une intégration active (Mock)
    const integrationId = `int_${platform}_${Date.now()}`;
    const integrationData = {
        id: integrationId,
        platform,
        isActive: true,
        storeId: storeId || 'mock_store_999',
        connectedAt: new Date().toISOString(),
        connectedBy: caller.uid,
        mappings: [
            // On injecte un faux mapping pour l'exemple
            { id: 'prod_burger_maison', externalId: `item_${platform}_888` }
        ]
    };

    // Sauvegarde dans la base de données
    // @ts-ignore
    await Nexus.adapter.create(`tenants/${tenantId}/integrations`, integrationData);

    logger.info(`[OAuth Mock] Intégration ${platform} réussie et enregistrée.`);

    return NextResponse.json({ 
        success: true, 
        message: `${platform} a été connecté avec succès.`,
        integration: integrationData
    });

  } catch (error) {
    logger.error('[OAuth Mock] Erreur lors de la connexion', { error: String(error) });
    return NextResponse.json({ error: 'Erreur interne' }, { status: 500 });
  }
}

/**
 * Reservations API — res-arch-1 : Architecture biface
 *
 * Surface BACKOFFICE (employés) :
 *   GET  /api/reservations?date=YYYY-MM-DD  — liste jour (requireTenantUser)
 *   POST /api/reservations                  — création interne (requireTenantUser)
 *   PATCH /api/reservations?id=xxx          — mise à jour statut/table (requireTenantUser)
 *
 * Surface WIDGET PUBLIC :
 *   POST /api/widget/book         — réservation client externe (sans auth)
 *   GET  /api/widget/availability — créneaux libres (sans auth)
 *
 * Cette route gère la surface interne (backoffice).
 * La surface publique est dans /api/widget/* (rate-limitée, sans auth).
 *
 * Règles :
 *   - jamais de cross-tenant : tenantId TOUJOURS depuis le token
 *   - statuts valides : 'pending' | 'confirmed' | 'arrived' | 'completed' | 'cancelled' | 'no_show'
 */
import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

type ReservationStatus = 'pending' | 'confirmed' | 'arrived' | 'completed' | 'cancelled' | 'no_show';
const VALID_STATUSES: ReservationStatus[] = ['pending', 'confirmed', 'arrived', 'completed', 'cancelled', 'no_show'];

const CreateReservationSchema = z.object({
  date:         z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Format YYYY-MM-DD requis'),
  time:         z.string().regex(/^\d{2}:\d{2}$/, 'Format HH:MM requis'),
  covers:       z.number().int().min(1).max(200),
  customerName: z.string().min(1).max(100).trim(),
  phone:        z.string().max(30).optional(),
  email:        z.string().email().max(254).optional(),
  notes:        z.string().max(500).optional(),
  tableId:      z.string().max(80).optional(),
});

const PatchReservationSchema = z.object({
  status:  z.enum(['pending', 'confirmed', 'arrived', 'completed', 'cancelled', 'no_show']).optional(),
  tableId: z.string().max(80).optional(),
  notes:   z.string().max(500).optional(),
});

export async function GET(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const date = req.nextUrl.searchParams.get('date');

  const all = await Nexus.adapter.query(`tenants/${tenantId}/reservations`) as Array<{ date?: string }>;
  const filtered = date ? all.filter(r => r.date === date) : all;

  return NextResponse.json({ reservations: filtered, date: date ?? 'all', total: filtered.length });
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const raw = await req.json().catch(() => null);
  const parsed = CreateReservationSchema.safeParse(raw);
  if (!parsed.success) {
    return NextResponse.json({ error: 'Données invalides', details: parsed.error.flatten() }, { status: 400 });
  }
  const { date, time, covers, customerName, phone, email, notes, tableId } = parsed.data;

  const id = Nexus.adapter.generateId(`tenants/${tenantId}/reservations`);
  const reservation = {
    id,
    date,
    time,
    covers,
    customerName,
    ...(phone   ? { phone }   : {}),
    ...(email   ? { email }   : {}),
    ...(notes   ? { notes }   : {}),
    ...(tableId ? { tableId } : {}),
    status:        'confirmed' as ReservationStatus,
    source:        'backoffice',
    schemaVersion: 2,
    createdAt:     new Date().toISOString(),
    updatedAt:     Date.now(),
  };

  await Nexus.adapter.set(`tenants/${tenantId}/reservations/${id}`, reservation);

  logger.info(`[Reservations] Réservation backoffice ${id} créée — ${customerName} le ${date}`);
  return NextResponse.json({ success: true, reservation });
}

export async function PATCH(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const id = req.nextUrl.searchParams.get('id');
  if (!id) return NextResponse.json({ error: 'id requis' }, { status: 400 });

  const rawPatch = await req.json().catch(() => null);
  const patchParsed = PatchReservationSchema.safeParse(rawPatch);
  if (!patchParsed.success) {
    return NextResponse.json({ error: 'Données invalides', details: patchParsed.error.flatten() }, { status: 400 });
  }
  const { status, tableId, notes } = patchParsed.data;

  const update: Record<string, unknown> = { updatedAt: Date.now() };
  if (status  !== undefined) update.status  = status;
  if (tableId !== undefined) update.tableId = tableId;
  if (notes   !== undefined) update.notes   = notes;

  await Nexus.adapter.set(`tenants/${tenantId}/reservations/${id}`, update, { merge: true });

  logger.info(`[Reservations] Réservation ${id} mise à jour — status: ${status ?? 'inchangé'}`);
  return NextResponse.json({ success: true, id, updated: patchParsed.data });
}

import { NextRequest, NextResponse } from 'next/server';
