export interface ArchitecturalHealthReport {
  timestamp: string;
  grade: 'X+++' | 'X' | 'B' | 'C' | 'CRITICAL';
  metrics: {
    anyCount: number;
    graphCycles: number;
    godNodes: string[];
    silentServices: number;
    unprotectedAdminRoutes: string[];
    scratchImports: number;
    financialIntegrity: boolean;
    sovereignMathCompliance: boolean;
  };
  blockers: Array<{ code: string; description: string; file: string }>;
  warnings: Array<{ code: string; description: string; file: string }>;
}

export class ArchitecturalHealthService {
    static async generateReport(): Promise<ArchitecturalHealthReport> {
        const unprotectedAdminRoutes: string[] = [];

        try {
            if (typeof window === 'undefined') {
                const fs = await import('fs');
                const path = await import('path');

                // Scan statique simple de src/app/api/admin (P09-K)
                const apiAdminPath = path.join(process.cwd(), 'src/app/api/admin');
                if (fs.existsSync(apiAdminPath)) {
                    const walkSync = (dir: string, filelist: string[] = []) => {
                        const files = fs.readdirSync(dir);
                        for (const file of files) {
                            const filepath = path.join(dir, file);
                            if (fs.statSync(filepath).isDirectory()) {
                                walkSync(filepath, filelist);
                            } else if (file.endsWith('route.ts')) {
                                filelist.push(filepath);
                            }
                        }
                        return filelist;
                    };

                    const routes = walkSync(apiAdminPath);
                    for (const route of routes) {
                        // Routes machine-to-machine exemptées (pas de session utilisateur)
                        if (route.includes('telemetry')) continue;
                        const content = fs.readFileSync(route, 'utf-8');
                        if (!content.includes('requireFleetAdmin') &&
                            !content.includes('requireTenantAdmin') &&
                            !content.includes('requireMccLevel') &&
                            !content.includes('requireTenantRole')) {
                            unprotectedAdminRoutes.push(route.replace(process.cwd(), ''));
                        }
                    }
                }
            }
        } catch (e) {
            // Ignorer en cas d'erreur de filesystem (ex: edge runtime)
        }

        const grade = unprotectedAdminRoutes.length > 0 ? 'CRITICAL' : 'X+++';

        return {
            timestamp: new Date().toISOString(),
            grade,
            metrics: {
                anyCount: 0,
                graphCycles: 0,
                godNodes: [],
                silentServices: 0,
                unprotectedAdminRoutes,
                scratchImports: 0,
                financialIntegrity: true,
                sovereignMathCompliance: true,
            },
            blockers: unprotectedAdminRoutes.map(file => ({
                code: 'UNPROTECTED_ADMIN_ROUTE',
                description: 'Une route admin critique ne vérifie pas le RBAC via adminAuthGuard',
                file
            })),
            warnings: [],
        };
    }
}

import type { CommunicationPulse } from '@/modules/finance/tresorerie/collection/types';

/**
 * 📡 CommunicationService
 * Gère l'envoi de messages transactionnels (Email, SMS) indépendamment du Bridge.
 */
export class CommunicationService {
    /**
     * 🖋️ Suture GRADE X+++: Emission CommunicationPulse (Email/SMS)
     */
    static async sendCommunicationPulse(pulse: CommunicationPulse): Promise<void> {
        const { sendEmail } = await import('@/infrastructure/services/email-service');

        // Handle EMAIL and MIXED types (SMS would need separate provider)
        if (pulse.type === 'EMAIL' || pulse.type === 'MIXED') {
            try {
                const result = await sendEmail({
                    to: pulse.recipient,
                    subject: pulse.subject,
                    html: pulse.content
                });

                if (result.success) {
                    // Track successful send in local audit log
                    const { logger } = await import('@/lib/logger');
                    logger.info('[CommunicationPulse] Email sent', {
                        recipient: pulse.recipient,
                        type: pulse.type,
                        messageId: result.messageId
                    });
                } else {
                    throw new Error(result.error || 'Email send failed');
                }
            } catch (error) {
                const { logger } = await import('@/lib/logger');
                logger.error('[CommunicationPulse] Failed to send email', {
                    recipient: pulse.recipient,
                    type: pulse.type,
                    error: error instanceof Error ? error.message : String(error)
                });
            }
        }
    }
}

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

export class FleetOutboxDrainService {
    /**
     * Draine l'outbox d'un tenant spécifique et propage les événements
     * vers la file globale de la flotte (MCC).
     */
    static async drainTenant(tenantId: string): Promise<number> {
        let count = 0;
        try {
            // Note: with NexusAdapter, we query the tenant's collection directly
            const pendingEvents = await Nexus.adapter.query<{ id: string; type: string; payload: any; timestamp: string }>(`tenants/${tenantId}/mcc_outbox`, {
                where: [
                    { field: 'status', operator: '==', value: 'pending' }
                ],
                limit: 50
            });

            for (const event of pendingEvents) {
                // 1. Inscrire dans la file globale MCC
                await Nexus.adapter.create('mcc/globalEvents', {
                    tenantId,
                    eventType: event.type,
                    payload: event.payload,
                    sourceTimestamp: event.timestamp,
                    dispatchedAt: new Date().toISOString()
                });

                // 2. Marquer l'événement comme dispatché dans l'outbox locale
                await Nexus.adapter.update(`tenants/${tenantId}/mcc_outbox/${event.id}`, {
                    status: 'dispatched',
                    dispatchedAt: Date.now()
                });

                count++;
            }

            if (count > 0) {
                logger.info(`[FleetOutboxDrain] Successfully drained ${count} events for tenant ${tenantId}`);
            }
        } catch (error) {
            logger.error(`[FleetOutboxDrain] Error draining outbox for tenant ${tenantId}`, String(error));
        }
        return count;
    }
}

import type { CartItem } from '@/modules/ops/workflow/engine/types';

export class TaxCalculator {
  static computeTvaBreakdown(items: CartItem[]): Record<string, number> {
    const breakdown: Record<string, number> = {};
    for (const item of items) {
      const rate = item.taxRate ?? '0.10';
      const rateNum = parseFloat(rate);
      // Prix stockés TTC (norme restauration FR) : TVA = TTC × r/(1+r)
      const lineTTC = item.unitPriceInMicrounits * item.quantity - (item.discountInMicrounits ?? 0);
      const tva = Math.round(lineTTC * rateNum / (1 + rateNum));
      breakdown[rate] = (breakdown[rate] ?? 0) + tva;
    }
    return breakdown;
  }

  static calculateTotals(cartItems: CartItem[]) {
    const totalTTCInMicrounits = cartItems.reduce(
      (acc, item) =>
        acc +
        item.unitPriceInMicrounits * item.quantity -
        (item.discountInMicrounits ?? 0),
      0
    );
    const tvaBreakdown = this.computeTvaBreakdown(cartItems);
    const totalTVAInMicrounits = Object.values(tvaBreakdown).reduce(
      (a, b) => a + b,
      0
    );
    const totalHTInMicrounits = totalTTCInMicrounits - totalTVAInMicrounits;

    return {
      totalTTCInMicrounits,
      totalTVAInMicrounits,
      totalHTInMicrounits,
      tvaBreakdown
    };
  }
}

import { db, SyncOperation } from './offline-store';
import { checkOnlineStatus } from './connectivity-hooks';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/axiom';

/**
 * 🔄 SyncManager - Restaurant OS
 * Gère la file d'attente de synchronisation entre la base locale et Firestore.
 */
async function executeMutationOp(op: SyncOperation): Promise<void> {
    const fullPath = op.collection + (op.targetId ? `/${op.targetId}` : '');
    if (op.action === 'CREATE') {
        await Nexus.adapter.create(op.collection, op.payload);
    } else if (op.action === 'DELETE') {
        await Nexus.adapter.delete(fullPath);
    } else if (op.action === 'SET') {
        await Nexus.adapter.set(fullPath, op.payload);
    } else if (op.action === 'UPDATE') {
        await Nexus.adapter.update(fullPath, op.payload as Partial<import('@/shared/nexus-contract').SovereignData>);
    }
}

async function executeFallbackOp(op: SyncOperation): Promise<void> {
    const fullPath = `${op.collection}/${op.targetId}`;
    if (op.action === 'SET') await Nexus.adapter.set(fullPath, op.payload);
    if (op.action === 'UPDATE') await Nexus.adapter.update(fullPath, op.payload as Partial<import('@/shared/nexus-contract').SovereignData>);
}

export class SyncManager {
    private static isSyncing = false;

    /** Au-delà : on continue de retenter (jamais de drop fiscal) mais on loggue en critique. */
    private static readonly ALERT_ATTEMPTS = 10;

    /**
     * Ajoute une opération à la file d'attente et tente une synchro si possible.
     */
    static async enqueue(op: Omit<SyncOperation, 'status' | 'attempts' | 'timestamp'>) {
        const newOp: SyncOperation = {
            ...op,
            status: 'pending',
            attempts: 0,
            timestamp: new Date().toISOString(),
            // ⚠️ 'NF525_PAYMENT' ne contient pas « FISCAL » : l'ancien calcul
            // (op.type.includes('FISCAL')) classait les paiements en priorité 0.
            priority: op.priority ?? (
                op.type === 'NF525_PAYMENT' || op.type === 'NF525_JET' || op.type === 'FISCAL_SEAL' || op.type === 'JOURNAL_ENTRY' ? 1 : 0
            )
        };

        const id = await db.syncQueue.add(newOp);
        logger.info('SyncManager: Operation enqueued', { id, type: op.type });

        // Tenter une synchro immédiate si online
        if (checkOnlineStatus()) {
            this.processQueue();
        } else {
            // Tenter d'enregistrer le tag Background Sync pour quand le réseau reviendra
            if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
                navigator.serviceWorker.ready.then(registration => {
                    if ('sync' in registration) {
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        (registration as any).sync.register('restaurant-os-sync').catch(() => {});
                    }
                }).catch(() => {});
            }
        }
    }

    /**
     * Traite tous les éléments en attente dans la SyncQueue.
     */
    static async processQueue() {
        if (this.isSyncing) return;

        // ⚠️ Rejouer AUSSI les 'failed' : les laisser de côté = ticket NF525
        // perdu au premier échec. Une op fiscale n'est JAMAIS abandonnée.
        const pendingOps = (await db.syncQueue
            .where('status')
            .anyOf('pending', 'failed')
            .toArray())
            // Fiscal (priority 1) d'abord, puis ordre chronologique (chaîne de sceaux).
            .sort((a, b) => (b.priority - a.priority) || a.timestamp.localeCompare(b.timestamp));

        if (pendingOps.length === 0) return;

        this.isSyncing = true;
        logger.info('SyncManager: Starting synchronization process', { count: pendingOps.length });

        for (const op of pendingOps) {
            try {
                await this.executeOperation(op);
                // Mark as synced and delete from queue if successful
                await db.syncQueue.delete(op.id!);
                logger.info('SyncManager: Operation synced and removed', { id: op.id, type: op.type });
            } catch (error) {
                const err = error as Error;
                const errorMessage = err.message || String(error);
                logger.error('SyncManager: Sync failed for operation', { id: op.id, error: errorMessage });

                await db.syncQueue.update(op.id!, {
                    status: 'failed',
                    attempts: op.attempts + 1,
                    lastError: errorMessage
                });

                if (op.attempts + 1 >= this.ALERT_ATTEMPTS) {
                    logger.error('SyncManager: CRITICAL — operation stuck after repeated attempts', {
                        id: op.id, type: op.type, attempts: op.attempts + 1
                    });
                }

                // Si c'est une erreur de connexion, on arrête la boucle
                if (!checkOnlineStatus()) break;
            }
        }

        this.isSyncing = false;

        // Relancer si de nouveaux items PENDING sont arrivés entre temps.
        // (Les 'failed' attendent le prochain déclencheur — online/boot/enqueue —
        // pour éviter une boucle chaude de retries.)
        const remaining = await db.syncQueue.where('status').equals('pending').count();
        if (remaining > 0 && checkOnlineStatus()) {
            this.processQueue();
        }
    }

    /**
     * Exécute une opération spécifique vers Firestore.
     */
    private static async executeOperation(op: SyncOperation) {
        if (op.type === 'NF525_PAYMENT') {
            const payload = op.payload as { instructions: Array<{ method: string; path: string; data: import('@/shared/nexus-contract').SovereignData }> };
            const instructions = payload.instructions;

            // Idempotence : si le JournalEntry existe déjà (écriture partielle avant
            // déconnexion), on ne rejoue pas le batch — sinon double-scellement NF525.
            const journalInstruction = instructions.find(i => i.path.includes('/journalEntries/'));
            if (journalInstruction) {
                const existing = await Nexus.adapter.get(journalInstruction.path);
                if (existing) {
                    logger.info('SyncManager: NF525_PAYMENT déjà commité — skip replay', { path: journalInstruction.path });
                    return;
                }
            }

            // Call the sync API instead of writing directly, to perform server-side atomic sealing
            const journalEntries = instructions
                .filter(ins => ins.path.includes('/journalEntries/') && ins.method === 'SET')
                .map(ins => ins.data);

            if (journalEntries.length > 0) {
                // Extract tenantId from path (e.g. 'tenants/tenant-1/journalEntries/JE-123')
                const pathParts = instructions[0].path.split('/');
                const tenantId = pathParts[1];

                const response = await fetch('/api/finance/sync', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        tenantId,
                        journalEntries,
                        isTrainingMode: false,
                    }),
                });

                if (!response.ok) {
                    throw new Error(`Sync API failed: ${response.status} ${response.statusText}`);
                }
            }
        } else if (op.type === 'NF525_JET') {
            const payload = op.payload as import('@/shared/nexus-contract').SovereignData;
            const tenantId = op.collection.split('/')[1] || 'default';

            const response = await fetch('/api/finance/jet/sync', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    tenantId,
                    entries: [payload],
                }),
            });

            if (!response.ok) {
                throw new Error(`JET Sync API failed: ${response.status} ${response.statusText}`);
            }
        } else if (op.type === 'MUTATION') {
            await executeMutationOp(op);
        } else {
            await executeFallbackOp(op);
        }
    }
}

// Lancement automatique du manager lors du chargement (si en ligne)
export function bootSyncManager() {
    if (typeof window !== 'undefined') {
        window.addEventListener('online', () => SyncManager.processQueue());

        // Listen to Service Worker Background Sync triggers
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.addEventListener('message', (event) => {
                if (event.data && event.data.type === 'PROCESS_SYNC_QUEUE') {
                    logger.info('SyncManager: Background Sync triggered by Service Worker');
                    SyncManager.processQueue();
                }
            });
            // Register Background Sync if queuing happens
            navigator.serviceWorker.ready.then(registration => {
                // Background Sync registration happens inside SyncManager.enqueue now
            }).catch(() => {});
        }

        // On lance immédiatement la synchro au chargement
        SyncManager.processQueue();
    }
}

