import { FiscalKeyService } from '@/modules/finance/services/FiscalKeyService';
import { TenantConfig, DEFAULT_TENANT_CONFIG } from '@/shared/nexus-contract';
import { RESTAURANT_FULL_DNA } from '@shared/seeds/restaurant-full-dna';
import { logger } from '@/lib/logger';

// nexus-core ne doit pas dépendre de la couche config (règle sentrux) : on lit
// l'env directement plutôt que d'importer APP_MODE de @/config/instance.
const APP_MODE = process.env.NEXT_PUBLIC_APP_MODE || 'tenant';

interface LegacyTenantConfig {
  features?: Record<string, boolean>;
  layout?: string;
  laws?: Record<string, boolean>;
}

/** Donnée distante pouvant contenir des champs legacy pré-Grade-VIII. */
type RemoteConfigData = Partial<TenantConfig> & LegacyTenantConfig;

/**
 * 🛰️ NexusBridge - The Command Omphalos
 * Establishes a real-time, resilient link between the MCC and the OS.
 *
 * ⚠️ Cloud-agnostique : AUCUN import firebase/* ici. Toute I/O passe par
 * Nexus.adapter (Firestore / SQL / Mock interchangeables), donc par le
 * NexusInterceptor + SovereignGuard.
 */
function metadataDefaults(): { name: string; version: string; description: string; ownerId: string; createdAt: number; subscriptionTier: string } {
  const dna = RESTAURANT_FULL_DNA.metadata;
  const def = DEFAULT_TENANT_CONFIG.metadata;
  return {
    name: dna?.name || def.name,
    version: dna?.version || def.version,
    description: dna?.description || '',
    ownerId: dna?.ownerId || '',
    createdAt: dna?.createdAt || Date.now(),
    subscriptionTier: dna?.subscriptionTier || 'FREE',
  };
}

export class NexusBridge {
  private static unsubscribe: (() => void) | null = null;
  private static pulseInterval: ReturnType<typeof setInterval> | null = null;
  private static store = getDefaultStore();

  /** Cadence du pulse montant vers le MCC (le stream bufferise, flush ≤ 5 min). */
  private static readonly PULSE_INTERVAL_MS = 120_000;

  /**
   * Initialise le pont en chargeant la config locale (Dexie) 
   * puis en écoutant les signaux distants (Firestore).
   */
  static async init(tenantId: string) {
    if (!tenantId) return;


    // 1. Local-First Boot: Load from Dexie
    const localConfig = await db.config.get(tenantId) as (TenantConfig & LegacyTenantConfig & { fiscalSigningKey?: string }) | undefined;
    if (localConfig?.fiscalSigningKey) {
      // Clé de scellement NF525 provisionnée par tenant (voir FiscalKeyService).
      FiscalKeyService.provision(tenantId, localConfig.fiscalSigningKey);
    }
    if (localConfig) {
      this.store.set(tenantConfigAtom, {
        ...localConfig,
        // Ensure keys from Phase 1 exist if migrating from Grade VI
        capabilities: localConfig.capabilities || localConfig.features || {},
        status: {
          ...DEFAULT_TENANT_CONFIG.status,
          ...localConfig.status,
          businessLaws: localConfig.status?.businessLaws || {}
        }
      } as TenantConfig);
    } else {
      this.store.set(tenantConfigAtom, { ...RESTAURANT_FULL_DNA, id: tenantId });
    }

    // 2. Establish Real-time Connection — les DEUX sens du lien MCC ↔ instance :
    //    DOWN : décrets impériaux (tenants/{t}/config/master → onSnapshot)
    //    UP   : télémétrie de santé (fleet-telemetry/{t} ← pulse périodique)
    this.listen(tenantId);
    // MCC reads fleet telemetry — it never pushes its own pulse.
    if (APP_MODE === 'tenant') {
      this.startPulse(tenantId);
    }
  }

  /**
   * 🛰️ Flux MONTANT du Nexus Bridge : heartbeat instance → MCC.
   * Enregistre le nœud puis pousse santé/commandes/version toutes les 2 min.
   */
  static startPulse(tenantId: string) {
    this.stopPulse();
    if (typeof window === 'undefined') return; // pulse côté instance uniquement

    import('@modules/intelligence/ia/fleet/FleetTelemetryService')
      .then(({ fleetTelemetry }) => {
        fleetTelemetry.registerNode(tenantId as import('@domain/types/brands').TenantID);
      })
      .catch((err) => logger.warn('[NexusBridge] registerNode failed', { error: String(err) }));

    const push = () => this.pushPulse(tenantId);
    push();
    this.pulseInterval = setInterval(push, this.PULSE_INTERVAL_MS);
  }

  private static async pushPulse(tenantId: string): Promise<void> {
    try {
      const { fleetTelemetry } = await import('@modules/intelligence/ia/fleet/FleetTelemetryService');
      const { pendingOrdersAtom } = await import('@/store/pillars/ops');
      let activeOrders = 0;
      try {
        activeOrders = (this.store.get(pendingOrdersAtom) as unknown[])?.length ?? 0;
      } catch { /* atomes ops non chargés sur cette route (ICM) — pulse minimal */ }

      await fleetTelemetry.pushSiteTelemetry(tenantId as import('@domain/types/brands').TenantID, {
        status: 'ONLINE',
        lastHeartbeat: new Date().toISOString(),
        healthScore: 100,
        activeOrders,
        version: process.env.NEXT_PUBLIC_APP_VERSION ?? '0.1.0',
      });
    } catch (err) {
      logger.warn('[NexusBridge] Instance pulse failed', { error: String(err) });
    }
  }

  static stopPulse() {
    if (this.pulseInterval) {
      clearInterval(this.pulseInterval);
      this.pulseInterval = null;
    }
  }

  private static mapTheme(remoteData: RemoteConfigData): TenantConfig['theme'] {
      return { 
        primaryColor: remoteData.theme?.primaryColor || RESTAURANT_FULL_DNA.theme?.primaryColor || DEFAULT_TENANT_CONFIG.theme.primaryColor,
        secondaryColor: remoteData.theme?.secondaryColor || RESTAURANT_FULL_DNA.theme?.secondaryColor || DEFAULT_TENANT_CONFIG.theme.secondaryColor,
        logoUrl: remoteData.theme?.logoUrl || RESTAURANT_FULL_DNA.theme?.logoUrl || DEFAULT_TENANT_CONFIG.theme.logoUrl,
        borderRadius: remoteData.theme?.borderRadius || RESTAURANT_FULL_DNA.theme?.borderRadius || DEFAULT_TENANT_CONFIG.theme.borderRadius,
        appearance: remoteData.theme?.appearance || RESTAURANT_FULL_DNA.theme?.appearance || DEFAULT_TENANT_CONFIG.theme.appearance
      };
  }

  private static mapStatus(remoteData: RemoteConfigData): TenantConfig['status'] {
      return { 
        ...(RESTAURANT_FULL_DNA.status || DEFAULT_TENANT_CONFIG.status), 
        ...(remoteData.status || {}),
        layoutType: (remoteData.status?.layoutType || remoteData.layout || (RESTAURANT_FULL_DNA.status?.layoutType ?? 'default')) as unknown as string,
        businessLaws: (remoteData.status?.businessLaws || remoteData.laws || (RESTAURANT_FULL_DNA.status?.businessLaws ?? {})) as unknown as Record<string, unknown>
      };
  }

  private static mapMetadata(remoteData: RemoteConfigData): TenantConfig['metadata'] {
      const defaults = metadataDefaults();
      return {
        name: remoteData.metadata?.name || defaults.name,
        version: remoteData.metadata?.version || defaults.version,
        description: remoteData.metadata?.description || defaults.description,
        ownerId: remoteData.metadata?.ownerId || defaults.ownerId,
        createdAt: remoteData.metadata?.createdAt || defaults.createdAt,
        subscriptionTier: (remoteData.metadata?.subscriptionTier || defaults.subscriptionTier) as string,
      };
  }

  /**
   * Grade VIII Mapping: Accept everything, map to core structure
   */
  static mapRemoteConfig(remoteData: Partial<TenantConfig> & LegacyTenantConfig, tenantId: string): TenantConfig {
    return {
      id: tenantId,
      capabilities: remoteData.capabilities || remoteData.features || RESTAURANT_FULL_DNA.capabilities,
      theme: this.mapTheme(remoteData),
      status: this.mapStatus(remoteData),
      metadata: this.mapMetadata(remoteData),
    };
  }

  /**
   * Écoute les changements sur le document de configuration du tenant.
   * Grade VIII : Injection agnostique.
   */
  static listen(tenantId: string) {
    this.stop();

    // Abonnement via l'abstraction Nexus (cloud-agnostique, intercepté).
    this.unsubscribe = Nexus.adapter.onSnapshot<RemoteConfigData & { fiscalSigningKey?: string } | null>(
      `tenants/${tenantId}/config/master`,
      (remoteData) => {
        if (!remoteData) return;

        if (remoteData.fiscalSigningKey) {
          FiscalKeyService.provision(tenantId, remoteData.fiscalSigningKey);
        }

        const nextConfig = this.mapRemoteConfig(remoteData, tenantId);

        this.store.set(tenantConfigAtom, nextConfig);
        db.config.put(nextConfig);
      },
      { onError: (error) => logger.warn('[NexusBridge] Decree listener error', { error: String(error) }) }
    );
  }


  /**
   * 🖋️ Suture GRADE X+++: Emission CommunicationPulse (Email/SMS)
   * @deprecated Use CommunicationService.sendCommunicationPulse directly
   */
  static async sendCommunicationPulse(pulse: import('@/modules/finance/tresorerie/collection/types').CommunicationPulse) {
      const { CommunicationService } = await import('@/infrastructure/services/CommunicationService');
      return CommunicationService.sendCommunicationPulse(pulse);
  }

  static stop() {
    if (this.unsubscribe) {
      this.unsubscribe();
      this.unsubscribe = null;
    }
    this.stopPulse();
  }
}

import { INexusAdapter, INexusBatch, INexusTransaction, NexusContext } from './types';
import { SovereignData } from '@/shared/nexus-contract';
import { SovereignGuard } from '@/shared/nexus/guards/SovereignGuard';
import { NexusTelemetryService } from '@/shared/nexus/telemetry/NexusTelemetryService';
import { AuditPulseType } from '@/shared/nexus/telemetry/types';
import { NexusError, NexusErrorCode } from '@/shared/nexus/errors';
import { IQueryOptions } from '@/shared/nexus/contracts/infrastructure/storage.contracts';
import { auditService } from '@/modules/compliance/securite/audit/AuditService';

/**
 * 🛰️ NexusInterceptor - Grade X Middleware
 * Encapsulates SovereignGuard, Tenant Scoping, and NF525 Fiscal Compliance.
 * Shields raw adapters from complex business logic.
 */
export class NexusInterceptor implements INexusAdapter {
    constructor(
        private readonly adapter: INexusAdapter,
        private readonly guard: typeof SovereignGuard,
        private readonly tenantProvider: () => string | null
    ) {
        auditService.setNexus(this.adapter as any);
    }

    async get<T = unknown>(path: string, context?: NexusContext): Promise<T | null> {
        const ctx = this.ensureContext(context);
        return this.intercept('READ', path, ctx, () => this.adapter.get<T>(this.scopePath(path, ctx.vassalId)));
    }

    async query<T = unknown>(collectionPath: string, options?: IQueryOptions, context?: NexusContext): Promise<T[]> {
        const ctx = this.ensureContext(context);
        return this.intercept('READ', collectionPath, ctx, () =>
            this.adapter.query<T>(this.scopePath(collectionPath, ctx.vassalId), options)
        );
    }

    onSnapshot<T = unknown>(
        path: string, 
        callback: (data: T) => void, 
        options?: IQueryOptions & { onError?: (error: Error) => void },
        context?: NexusContext
    ): () => void {
        const ctx = this.ensureContext(context);

        // Guard-First Listener Pattern (Grade X+++ Security)
        // The adapter listener is NOT started until access validation completes.
        // This eliminates the race condition where data could transit before denial.
        let innerUnsubscribe: (() => void) | null = null;
        let isUnsubscribed = false;

        const initListener = async () => {
            // Step 1: Validate access BEFORE subscribing to any data (scoped path — même raison que intercept)
            const scopedForValidation = this.scopePath(path, ctx.vassalId);
            let access: { granted: boolean; reason?: string };
            try {
                access = await this.guard.validateAccessGradeX('READ', scopedForValidation, ctx);
            } catch (error: unknown) {
                this.emitDenial('READ', path, ctx, error instanceof Error ? error.message : 'VALIDATION_EXCEPTION');
                options?.onError?.(new NexusError(NexusErrorCode.ACCESS_DENIED, 'Access validation failed'));
                return; // No listener started, no data transmitted
            }

            // Step 2: If denied, emit denial and do NOT start the listener
            if (!access.granted) {
                this.emitDenial('READ', path, ctx, access.reason || 'ACCESS_DENIED');
                options?.onError?.(new NexusError(NexusErrorCode.ACCESS_DENIED, 'Access denied'));
                return; // No listener started, no data transmitted
            }

            // Step 3: If caller already unsubscribed while we were validating, bail out
            if (isUnsubscribed) return;

            // Step 4: Access granted — NOW start the real listener
            innerUnsubscribe = this.adapter.onSnapshot<T>(
                this.scopePath(path, ctx.vassalId),
                callback,
                options
            );
        };

        // Fire the init (no await — onSnapshot must return synchronously)
        initListener();

        // Return a stable unsubscribe that works even during validation
        return () => {
            isUnsubscribed = true;
            if (innerUnsubscribe) innerUnsubscribe();
        };
    }

    batch(): INexusBatch {
        const ctx = this.ensureContext();
        const rawBatch = this.adapter.batch();
        const ops: { type: string, path: string }[] = [];
        // ⚠️ validateAccess est ASYNC : l'appeler sans await dans ces closures
        // synchrones laissait passer TOUTE écriture batch (cross-tenant + NF525)
        // avec un rejet flottant. On accumule les gardes et on les attend au
        // commit, AVANT le rawBatch.commit — rien n'est écrit si une garde jette.
        const pendingGuards: Promise<unknown>[] = [];
        const pendingWrites: Array<() => Promise<void>> = [];

        return {
            set: (path, data) => {
                const scopedPath = this.scopePath(path, ctx.vassalId);
                pendingGuards.push(this.guard.validateAccess(scopedPath, ctx.vassalId));
                pendingWrites.push(async () => {
                    const protectedData = await this.guard.protectWrite(scopedPath, data as SovereignData, ctx.vassalId);
                    rawBatch.set(scopedPath, protectedData);
                });
                ops.push({ type: 'SET', path: scopedPath });
            },
            update: (path, data) => {
                const scopedPath = this.scopePath(path, ctx.vassalId);
                pendingGuards.push(this.guard.validateAccess(scopedPath, ctx.vassalId));
                pendingWrites.push(async () => {
                    const protectedData = await this.guard.protectWrite(scopedPath, data as SovereignData, ctx.vassalId);
                    rawBatch.update(scopedPath, protectedData as Partial<unknown>);
                });
                ops.push({ type: 'UPDATE', path: scopedPath });
            },
            increment: (path, field, amount) => {
                const scopedPath = this.scopePath(path, ctx.vassalId);
                pendingGuards.push(this.guard.validateAccess(scopedPath, ctx.vassalId));
                rawBatch.increment(scopedPath, field, amount);
                ops.push({ type: 'INCREMENT', path: scopedPath });
            },
            delete: (path) => {
                const scopedPath = this.scopePath(path, ctx.vassalId);
                if (!this.guard.canDelete(path)) {
                    throw new NexusError(NexusErrorCode.NF525_VIOLATION, 'Cannot delete a fiscally sealed document in batch');
                }
                pendingGuards.push(this.guard.validateAccess(scopedPath, ctx.vassalId));
                rawBatch.delete(scopedPath);
                ops.push({ type: 'DELETE', path: scopedPath });
            },
            commit: async () => {
                // Barrière de sécurité : toutes les gardes doivent passer avant l'écriture.
                await Promise.all(pendingGuards);
                await Promise.all(pendingWrites.map(fn => fn()));
                await rawBatch.commit();
                if (ops.length > 0) {
                    await NexusTelemetryService.emit({
                        pulse: AuditPulseType.STORAGE_WRITE, // Batch counts as a write pulse
                        vassalId: ctx.vassalId,
                        actorId: ctx.actorId,
                        payload: {
                            batchSize: ops.length,
                            operations: ops.map(o => ({ type: o.type, path: this.sanitizePath(o.path) }))
                        },
                        severity: 'INFO',
                        timestamp: new Date().toISOString(),
                    });
                }
            }
        };
    }

    async set<T = unknown>(path: string, data: T, options?: { merge?: boolean }, context?: NexusContext): Promise<void> {
        const ctx = this.ensureContext(context);
        return this.intercept('WRITE', path, ctx, async () => {
            const protectedData = await this.guard.protectWrite(this.scopePath(path, ctx.vassalId), data as unknown as SovereignData, ctx.vassalId);
            return this.adapter.set(this.scopePath(path, ctx.vassalId), protectedData, options);
        });
    }

    async update<T = unknown>(path: string, data: Partial<T>, context?: NexusContext): Promise<void> {
        const ctx = this.ensureContext(context);
        return this.intercept('WRITE', path, ctx, () =>
            this.adapter.runTransaction(async (tx) => {
                const scopedPath = this.scopePath(path, ctx.vassalId);
                const existing = await tx.get<T>(scopedPath);
                const merged = { ...existing, ...data } as unknown as SovereignData;
                const protectedData = await this.guard.protectWrite(scopedPath, merged, ctx.vassalId);
                tx.update(scopedPath, protectedData);
            })
        );
    }

    async runTransaction<T>(callback: (tx: INexusTransaction) => Promise<T>, context?: NexusContext): Promise<T> {
        const ctx = this.ensureContext(context);
        return this.adapter.runTransaction(async (rawTx) => {
            const guardedTx: INexusTransaction = {
                get: (path) => rawTx.get(this.scopePath(path, ctx.vassalId)),
                set: (path, data) => rawTx.set(this.scopePath(path, ctx.vassalId), data),
                update: (path, data) => rawTx.update(this.scopePath(path, ctx.vassalId), data),
                delete: (path) => rawTx.delete(this.scopePath(path, ctx.vassalId)),
            };
            return callback(guardedTx);
        });
    }

    async increment(path: string, field: string, amount: number, context?: NexusContext): Promise<void> {
        const ctx = this.ensureContext(context);
        return this.intercept('WRITE', path, ctx, () => this.adapter.increment(this.scopePath(path, ctx.vassalId), field, amount));
    }

    async create<T = unknown>(path: string, data: T, context?: NexusContext): Promise<void> {
        const ctx = this.ensureContext(context);
        return this.intercept('WRITE', path, ctx, async () => {
            const protectedData = await this.guard.protectWrite(this.scopePath(path, ctx.vassalId), data as unknown as SovereignData, ctx.vassalId);
            return this.adapter.create(this.scopePath(path, ctx.vassalId), protectedData);
        });
    }

    async delete(path: string, context?: NexusContext): Promise<void> {
        const ctx = this.ensureContext(context);
        return this.intercept('DELETE', path, ctx, () => this.adapter.delete(this.scopePath(path, ctx.vassalId)));
    }

    generateId(collectionPath: string): string {
        return this.adapter.generateId(collectionPath);
    }

    serverTimestamp(): unknown {
        return this.adapter.serverTimestamp();
    }

    // --- Private Infrastructure ---

    private async intercept<R>(
        operation: 'READ' | 'WRITE' | 'DELETE',
        path: string,
        context: NexusContext,
        action: () => Promise<R>
    ): Promise<R> {
        // 1. Validation d'accès — utiliser le path scopé pour éviter le faux positif :
        // 'categories' → pathTenantId='main' vs currentTenant='lepetitpoucet' déclenchait fail-safe.
        // Le batch fait déjà ça correctement (scopedPath avant validateAccess).
        const scopedForValidation = this.scopePath(path, context.vassalId);
        const accessResult = await this.guard.validateAccessGradeX(operation, scopedForValidation, context);
        if (!accessResult.granted) {
            // Access denied — emit telemetry and throw
            const reason = accessResult.reason || 'ACCESS_DENIED';
            const code = reason.includes('NF525') ? NexusErrorCode.NF525_VIOLATION : NexusErrorCode.ACCESS_DENIED;
            await this.emitDenial(operation, path, context, reason);
            const error = new NexusError(code, `Operation ${operation} refused on ${this.sanitizePath(path)}: ${reason}`);
            error.code = code; // Explicitly set it again
            throw error;
        }

        // 2. Compliance NF525
        if (operation === 'DELETE') {
            const isSealed = await this.guard.isFiscallySealed(path, context);
            if (isSealed) {
                await NexusTelemetryService.emit({
                    pulse: AuditPulseType.ILLEGAL_DELETE_ATTEMPT,
                    vassalId: context.vassalId,
                    actorId: context.actorId,
                    payload: { path: this.sanitizePath(path) },
                    severity: 'CRITICAL',
                    timestamp: new Date().toISOString(),
                });
                throw new NexusError(NexusErrorCode.NF525_VIOLATION, 'Cannot delete a fiscally sealed document');
            }
        }

        // 3. Execution
        const result = await action();

        // 4. Telemetry on Success
        if (operation === 'WRITE' || operation === 'DELETE') {
            await NexusTelemetryService.emit({
                pulse: operation === 'WRITE' ? AuditPulseType.STORAGE_WRITE : AuditPulseType.STORAGE_DELETE,
                vassalId: context.vassalId,
                actorId: context.actorId,
                payload: {
                    path: this.sanitizePath(path),
                    operation,
                },
                severity: 'INFO',
                timestamp: new Date().toISOString(),
            });

            // 4b. Audit log for sensitive collections (T07)
            const collection = this.extractCollection(path);
            if (collection && auditService.isAuditedCollection(collection)) {
                const entityId = this.extractEntityId(path);
                auditService.record({
                    tenantId: context.vassalId,
                    actorId: context.actorId,
                    actorRole: 'system',
                    action: operation === 'DELETE' ? 'delete' : 'update',
                    collection,
                    entityId,
                }).catch(() => {});
            }
        }

        return result;
    }

    private async emitDenial(operation: string, path: string, context: NexusContext, reason: string) {
        await NexusTelemetryService.emit({
            pulse: AuditPulseType.ACCESS_DENIED,
            vassalId: context.vassalId,
            actorId: context.actorId,
            payload: {
                operation,
                path: this.sanitizePath(path),
                reason,
            },
            severity: 'WARNING',
            timestamp: new Date().toISOString(),
        });
    }

    private sanitizePath(path: string): string {
        return path.replace(/tenants\/[^/]+\//g, 'vassals/[REDACTED]/');
    }

    private scopePath(path: string, vassalId: string): string {
        if (!vassalId || vassalId === 'restaurant-os' || vassalId === 'main') return path;

        // If path is already scoped to a tenant
        if (path.startsWith('tenants/')) {
            const parts = path.split('/');
            const pathTenantId = parts[1];
            // If it's the same tenant, return as is
            if (pathTenantId === vassalId) return path;
            // If it's another tenant, we keep it as is and let SovereignGuard block it
            return path;
        }

        return `tenants/${vassalId}/${path}`;
    }

    private extractCollection(path: string): string | null {
        // tenants/{tenantId}/{collection}/{id} → collection
        // or {collection}/{id} → collection
        const parts = path.split('/').filter(Boolean);
        if (parts[0] === 'tenants' && parts.length >= 3) return parts[2] ?? null;
        return parts[0] ?? null;
    }

    private extractEntityId(path: string): string | undefined {
        const parts = path.split('/').filter(Boolean);
        if (parts[0] === 'tenants' && parts.length >= 4) return parts[3];
        if (parts.length >= 2) return parts[1];
        return undefined;
    }

    private ensureContext(context?: NexusContext): NexusContext {
        if (context) return context;
        // Fallback to active tenant from Nexus manager
        return {
            vassalId: this.tenantProvider() || 'main',
            actorId: 'system'
        };
    }
}

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { getDefaultStore } from 'jotai';
import { fiscalLedgerAtom } from '@modules/compliance/qualite/haccp/store/complianceAtoms';
import { TelemetryPulse } from '@/shared/nexus-contract';
import { logger } from '@/lib/logger';

interface BatteryManager {
  level: number;
  charging: boolean;
  addEventListener(type: string, listener: EventListenerOrEventListenerObject): void;
}

interface NetworkInformation extends EventTarget {
  readonly effectiveType: string;
}

interface ExtendedNavigator extends Navigator {
  getBattery?: () => Promise<BatteryManager>;
  connection?: NetworkInformation;
  mozConnection?: NetworkInformation;
  webkitConnection?: NetworkInformation;
}

/**
 * 💓 TelemetryService - The Nexus Heartbeat (Phase 3: Le Miroir)
 * Periodically reports the health and status of the OS back to the Suzerain (MCC).
 */
export class TelemetryService {
  private static heartbeatInterval: NodeJS.Timeout | null = null;
  private static store = getDefaultStore();

  /**
   * Commence l'envoi périodique du heartbeat (chaque 5 minutes).
   */
  static start(tenantId: string) {
    this.stop(); // Cleanup previous if unknown

    logger.info(`[TelemetryService] Heartbeat démarré pour ${tenantId} (Intervalle: 5min).`);

    // Initial beat
    this.sendPulse(tenantId);

    // Set interval (5 minutes = 300,000ms)
    this.heartbeatInterval = setInterval(() => {
      this.sendPulse(tenantId);
    }, 300000);
  }

  /**
   * Envoie un signal unique de santé vers Firestore.
   */
  private static async sendPulse(tenantId: string) {
    try {
      const heartbeatPath = `tenants/${tenantId}/status/heartbeat`;

      // 1. Gather Battery Info
      let batteryInfo = { level: 1, charging: true, supported: false };
      const extendedNav = navigator as ExtendedNavigator;
      if (typeof extendedNav !== 'undefined' && extendedNav.getBattery) {
        try {
          const battery = await extendedNav.getBattery();
          batteryInfo = {
            level: battery.level,
            charging: battery.charging,
            supported: true
          };
        } catch (_e) { /* Fallback */ }
      }

      // 2. Gather NF525 Status
      const ledgerData: import('@nexus/contracts/finance.types').JournalEntry[] = this.store.get(fiscalLedgerAtom);
      const isSealed = Array.isArray(ledgerData) && ledgerData.some(e => e.fiscalSealHash);
      const lastHash = isSealed ? ledgerData.find(e => e.fiscalSealHash)?.fiscalSealHash : undefined;

      // Type-safe connection check
      const connection = extendedNav.connection || extendedNav.mozConnection || extendedNav.webkitConnection;
      const effectiveType = connection?.effectiveType || 'SOVEREIGN_UNKNOWN';


      const payload: TelemetryPulse = {
        version: '9.0.0-grade-ix',
        status: 'ACTIVE',
        lastPulse: Nexus.adapter.serverTimestamp() as unknown as Date,
        health: {
          uptime: typeof process !== 'undefined' && process.uptime ? Math.floor(process.uptime()) : 0,
          battery: batteryInfo,
          network: {
            online: typeof navigator !== 'undefined' ? navigator.onLine : true,
            effectiveType
          }
        },
        security: {
          nf525Sealed: isSealed,
          lastSealHash: lastHash,
          integrityGrade: 'IX'
        }
      };

      await Nexus.adapter.set(heartbeatPath, payload, { merge: true });
      logger.debug(`[TelemetryService] Heartbeat envoyé à ${new Date().toLocaleTimeString()}`);
    } catch (error) {
      console.warn(`[TelemetryService] Échec du heartbeat:`, error);
    }
  }

  /**
   * 📢 Dénonce une anomalie TECHNIQUE au MCC (Anonymisation Totale).
   * INTERDICTION : Pas de montants, pas de noms, pas de PII.
   */
  static async reportIssue(code: 'FALLBACK_VALUE' | 'INTEGRITY_DRIFT' | 'AUTH_ANOMALY', source: string, techMetadata: { field: string, type?: string }) {
    try {
      const issueId = `INCIDENT-${Math.random().toString(36).substring(7).toUpperCase()}`;
      const issuePath = `system_alerts/${issueId}`;

      await Nexus.adapter.set(issuePath, {
        code,
        source,
        techMetadata,
        timestamp: Nexus.adapter.serverTimestamp(),
        version: '9.0.0-grade-ix',
        severity: code === 'INTEGRITY_DRIFT' ? 'CRITICAL' : 'WARNING'
      });

      console.warn(`[TelemetryService] TECHNICAL_SIGNAL_SENT: ${code} from ${source}`, techMetadata);
    } catch (_e) {
      // Échec silencieux pour ne pas perturber l'expérience locale
    }
  }

  /**
   * Arrête le heartbeat.
   */
  static stop() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
      logger.info(`[TelemetryService] Heartbeat arrêté.`);
    }
  }
}

import { INexusAdapter, INexusBatch, INexusTransaction, NexusContext } from "@/lib/nexus/types";
import type { SovereignData } from '@/shared/nexus-contract';
import { simulatorDb } from '@/modules/intelligence/ia/simulator/SimulatorDB';
import { logger } from '@/lib/logger';
import { IdGenerator } from '@/lib/utils/IdGenerator';
import { 
    IDocumentStore, 
    IQueryEngine, 
    IRealtimeSubscriber, 
    IQueryOptions 
} from '@/shared/nexus/contracts/infrastructure/storage.contracts';

/**
 * 🌀 SimulacraAdapter - Restaurant OS (Grade X - Pure I/O)
 * The Copy-on-Write Isolation Layer.
 * Reads from Real Adapter + Virtual Store. Writes ONLY to Virtual Store.
 */
export class SimulacraAdapter implements INexusAdapter, IDocumentStore, IQueryEngine, IRealtimeSubscriber {
    constructor(
        private realAdapter: INexusAdapter,
        private forkId: string = 'default_sim'
    ) {
        logger.info(`[Simulacra] Air-Gap Interface active for fork: ${forkId}`);
    }

    async get<T = SovereignData>(path: string, _context?: NexusContext): Promise<T | null> {
        // 1. Check Virtual Store first
        const virtual = await simulatorDb.virtualStore.get(path);

        if (virtual) {
            if (virtual.isDeleted) return null;
            return virtual.data as T;
        }

        // 2. Fallback to Real Adapter (Read-only source)
        return this.realAdapter.get<T>(path);
    }

    async query<T = SovereignData>(collectionPath: string, options?: IQueryOptions, _context?: NexusContext): Promise<T[]> {
        const realResults = await this.realAdapter.query<T>(collectionPath, options);
        const virtualResults = await simulatorDb.virtualStore
            .where('forkId').equals(this.forkId)
            .filter(doc => doc.path.startsWith(collectionPath))
            .toArray();

        // Merge logic: Virtual data overrides or filters out real data
        const merged = [...realResults] as Array<T & { id?: string }>;

        virtualResults.forEach(v => {
            const virtualData = v.data as T & { id?: string };
            const index = merged.findIndex(m => m.id === virtualData.id);
            if (v.isDeleted) {
                if (index !== -1) merged.splice(index, 1);
            } else {
                if (index !== -1) merged[index] = virtualData;
                else merged.push(virtualData);
            }
        });

        return merged as T[];
    }

    onSnapshot<T = SovereignData>(path: string, callback: (data: T) => void, _options?: IQueryOptions, _context?: NexusContext): () => void {
        logger.warn("[Simulacra] Real-time snapshots are simulated via polling in Grade X.");

        // Initial load
        this.get<T>(path).then((data) => callback(data as T));

        // Polling simulation (every 2s)
        const interval = setInterval(async () => {
            const data = await this.get<T>(path);
            callback(data as T);
        }, 2000);

        return () => clearInterval(interval);
    }

    batch(context?: NexusContext): INexusBatch {
        const ops: Array<() => Promise<void>> = [];
        return {
            set: (path: string, data: unknown) => {
                ops.push(() => this.set(path, data, undefined, context));
            },
            update: (path: string, data: unknown) => {
                ops.push(() => this.update(path, data as Partial<SovereignData>, context));
            },
            delete: (path: string) => {
                ops.push(() => this.delete(path, context));
            },
            increment: (path: string, field: string, amount: number) => {
                ops.push(() => this.increment(path, field, amount, context));
            },
            commit: async () => {
                for (const op of ops) await op();
            }
        };
    }

    async set<T = SovereignData>(path: string, data: T, options?: { merge?: boolean }, _context?: NexusContext): Promise<void> {
        let finalData = data;

        if (options?.merge) {
            const existing = await this.get<Record<string, unknown>>(path);
            finalData = { ...existing, ...data };
        }

        await simulatorDb.virtualStore.put({
            path,
            data: finalData as SovereignData,
            isDeleted: false,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async update<T = SovereignData>(path: string, data: Partial<T>, _context?: NexusContext): Promise<void> {
        const existing = await this.get<Record<string, unknown>>(path);
        const finalData = { ...existing, ...data };

        await simulatorDb.virtualStore.put({
            path,
            data: finalData as SovereignData,
            isDeleted: false,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async delete(path: string, _context?: NexusContext): Promise<void> {
        await simulatorDb.virtualStore.put({
            path,
            data: null,
            isDeleted: true,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async create<T = SovereignData>(path: string, data: T, context?: NexusContext): Promise<void> {
        await this.set(path, data, undefined, context);
    }

    generateId(_collectionPath: string): string {
        return IdGenerator.generateWithPrefix('sim');
    }

    serverTimestamp(): unknown {
        return this.realAdapter.serverTimestamp();
    }

    async increment(path: string, field: string, amount: number, _context?: NexusContext): Promise<void> {
        const existing = await this.get<Record<string, number>>(path) || {} as Record<string, number>;
        existing[field] = (Number(existing[field]) || 0) + amount;
        await this.set(path, existing);
    }

    async runTransaction<T>(callback: (tx: INexusTransaction) => Promise<T>, context?: NexusContext): Promise<T> {
        const deferred: Array<() => Promise<void>> = [];
        const tx: INexusTransaction = {
            get: (path) => this.get(path, context),
            set: (path, data) => { deferred.push(() => this.set(path, data as SovereignData, undefined, context)); },
            update: (path, data) => { deferred.push(() => this.update(path, data as Partial<SovereignData>, context)); },
            delete: (path) => { deferred.push(() => this.delete(path, context)); },
        };
        const result = await callback(tx);
        for (const op of deferred) await op();
        return result;
    }
}

