            </svg>
          </div>
        </motion.div>

        {/* Intelligence Alerts - Dynamic */}
        <motion.div
          variants={fadeInUp}
          className="card-premium p-6 md:p-8"
        >
          <div className="flex items-center justify-between mb-6 border-b border-border/30 pb-4">
