interface NewQuoteDialogProps {
    isOpen: boolean;
    onClose: () => void;
}

type QuoteProduct = { name?: string; priceInMicrounits?: number; priceInCents?: number; unitCostInCents?: number };

function recalculateLineTotals(line: Partial<QuoteLine>): Partial<QuoteLine> {
    const q = line.quantity || 0;
    const p = line.unitPriceHTInMicrounits || 0;
    const v = line.vatRate || 20;
    const totalHT = Math.round(q * p);
    const vatAmount = Math.round(totalHT * (v / 100));
    return { ...line, totalHTInMicrounits: totalHT, vatAmountInMicrounits: vatAmount, totalTTCInMicrounits: totalHT + vatAmount };
}

function buildQuotePayload(
    lines: Partial<QuoteLine>[],
    crmName: string,
    subject: string,
    selectedCRMId: string | undefined,
    totals: { totalHTInMicrounits: number; totalVATInMicrounits: number; totalTTCInMicrounits: number },
): Partial<Quote> {
    return {
        customerId: selectedCRMId || 'ORPHAN',
        customerName: crmName,
        title: subject,
        items: lines.map(l => ({
            id: l.id!,
            name: l.designation!,
            quantity: l.quantity || 1,
            priceInMicrounits: l.unitPriceHTInMicrounits || 0,
            priceInCents: Math.round((l.unitPriceHTInMicrounits || 0) / 10_000),
        })),
        amountInMicrounits: totals.totalTTCInMicrounits,
        validUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        status: 'draft' as const,
        totals: {
            totalHTInMicrounits:       totals.totalHTInMicrounits,
            totalTTCInMicrounits:      totals.totalTTCInMicrounits,
            totalTaxInMicrounits:      totals.totalVATInMicrounits,
            totalDiscountInMicrounits: 0,
        },
    };
}

function needsRecalculation(updates: Partial<QuoteLine>): boolean {
    return updates.quantity !== undefined || updates.unitPriceHTInMicrounits !== undefined || updates.vatRate !== undefined;
}

function createQuoteLine(product?: QuoteProduct): Partial<QuoteLine> {
    const price = product?.priceInMicrounits ?? ((product?.priceInCents ?? product?.unitCostInCents ?? 0) * 10_000);
    return recalculateLineTotals({
        id: crypto.randomUUID(),
        type: product ? 'product' : 'service',
        designation: product?.name ?? '',
        quantity: 1,
        unitPriceHTInMicrounits: price,
        vatRate: 20,
        unit: 'unité',
    });
}

export function NewQuoteDialog({ isOpen, onClose }: NewQuoteDialogProps) {
    const [crmType, setCRMType] = useState<'individual' | 'company'>('company');
    const [crmName, setCRMName] = useState('');
    const [crmEmail, setCRMEmail] = useState('');
    const [subject, setSubject] = useState('');
    const [lines, setLines] = useState<Partial<QuoteLine>[]>(() => [createQuoteLine()]);
    const [isSaving, setIsSaving] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [showCatalog, setShowCatalog] = useState(false);

    const addNewLine = (product?: QuoteProduct) => {
        setLines([...lines, createQuoteLine(product)]);
        setShowCatalog(false);
    };

    const resetForm = () => {
        setCRMType('company');
        setCRMName('');
        setCRMEmail('');
        setSubject('');
        setLines([createQuoteLine()]);
        setIsSaving(false);
        setSearchQuery('');
        setShowCatalog(false);
    };

    const handleClose = () => {
        resetForm();
        onClose();
    };

    const removeLine = (id: string) => {
        setLines(lines.filter(l => l.id !== id));
    };

    const updateLine = (id: string, updates: Partial<QuoteLine>) => {
        const needsRecalc = needsRecalculation(updates);
        setLines(lines.map(l => {
            if (l.id !== id) return l;
            const merged = { ...l, ...updates };
            return needsRecalc ? recalculateLineTotals(merged) : merged;
        }));
    };

    const calculateTotals = () => {
        const totalHTInMicrounits = lines.reduce((sum, l) => sum + (l.totalHTInMicrounits || 0), 0);
        const totalVATInMicrounits = lines.reduce((sum, l) => sum + (l.vatAmountInMicrounits || 0), 0);
        const totalTTCInMicrounits = lines.reduce((sum, l) => sum + (l.totalTTCInMicrounits || 0), 0);
        return { totalHTInMicrounits, totalVATInMicrounits, totalTTCInMicrounits };
    };

    const totals = calculateTotals();

    const { data: inventoryProducts } = useInventory();
    const { createQuote } = useQuotes();
    const { selectedCRM } = useCRM();

    const handleSave = async () => {
        if (!crmName || !crmEmail || lines.length === 0) {
            toast.error("Veuillez remplir les informations client et ajouter au moins une ligne.");
            return;
        }

        setIsSaving(true);
        try {
            await createQuote(buildQuotePayload(lines, crmName, subject, selectedCRM?.id, totals));

            toast.success("Le devis a été généré et persisté avec succès.");
            handleClose();
