import { CryptoService } from '@/domain/services/CryptoService';
import { AuditEventSchema, AUDITED_COLLECTIONS, type AuditAction, type AuditEvent } from '@/domain/schemas/audit';
import { operationalFlags } from '@/config/features';
import { logger } from '@/lib/logger';

const GENESIS_HASH = 'AUDIT_GENESIS_0000000000000000';

interface AuditPayload {
    tenantId: string;
    actorId: string;
    actorRole: string;
    action: AuditAction;
    collection: string;
    entityId?: string;
    subjectId?: string;
    before?: Record<string, unknown>;
    after?: Record<string, unknown>;
    metadata?: Record<string, unknown>;
}

type NexusWriter = {
    set<T>(path: string, data: T): Promise<void>;
    query<T>(collectionPath: string, options?: { orderBy?: string; orderDirection?: 'asc' | 'desc'; limit?: number }): Promise<T[]>;
    generateId(collectionPath: string): string;
};

export class AuditService {
    private previousHash: string = GENESIS_HASH;
    private initialized = false;
    private nexus: NexusWriter | null = null;

    setNexus(nexus: NexusWriter) {
        this.nexus = nexus;
    }

    async init(tenantId: string) {
        if (!this.nexus) return;
        if (this.initialized) return;

        const path = `tenants/${tenantId}/auditLog`;
        const lastEvents = await this.nexus.query<AuditEvent>(path, {
            orderBy: 'ts',
            orderDirection: 'desc',
            limit: 1,
        });

        if (lastEvents.length > 0 && lastEvents[0]!.hash) {
            this.previousHash = lastEvents[0]!.hash;
        }

        this.initialized = true;
    }

    isAuditedCollection(collection: string): boolean {
        return (AUDITED_COLLECTIONS as readonly string[]).includes(collection);
    }

    stripPii(data: Record<string, unknown> | undefined): Record<string, unknown> | undefined {
        if (!data) return undefined;
        const PII_KEYS = ['email', 'phone', 'firstName', 'lastName', 'address', 'iban', 'bankAccount', 'ssn'];
        const stripped: Record<string, unknown> = {};
        for (const [key, value] of Object.entries(data)) {
            if (PII_KEYS.includes(key)) {
                stripped[key] = '[REDACTED]';
            } else {
                stripped[key] = value;
            }
        }
        return stripped;
    }

    async record(payload: AuditPayload): Promise<AuditEvent | null> {
        const mode = operationalFlags.auditIntercept;
        if (mode === 'off') return null;

        if (!this.nexus) {
            logger.warn('[AuditService] No Nexus writer — skipping audit event');
            return null;
        }

        const { tenantId, before, after, ...rest } = payload;

        if (!this.initialized && tenantId) {
            await this.init(tenantId);
        }
        const sanitizedBefore = this.stripPii(before);
        const sanitizedAfter = this.stripPii(after);

        const collectionPath = `tenants/${tenantId}/auditLog`;
        const id = this.nexus.generateId(collectionPath);
        const ts = Date.now();

        const dataForHash = CryptoService.canonicalStringify({
            ...rest,
            tenantId,
            entityId: rest.entityId ?? '',
            ts,
        });

        const hash = await CryptoService.generateHash(dataForHash, this.previousHash);

        const event: AuditEvent = {
            id,
            tenantId,
            ...rest,
            before: sanitizedBefore,
            after: sanitizedAfter,
            ts,
            hash,
            previousHash: this.previousHash,
        };

        const parsed = AuditEventSchema.parse(event);

        if (mode === 'warn') {
            logger.info(`[AuditService] WARN mode — would record: ${parsed.action} on ${parsed.collection}/${parsed.entityId ?? '?'}`);
        }

        await this.nexus.set(`${collectionPath}/${id}`, parsed);
        this.previousHash = hash;

        return parsed;
    }

    /**
     * Exports tenant-scoped audit logs in CSV format.
     */
    async exportAuditLogs(tenantId: string): Promise<string> {
        if (!this.nexus) throw new Error('[AuditService] Nexus adapter not initialized');
        const collectionPath = `tenants/${tenantId}/auditLog`;
        const events = await this.nexus.query<AuditEvent>(collectionPath, {
            orderBy: { field: 'ts', direction: 'asc' } as any
        });

        const header = 'id,ts,action,collection,entityId,userId,hash,previousHash\n';
        const rows = (events || []).map(e => 
            `"${e.id}","${new Date(e.ts).toISOString()}","${e.action}","${e.collection}","${e.entityId || ''}","${(e as any).actorId || (e as any).userId || ''}","${e.hash}","${e.previousHash}"`
        ).join('\n');

        return header + rows;
    }
}

export const auditService = new AuditService();

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { empireAudit } from '@/infrastructure/services/audit';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';

/**
 * 🕵️ C4.5: Fraud Detection Model - Grade X
 * Analyse les événements d'audit (via heuristiques ou IA) pour détecter des comportements suspects.
 */
export class FraudDetectionModel {

    /**
     * Analyse un opérateur spécifique sur une période donnée (ex: la journée).
     * Si des motifs de fraude sont détectés (ex: trop de voids après impression, skims massifs),
     * une alerte est levée.
     */
    static async analyzeOperatorBehavior(tenantId: string, operatorId: string, dateStr: string): Promise<void> {
        logger.info(`[FraudDetection] Analyse de l'opérateur ${operatorId} pour la journée du ${dateStr}...`);

        try {
            // 1. Récupération des logs d'audit
            // Dans un vrai système, on interrogerait le LightRAG ou une DB vectorielle
            const auditLogs = await Nexus.adapter.get<Record<string, { action: string, timestamp: string, details: any }>>(
                `tenants/${tenantId}/empireAudit`
            ) || {};

            let voidCount = 0;
            let discountCount = 0;
            let totalTransactions = 0;

            for (const log of Object.values(auditLogs)) {
                // Filtrage naïf pour l'exemple (en prod, indexation forte par operateur/date)
                if (log.details?.operatorId === operatorId && log.timestamp.startsWith(dateStr)) {
                    totalTransactions++;
                    if (log.action === 'ORDER_ITEM_VOIDED') voidCount++;
                    if (log.action === 'ORDER_DISCOUNT_APPLIED') discountCount++;
                }
            }

            // 2. Moteur Heuristique de Détection
            const VOID_THRESHOLD = 0.10; // 10% des actions = annulations -> très suspect

            if (totalTransactions > 20 && (voidCount / totalTransactions) > VOID_THRESHOLD) {
                const fraudProbability = Math.round((voidCount / totalTransactions) * 100);
                logger.warn(`[FraudDetection] 🚨 Comportement suspect pour ${operatorId}. Voids: ${voidCount}/${totalTransactions} (${fraudProbability}%)`);

                // 3. Action : Alerte silencieuse (on ne bloque pas le POS, on notifie le management)
                empireAudit.log({
                    module: 'finance',
                    action: 'POTENTIAL_FRAUD_DETECTED',
                    details: { 
                        operatorId, 
                        reason: 'HIGH_VOID_RATE', 
                        voidCount, 
                        totalTransactions,
                        fraudProbability 
                    },
                    severity: 'high',
                    timestamp: new Date(),
                });

                // Émission d'un event système pour réveiller le dashboard du directeur
                // Note : On ne fait pas de sovereign.breach ici car ce n'est pas une fuite de données inter-tenant, 
                // c'est un problème RH/Vol interne.
                await NexusEventBus.emitDurable('support.ticket_submitted' as any, {
                    v: 1,
                    ticketId: `fraud-${Date.now()}`,
                    tenantId,
                    description: `Activité suspecte détectée: L'opérateur ${operatorId} a un taux d'annulation anormalement élevé (${fraudProbability}%).`,
                    submittedBy: 'SYSTEM_FRAUD_AI'
                });
            }

        } catch (e) {
            logger.error('[FraudDetection] Échec de l\'analyse de fraude', e);
            throw e;
        }
    }
}

