            toast.error("Erreur lors de l'export Bilan.");
        } finally {
            setBilanExporting(false);
        }
    }, []);

    // fin-13: Payroll CSV export
    const handleExportPayroll = useCallback(async () => {
        setPayrollExporting(true);
        try {
            const { AccountingReportService } = await import("@/modules/finance/services/AccountingReportService");
            await AccountingReportService.exportPayrollCSV(payrollMonth);
            toast.success(`Variables de paie ${payrollMonth} exportées.`);
        } catch {
            toast.error("Erreur lors de l'export variables de paie.");
        } finally {
            setPayrollExporting(false);
        }
    }, [payrollMonth]);

    // ── Render ─────────────────────────────────────────────────────────────────

    return (
        <div className="min-h-screen bg-surface-base text-text-primary p-6">

            {/* fin-8: Bank connection modal iframe */}
            <BankModal open={bankModalOpen} url={bankWebviewUrl} onClose={() => setBankModalOpen(false)} />

            <header className="mb-6 flex items-start justify-between">
                <div>
                    <h1 className="text-2xl font-serif font-bold">Finance &amp; Comptabilité</h1>
                    <p className="text-sm text-text-muted mt-1">
                        Pilotage financier, facturation et audit fiscal NF525.
                    </p>
                </div>
                <button
                    onClick={() => setClaimOpen(true)}
                    className="flex items-center gap-2 px-3 py-2 rounded-md bg-action-primary text-text-primary text-sm font-medium hover:opacity-90"
                >
                    <PlusCircle className="w-4 h-4" /> Note de frais
                </button>
            </header>

            <nav className="flex gap-1 border-b border-border mb-6 overflow-x-auto">
                {([
                    { id: "accounting", label: "Comptabilité", icon: BookOpen },
                    { id: "billing", label: "Facturation", icon: Receipt },
                    { id: "bank", label: "Connexion Bancaire", icon: Landmark },
                    { id: "treasury", label: "Trésorerie", icon: Wallet },
                    { id: "audit", label: "Audit fiscal", icon: ShieldCheck },
                ] as const).filter(tab => {
                    if (tab.id === "treasury") return canSeeTreasury;
                    if (tab.id === "audit") return canSeeAudit;
                    return true;
                }).map((tab) => {
                    const Icon = tab.icon;
                    const active = activeTab === tab.id;
                    return (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
                                active
                                    ? "border-action-primary text-action-primary"
                                    : "border-transparent text-text-muted hover:text-text-primary"
                            }`}
                        >
                            <Icon className="w-4 h-4" />
                            {tab.label}
                        </button>
                    );
                })}
            </nav>

            <main>
                {/* ── Comptabilité ───────────────────────────────────────────── */}
                {activeTab === "accounting" && (
                    <AccountingTab
                        journalEntries={journalEntries}
                        metrics={metrics}
                        accountingMetrics={accountingMetrics}
                        tvaBreakdown={tvaBreakdown}
                        closingZ={closingZ}
                        payrollMonth={payrollMonth}
                        pnlExporting={pnlExporting}
                        bilanExporting={bilanExporting}
                        payrollExporting={payrollExporting}
                        activeTenantId={activeTenantId}
                        closePeriodPermission={closePeriodPermission}
                        onClotureZ={handleClotureZ}
                        onPayrollMonthChange={setPayrollMonth}
                        onExportPnL={handleExportPnL}
                        onExportBilan={handleExportBilan}
                        onExportPayroll={handleExportPayroll}
                    />
                )}

                {/* ── Facturation ────────────────────────────────────────────── */}
                {activeTab === "billing" && (
                    <BillingTab
                        paidOrders={paidOrders}
                        ordersLoading={ordersLoading}
                    />
                )}

                {/* ── Connexion Bancaire (fin-8) ─────────────────────────────── */}
                {activeTab === "bank" && (
                    <BankTab
                        connectingBank={connectingBank}
                        syncingBank={syncingBank}
                        loadingBankAccounts={loadingBankAccounts}
                        bankAccounts={bankAccounts}
                        bankTransactions={bankTransactions as BankTransaction[]}
                        onConnectBank={handleConnectBank}
                        onSync={handleBankSync}
                    />
                )}

                {/* ── Trésorerie & SEPA ──────────────────────────────────────── */}
                {activeTab === "treasury" && (
                    <TabGuard pageKey="finance" tabKey="treasury">
                        <TreasuryTab />
                    </TabGuard>
                )}

                {/* ── Audit fiscal ───────────────────────────────────────────── */}
                {activeTab === "audit" && (
                    <TabGuard pageKey="finance" tabKey="audit">
                        <AuditTab entriesCount={journalEntries.length} journalEntries={journalEntries} />
                    </TabGuard>
                )}
            </main>

            <ExpenseClaimDialog isOpen={claimOpen} onClose={() => setClaimOpen(false)} />
        </div>
    );
}

"use client";

import { useState, useCallback } from "react";
import { FileText } from "lucide-react";
import { FacturXDownloadButton } from "@/modules/finance/components/FacturXDownloadButton";
import type { Order } from "@/domain/schemas/orders";
import { useBilling } from "@modules/finance/comptabilite/billing/hooks/useBilling";

/**
 * Onglet « Facturation » de la page Finance — extrait de page.tsx (dette-4).
 */
export interface BillingTabProps {
    paidOrders: Order[];
    ordersLoading: boolean;
}

export function BillingTab({ paidOrders, ordersLoading }: BillingTabProps) {
    const [billingOrder, setBillingOrder] = useState<string | null>(null);
    const { billOrder } = useBilling();

    const onBillOrder = useCallback(async (order: Order) => {
        setBillingOrder(order.id);
        try {
            await billOrder(order);
        } finally {
            setBillingOrder(null);
        }
    }, [billOrder]);
    return (
        <section className="space-y-4">
            <div className="flex items-center justify-between">
                <h2 className="text-lg font-serif font-semibold">Factures émises</h2>
                <span className="text-xs text-text-muted">
                    {paidOrders.length} commande{paidOrders.length !== 1 ? "s" : ""} facturée{paidOrders.length !== 1 ? "s" : ""}
                </span>
            </div>

            {ordersLoading ? (
                <p className="text-sm text-text-muted italic py-8 text-center">Chargement…</p>
            ) : paidOrders.length === 0 ? (
                <p className="text-sm text-text-muted italic py-8 text-center">
                    Aucune commande réglée — les factures apparaissent ici automatiquement.
                </p>
            ) : (
                <div className="space-y-2">
                    {paidOrders.map((order) => (
                        <div
                            key={order.id}
                            className="rounded-lg border border-border p-4 flex items-center justify-between bg-surface-sidebar"
                        >
                            <div className="flex items-center gap-3">
                                <FileText className="w-4 h-4 text-text-muted shrink-0" />
                                <div>
                                    <p className="text-sm font-medium">
                                        FACT-{new Date().getFullYear()}-{order.id.slice(-6).toUpperCase()}
                                    </p>
                                    <p className="text-xs text-text-muted">
                                        Table {order.tableId ?? "Emporté"} · Commande {order.id.slice(-8)}
                                    </p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 shrink-0">
                                <button
                                    onClick={() => onBillOrder(order)}
                                    disabled={billingOrder === order.id}
                                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-border text-xs font-medium hover:bg-action-primary hover:text-text-primary hover:border-action-primary transition-colors disabled:opacity-50"
                                >
                                    {billingOrder === order.id ? "Émission…" : "Émettre facture"}
                                </button>
                                {/* fin-9: Factur-X XML (e-facturation B2B 2026) */}
                                <FacturXDownloadButton
                                    invoiceId={order.id}
                                    filename={`facturx_FACT-${new Date().getFullYear()}-${order.id.slice(-6).toUpperCase()}.xml`}
                                />
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </section>
    );
}

"use client";

import React, { useState, useRef } from "react";
import { X, Camera, ReceiptEuro, Save, Sparkles, ShieldCheck } from "lucide-react";
