import { useEffect, useCallback } from 'react';
        // FIXME (Modular Monolith): Remove cross-module import. Use domain/ or NexusEventBus.
        // eslint-disable-next-line vanguard/no-inter-module-imports
import { useOrders } from '@/modules/ops/providers';
import type { Order } from '@modules/ops/workflow/engine/types';
import type { JournalEntry } from '@modules/finance/types';
import { InvoiceEngine } from '../domain/InvoiceEngine';
import { useAtomValue, useStore } from 'jotai';
import { fiscalLedgerNodeAtom } from '@/store/pillars/compliance';
import { tenantIdAtom } from '@/store/pillars/sovereign';

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { OperationalIdentity } from '@/shared/nexus-contract';
import { DomainRegistry } from '@shared/nexus/engines/DomainRegistry';
import { logger } from '@/lib/logger';

/**
 * 🧾 useBilling - Fiscal Suture Hook
 * Orchestrates the real-time link between POS [OPS] and Billing [FINANCE].
 */
export function useBilling(options?: { enabled?: boolean }) {
    const enabled = options?.enabled ?? true;
    const { data: orders, isLoading } = useOrders();
    const fiscalLedgerNode = useAtomValue(fiscalLedgerNodeAtom);
    const tenantId = useAtomValue(tenantIdAtom);
    const _store = useStore();

    /**
     * Fiscal Suture: Process a single order into a LegalInvoice and seal it.
     */
    const billOrder = useCallback(async (order: Order) => {
        try {
            // 1. Transform SovereignOrder -> LegalInvoice
            const invoice = InvoiceEngine.transform(order);

            // 2. Map to JournalEntry for the Ledger
            const journalEntry = InvoiceEngine.toJournalEntry(invoice, tenantId as string);

            // 3. Save Invoice to Finance Domain
            const invoicePath = `tenants/${tenantId as string}/finance/billing`;
            await Nexus.adapter.create(invoicePath, invoice);

            // 4. Seal to Fiscal Ledger (STX_LAMBDA)
            const ledgerPath = `tenants/${tenantId as string}/${DomainRegistry.resolve(OperationalIdentity.COMPLIANCE)}`;
            await Nexus.adapter.create(ledgerPath, journalEntry);

            logger.info(`[Billing] Order ${order.id} billed and sealed successfully as ${invoice.invoiceNumber}`);
            return invoice;
        } catch (error) {
            logger.error(`[Billing] Failed to bill order ${order.id}`, error);
            throw error;
        }
    }, [tenantId]);

    /**
     * Orchestrator: Watch for completed orders that haven't been billed.
     */
    useEffect(() => {
        if (!enabled || isLoading || !orders) return;

        const processOrders = async () => {
            const completedOrders = (orders as Order[]).filter((o: Order) => o.status === 'paid' || (o as { status?: string }).status === 'served');
            const ledgerData = (fiscalLedgerNode.data || []) as unknown as JournalEntry[];

            for (const order of completedOrders) {
                const isAlreadyBilled = ledgerData.some((entry: JournalEntry) => (entry as { metadata?: { orderId?: string } }).metadata?.orderId === order.id);

                if (!isAlreadyBilled) {
                    await billOrder(order);
                }
            }
        };

        processOrders();
    }, [enabled, orders, isLoading, fiscalLedgerNode.data, billOrder]);

    return {
        billOrder,
        isLoadingOrders: isLoading
    };
}

import { CA3Declaration, EDISubmissionResult, TaxBreakdown } from './types';
import { EDIMapper } from './EDIMapper';
import { DocumentVault } from '@/domain/shared/DocumentVault';
import { QuantumCrypto } from '@/infrastructure/services/QuantumCrypto';
import { NexusTelemetryService } from '@/domain/services/NexusTelemetryService';
import { SovereignLedger } from '@/modules/finance/services';

/**
 * 🏛️ FiscalTransmitter - Grade X+++
 * Déclarations TVA EDI et transmission DGFiP via partenaire EDI.
 */
export class FiscalTransmitter {

    /**
     * Génère, transmet et archive la déclaration TVA (CA3)
     */
    static async transmitCA3(tenantId: string, siren: string, period: string): Promise<EDISubmissionResult> {
        NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_STARTED', { period });

        // 1. Extraction de la breakdown (Simulation via le Ledger)
        const breakdown = await this.extractTaxBreakdown();

        const declaration: CA3Declaration = {
            period,
            siren,
            breakdown,
            generatedAt: new Date().toISOString()
        };

        // 2. Transformation XML (Format TDFC)
        const xmlContent = EDIMapper.toTDFC(declaration);

        // 3. Transmission EDI via Provider (Simulation Jedéclare)
        const submissionResult = await this.transmitToEDIProvider(xmlContent);

        if (submissionResult.success && submissionResult.status === 'ACCEPTED') {
            // 4. Scellage et archivage WORM du récépissé
            const receiptHash = await QuantumCrypto.sign(xmlContent);
            submissionResult.dgfipReceiptHash = receiptHash;

            await DocumentVault.archive(`CA3_RECEIPT_${period}.xml`, xmlContent, {
                tenantId,
                type: 'TAX_DECLARATION',
                period,
                hash: receiptHash
            });

            // 5. Suture Financière: Provisionnement de la TVA à décaisser
            await SovereignLedger.getInstance(tenantId).recordTransfer({
                debitAccount: 'TAX_COLLECTED_4457',
                creditAccount: 'TAX_TO_PAY_4455',
                amountInCents: breakdown.netTaxToPayInCents,
                referenceId: `TVA-${period}`,
                description: `Liquidation TVA Période ${period}`
            });

            NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_SUCCESS', { 
                period, 
                receiptHash 
            });
        } else {
            NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_FAILED', { 
                period, 
                errors: submissionResult.errors 
            });
        }

        return submissionResult;
    }

    /**
     * Extrait les données fiscales du Ledger (Stub pour le module)
     */
    private static async extractTaxBreakdown(): Promise<TaxBreakdown> {
        // En conditions réelles, cette méthode interroge le SovereignLedger
        // pour calculer la base HT et la TVA collectée/déductible.
        return {
            totalRevenueInCents: 5000000,
            totalRevenueInMicrounits: 5000000 * 10_000,
            taxBaseByRate: { "20.0": 4000000, "10.0": 1000000 },
            taxCollectedByRate: { "20.0": 800000, "10.0": 100000 },
            totalTaxCollectedInCents: 900000,
            totalTaxCollectedInMicrounits: 900000 * 10_000,
            deductibleTaxInCents: 200000,
            deductibleTaxInMicrounits: 200000 * 10_000,
            netTaxToPayInCents: 700000,
            netTaxToPayInMicrounits: 700000 * 10_000,
        };
    }

    /**
     * Transmission vers le partenaire EDI (ex: Jedéclare)
     */
    private static async transmitToEDIProvider(_xmlContent: string): Promise<EDISubmissionResult> {
        // Stub: Simulation de réponse du partenaire EDI
        return {
            success: true,
            submissionId: `EDI_${Date.now()}`,
            status: 'ACCEPTED'
        };
    }
}

"use client";

import React, { createContext, useContext, useMemo, ReactNode, useCallback } from 'react';
import { useAtomValue } from 'jotai';
import { 
    journalEntriesNodeAtom, 
    accountsAtom, 
    bankTransactionsAtom, 
    expenseClaimsAtom 
} from '@/store/pillars/finance';
import { fiscalLedgerNodeAtom } from '@/store/pillars/compliance';
import { tenantIdAtom, currentUserAtom } from '@/store/pillars/sovereign';

import { SovereignMath } from '@shared/services/SovereignMath';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { BlockchainLedgerService } from '@/modules/finance/comptabilite/accounting/domain/BlockchainLedgerService';
import { computeTreasury } from '@/modules/finance/services/TreasuryCalculator';
import { 
    JournalEntry,
    Account,
    BankTransaction,
    ExpenseClaim,
    TreasurySnapshot,
    FiscalSeal
} from '@modules/finance/types';
import type { TreasuryMetrics } from '@/domain/schemas/finance';
import { useBilling } from '@modules/finance/comptabilite/billing/hooks/useBilling';
import { useTaskContext } from '@/lib/icm/useTaskContext';

import { Sentry } from '@/lib/sentry';
import { toMicrounits } from '@/domain/schemas/primitives';

/**
 * 🏛️ SovereignSignable
 */
interface SovereignSignable {
    amountInMicrounits: number;
    category: string;
    date: string;
    merchantName?: string;
    [key: string]: unknown;
}

/**
 * 🛡️ ComplianceDocument - Grade X Agnostic Structure
 */
export interface ComplianceDocument {
    id: string;
    type: string;
    status: 'VALID' | 'EXPIRED' | 'PENDING';
    issuedAt: string;
    expiresAt: string;
    metadata: Record<string, import("@/shared/nexus-contract").SovereignValue>;
}

export interface NexusFiscalState {
    accounting: {
        entries: JournalEntry[];
        accounts: Account[];
        bankTransactions: BankTransaction[];
        expenseClaims: ExpenseClaim[];
        isLoading: boolean;
        metrics: { netProfitInMicrounits: number };
        submitExpense: (data: Partial<ExpenseClaim>) => Promise<string | undefined>;
    };
    compliance: {
        seals: FiscalSeal[];
        runAudit: () => Promise<boolean>;
        documents: ComplianceDocument[]; 
    };
    finance: {
        treasury: TreasuryMetrics;
        cashSnapshot: TreasurySnapshot;
    };
}

function computeRevExpTotals(entries: JournalEntry[]): { totalRevenueMu: number; totalExpensesMu: number } {
    let rev = 0, exp = 0;
    for (const entry of entries) {
        const amount = Number(entry.amountInMicrounits || 0);
        if (entry.type === 'revenue') rev = SovereignMath.add(rev, amount);
        else if (entry.type === 'expense') exp = SovereignMath.add(exp, amount);
    }
    return { totalRevenueMu: rev, totalExpensesMu: exp };
}

const NexusFiscalContext = createContext<NexusFiscalState | undefined>(undefined);

export const NexusFiscalProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const tenantId = useAtomValue(tenantIdAtom);
    const currentUser = useAtomValue(currentUserAtom);
    const journalEntries = useAtomValue(journalEntriesNodeAtom);
    const accounts = useAtomValue(accountsAtom);
    const bankTransactions = useAtomValue(bankTransactionsAtom);
    const expenseClaims = useAtomValue(expenseClaimsAtom);
    const fiscalSeals = useAtomValue(fiscalLedgerNodeAtom);

    // 🛡️ SOVEREIGN MATH: Total elimination of native operators
    const netProfitInMicrounits = useMemo(() => {
        const entries = journalEntries.data;
        const total = entries.reduce((acc: number, entry) => {
            const amount = Number(entry.amountInMicrounits || 0);
            return entry.type === 'revenue' ? SovereignMath.add(acc, amount) : SovereignMath.subtract(acc, amount);
        }, 0);
        return total;
    }, [journalEntries.data]);

    // Produits & charges séparés (pour le résumé P&L de la trésorerie).
    const { totalRevenueMu, totalExpensesMu } = useMemo(
        () => computeRevExpTotals(journalEntries.data),
        [journalEntries.data]
    );

    const generateBusinessSignature = (data: SovereignSignable): string => {
        const payload = `${data.amountInMicrounits}|${data.category}|${data.merchantName || 'NONE'}|${data.date}`;
        let hash = 0;
        for (let i = 0; i < payload.length; i++) {
            const char = payload.charCodeAt(i);
            // 🛡️ NO NATIVE MULTIPLY
            hash = SovereignMath.add(SovereignMath.multiply(hash, 31), char);
        }
        return `SIG_${Math.abs(hash).toString(36).toUpperCase()}`;
    };

    const submitExpense = useCallback(async (expenseData: Partial<ExpenseClaim>) => {
        if (!tenantId || !currentUser) throw new Error("FISCAL_SESSION_ERROR");

        try {
            const finalData: SovereignSignable = {
                ...expenseData,
                amountInMicrounits: Number(expenseData.amountInMicrounits || 0),
                category: expenseData.category || 'other',
                date: expenseData.submittedAt ? new Date(expenseData.submittedAt).toISOString() : new Date().toISOString()
            };

            const businessSignature = generateBusinessSignature(finalData);
            const idempotencyKey = `FISCAL_${tenantId}_${businessSignature}`;

            Sentry.setTag("fiscal.idempotency_key", idempotencyKey);
            Sentry.setTag("nexus.grade", "X+++");

            const path = `tenants/${tenantId}/expenseClaims`;
            const id = Nexus.adapter.generateId(path);

            await Nexus.adapter.set(`${path}/${id}`, {
                ...expenseData,
                id,
                idempotencyKey,
                updatedAt: new Date().toISOString()
            });

            return id;
        } catch (error) {
            Sentry.captureException(error, { tags: { source: 'fiscal', tenantId } });
            throw error;
        }
    }, [tenantId, currentUser]);

    const runFiscalAudit = useCallback(async (): Promise<boolean> => {
        logger.info("[NexusFiscal] Running NF525 Integrity Audit...");
        const intact = await BlockchainLedgerService.auditFullChain();
        logger.info(`[NexusFiscal] Audit terminé — chaîne ${intact ? 'intacte' : 'BRISÉE'}`);
        return intact;
    }, []);

    // 💰 CASH SNAPSHOT — position de trésorerie réelle depuis les écritures Nexus
    // (PCG 53x caisse / 512x banque / 411x créances / 401x dettes). Remplace le stub zéro.
    const cashSnapshot: TreasurySnapshot = useMemo(
        () => computeTreasury(journalEntries.data),
        [journalEntries.data],
    );

    // 💰 TREASURY — résumé P&L (produits / charges / résultat), désormais calculé.
    const treasury: TreasuryMetrics = useMemo(() => {
        const marginRate = totalRevenueMu > 0
            ? Math.max(-1, Math.min(1, netProfitInMicrounits / totalRevenueMu))
            : 0;
        const now = Date.now();
        return {
            totalRevenueInMicrounits: toMicrounits(totalRevenueMu),
            totalExpensesInMicrounits: toMicrounits(totalExpensesMu),
            netProfitInMicrounits,
            marginRate,
            forecastedRevenueInMicrounits: toMicrounits(totalRevenueMu),
            cashPositionInMicrounits: cashSnapshot.netCashPositionInMicrounits,
            periodStart: now - 30 * 86_400_000,
            periodEnd: now,
        };
    }, [totalRevenueMu, totalExpensesMu, netProfitInMicrounits, cashSnapshot]);

    const contextValue: NexusFiscalState = useMemo(() => ({
        accounting: {
            entries: journalEntries.data,
            accounts,
            bankTransactions,
            expenseClaims,
            isLoading: journalEntries.loading || false,
            metrics: { netProfitInMicrounits },
            submitExpense
        },
        compliance: {
            seals: fiscalSeals.data as unknown as FiscalSeal[],
            runAudit: runFiscalAudit,
            documents: [] as ComplianceDocument[] 
        },
        finance: {
            treasury,
            cashSnapshot
        }
    }), [journalEntries, accounts, bankTransactions, expenseClaims, netProfitInMicrounits, submitExpense, fiscalSeals, runFiscalAudit, treasury, cashSnapshot]);

    const taskContext = useTaskContext();
    const financeActive = taskContext.importance.finance !== 'OFF';
    useBilling({ enabled: financeActive });

    return (
        <NexusFiscalContext.Provider value={contextValue}>
            {children}
        </NexusFiscalContext.Provider>
    );
};

export const useNexusFiscal = () => {
    const context = useContext(NexusFiscalContext);
    if (!context) throw new Error("useNexusFiscal must be used within NexusFiscalProvider");
    return context;
};

export const useCompliance = () => useNexusFiscal().compliance;
export const useAccounting = () => useNexusFiscal().accounting;
export const useFinance = () => useNexusFiscal().finance;
export const useFinanceReflex = () => useNexusFiscal(); // Fallback if reflex is needed
export const useFiscal = () => useNexusFiscal();

