 *
 * ⚠️ Les noms de champs exacts de l'API Powens (auth/token, users/me/accounts…)
 * doivent être revérifiés contre la doc Powens en vigueur avant mise en prod —
 * cette implémentation suit la forme documentée publiquement au moment de l'écriture,
 * mais Powens fait évoluer son contrat régulièrement.
 */
export class PowensProvider implements IOpenBankingProvider {
    readonly id = 'powens';
    readonly webhookSignatureHeader = 'x-powens-signature';

    private static API_URL = process.env.POWENS_API_URL ?? 'https://sandbox.biapi.pro/2.0';
    private static CLIENT_ID = process.env.POWENS_CLIENT_ID ?? process.env.NEXT_PUBLIC_POWENS_CLIENT_ID;

    private static get CLIENT_SECRET(): string {
        const secret = process.env.POWENS_CLIENT_SECRET;
        if (!secret) {
            throw new Error('❌ SÉCURITÉ : POWENS_CLIENT_SECRET manquant. Accès bancaire refusé.');
        }
        return secret;
    }

    isDemoMode(): boolean {
        const clientId = PowensProvider.CLIENT_ID;
        if (!clientId || clientId.includes('placeholder') || clientId === 'restaurant-os-master') return true;
        // Pas de secret = mode démo sécurisé plutôt que throw sur le premier appel réel
        if (!process.env.POWENS_CLIENT_SECRET) return true;
        return false;
    }

    async createConnectionToken(tenantId: string): Promise<OpenBankingConnectionToken> {
        if (this.isDemoMode()) {
            return { token: `demo-token-${tenantId}` };
        }
        const res = await fetch(`${PowensProvider.API_URL}/auth/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                client_id: PowensProvider.CLIENT_ID!,
                client_secret: PowensProvider.CLIENT_SECRET,
                grant_type: 'client_credentials',
            }),
        });
        if (!res.ok) {
            logger.error('PowensProvider: createConnectionToken failed', { status: res.status });
            throw new Error('Impossible d\'initialiser la connexion bancaire.');
        }
        const data = (await res.json()) as { access_token: string; expires_in?: number };
        return {
            token: data.access_token,
            expiresAt: data.expires_in ? Date.now() + data.expires_in * 1000 : undefined,
        };
    }

    async getConnectionUrl(token: string, redirectUri: string, state: string): Promise<string> {
        const baseUrl = this.isDemoMode()
            ? 'https://restaurant-os-sandbox.biapi.pro/2.0/manage/connect'
            : `${PowensProvider.API_URL}/manage/connect`;
        const params = new URLSearchParams({
            client_id: PowensProvider.CLIENT_ID ?? '',
            token,
            redirect_uri: redirectUri,
            state,
        });
        return `${baseUrl}?${params.toString()}`;
    }

    async exchangeCode(code: string): Promise<OpenBankingUserToken> {
        if (this.isDemoMode()) {
            return { userToken: `demo-user-token-${code}` };
        }
        const res = await fetch(`${PowensProvider.API_URL}/auth/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                client_id: PowensProvider.CLIENT_ID!,
                client_secret: PowensProvider.CLIENT_SECRET,
                grant_type: 'authorization_code',
                code,
            }),
        });
        if (!res.ok) {
            logger.error('PowensProvider: exchangeCode failed', { status: res.status });
            throw new Error('Impossible de finaliser la connexion bancaire.');
        }
        const data = (await res.json()) as { access_token: string; expires_in?: number };
        return {
            userToken: data.access_token,
            expiresAt: data.expires_in ? Date.now() + data.expires_in * 1000 : undefined,
        };
    }

    async getAccounts(userToken: string): Promise<OpenBankingAccount[]> {
        if (this.isDemoMode()) return [];
        const res = await fetch(`${PowensProvider.API_URL}/users/me/accounts`, {
            headers: { Authorization: `Bearer ${userToken}` },
        });
        if (!res.ok) {
            logger.error('PowensProvider: getAccounts failed', { status: res.status });
            throw new Error('Impossible de récupérer les comptes bancaires.');
        }
        const data = (await res.json()) as { accounts?: PowensAccountDTO[] };
        return (data.accounts ?? []).map((acc) => ({
            id: String(acc.id),
            balance: acc.balance,
            bankName: acc.connection?.bank?.name ?? 'Banque inconnue',
            label: acc.name ?? 'Compte',
            currency: typeof acc.currency === 'string' ? acc.currency : (acc.currency?.id ?? 'EUR'),
            lastUpdate: new Date().toISOString(),
        }));
    }

    async getTransactions(
        accountId: string,
        userToken: string,
        fromDate?: string
    ): Promise<Omit<BankTransaction, 'id'>[]> {
        if (this.isDemoMode()) return [];
        const params = fromDate ? `?min_date=${encodeURIComponent(fromDate)}` : '';
        const res = await fetch(
            `${PowensProvider.API_URL}/users/me/accounts/${accountId}/transactions${params}`,
            { headers: { Authorization: `Bearer ${userToken}` } }
        );
        if (!res.ok) {
            logger.error('PowensProvider: getTransactions failed', { status: res.status, accountId });
            throw new Error('Impossible de récupérer les transactions bancaires.');
        }
        const data = (await res.json()) as { transactions?: PowensTransactionDTO[] };
        const out: Omit<BankTransaction, 'id'>[] = [];
        for (const tx of data.transactions ?? []) {
            const label = tx.wording ?? tx.original_wording ?? 'Transaction';
            const transaction: Omit<BankTransaction, 'id'> = {
                date: tx.date,
                label,
                amountInCents: Math.round(Math.abs(tx.value) * 100),
                type: tx.value >= 0 ? 'credit' : 'debit',
                isReconciled: false,
                updatedAt: new Date().toISOString(),
            };
            transaction.signature = await StatementIngestionService.generateSignature(transaction);
            out.push(transaction);
        }
        return out;
    }

    normalizeWebhookPayload(raw: unknown): import('./types').WebhookEnvelope {
        const p = raw as { tenant_id?: string; event?: string };
        return {
            tenantId: p.tenant_id,
            event:    p.event ?? 'unknown',
            raw,
        };
    }

    async refreshConnection(userToken: string): Promise<void> {
        if (this.isDemoMode()) return;
        const res = await fetch(`${PowensProvider.API_URL}/users/me/connections`, {
            method: 'PUT',
            headers: { Authorization: `Bearer ${userToken}`, 'Content-Type': 'application/json' },
        });
        if (!res.ok) {
            logger.error('PowensProvider: refreshConnection failed', { status: res.status });
            throw new Error('Erreur Powens lors de la synchronisation.');
        }
    }
}

import { PayoutInvoice, PayoutRequest } from './types';
import { BankingNexusBridge } from '@/modules/finance/tresorerie/banking/BankingNexusBridge';
import { QuantumCrypto } from '@/infrastructure/services/QuantumCrypto';
import { NexusTelemetryService } from '@/domain/services/NexusTelemetryService';
import { SovereignLedger } from '@/modules/finance/services';

/**
 * 🏛️ SovereignPayout - Grade X+++
 * Virements Fournisseurs Intégrés avec Approbation Duale
 */
export class SovereignPayout {
    private static readonly MCC_APPROVAL_THRESHOLD_CENTS = 50000; // 500.00€

    /**
     * Initie une demande de paiement fournisseur.
     */
    static async initiatePayout(invoice: PayoutInvoice, initiatorAdminId: string, tenantId: string): Promise<PayoutRequest> {
        if (invoice.status !== 'validated') {
            throw new Error('PAYOUT_001: Invoice must be validated before payout.');
        }

        const currentBalance = await BankingNexusBridge.getBalance();
        if (currentBalance < invoice.amountInCents) {
            throw new Error('PAYOUT_002: Insufficient funds for payout.');
        }

        const isHighValue = invoice.amountInCents > this.MCC_APPROVAL_THRESHOLD_CENTS;

        const request: PayoutRequest = {
            id: `REQ-${invoice.id}-${Date.now()}`,
            invoiceId: invoice.id,
            amountInCents: invoice.amountInCents,
            amountInMicrounits: (invoice.amountInMicrounits ?? invoice.amountInCents * 10_000),
            status: isHighValue ? 'pending_approval' : 'approved',
            approvals: []
        };

        // Première signature Post-Quantique par l'initiateur
        const signature = await QuantumCrypto.sign(`APPROVE_${request.id}_${initiatorAdminId}`);
        request.approvals.push({
            adminId: initiatorAdminId,
            signatureHash: signature,
            timestamp: new Date().toISOString()
        });

        if (!isHighValue) {
            await this.executePayout(request, invoice, tenantId);
        }

        NexusTelemetryService.emitAuditPulse('FINANCE', 'PAYOUT_INITIATED', {
            requestId: request.id,
            amountInCents: request.amountInCents,
            requiresDualApproval: isHighValue
        });

        return request;
    }

    /**
     * Valide le paiement via l'Approbation Duale (MCC).
     */
    static async approvePayout(request: PayoutRequest, invoice: PayoutInvoice, secondAdminId: string, tenantId: string): Promise<PayoutRequest> {
        if (request.status !== 'pending_approval') {
            throw new Error('PAYOUT_003: Request is not pending approval.');
        }

        // Zéro Null / Strict Guard: Vérification d'unicité de l'admin
        const hasAlreadyApproved = request.approvals.some(a => a.adminId === secondAdminId);
        if (hasAlreadyApproved) {
            throw new Error('PAYOUT_004: Dual approval requires two distinct administrators.');
        }

        // Seconde signature
        const signature = await QuantumCrypto.sign(`APPROVE_${request.id}_${secondAdminId}`);
        request.approvals.push({
            adminId: secondAdminId,
            signatureHash: signature,
            timestamp: new Date().toISOString()
        });

        request.status = 'approved';

        NexusTelemetryService.emitAuditPulse('FINANCE', 'PAYOUT_DUAL_APPROVED', {
            requestId: request.id,
            secondAdminId
        });

        await this.executePayout(request, invoice, tenantId);

        return request;
    }

    /**
     * Exécute le paiement SEPA et suture le registre comptable.
     */
    private static async executePayout(request: PayoutRequest, invoice: PayoutInvoice, tenantId: string): Promise<void> {
        if (request.status !== 'approved') {
            throw new Error('PAYOUT_005: Cannot execute unapproved payout.');
        }

        request.status = 'processing';

        try {
            // Exécution du virement SCT SEPA via le Bridge BaaS
            const sepaRef = await BankingNexusBridge.executeSepaTransfer(
                invoice.bankAccountIban, 
                request.amountInCents, 
                `INV-${invoice.id}`
            );

            request.sepaReference = sepaRef;
            request.status = 'completed';

            // Suture Financière: Extinction de la dette (Débit 401) et sortie de trésorerie (Crédit 512 / CASH)
            await SovereignLedger.getInstance(tenantId).recordTransfer({
                debitAccount: 'SUPPLIER_DEBT_401',
                creditAccount: 'CASH',
                amountInCents: request.amountInCents,
                referenceId: request.id,
                description: `Paiement fournisseur SEPA ${sepaRef}`
            });

            NexusTelemetryService.emitAuditPulse('FINANCE', 'PAYOUT_COMPLETED', {
                requestId: request.id,
                sepaRef
            });

        } catch (error) {
            request.status = 'failed';
            NexusTelemetryService.emitAuditPulse('FINANCE', 'PAYOUT_FAILED', {
                requestId: request.id,
                error: error instanceof Error ? error.message : 'Unknown SEPA error'
            });
            throw new Error('PAYOUT_006: SEPA Transfer Failed.');
        }
    }
}

import type { IPayrollConnectorProvider, TimesheetEntry, Payslip, PayrollCost, PayrollSyncResult } from '../types';
import { MergePayrollClient } from '@/modules/human/remuneration/payroll/MergePayrollClient';
import { logger } from '@/lib/logger';

/**
 * Adaptateur IPayrollConnectorProvider → MergePayrollClient.
 * Merge.dev unifie PayFit, BambooHR, ADP, Gusto, etc. via un seul token.
 */
export class MergeConnectorProvider implements IPayrollConnectorProvider {
    readonly id = 'merge';

    private client(): MergePayrollClient {
        return new MergePayrollClient({
            provider: 'merge',
            mergeAccountToken: process.env.MERGE_ACCOUNT_TOKEN,
            mergeLinkedAccountId: process.env.MERGE_LINKED_ACCOUNT_ID,
        });
    }

    async ping(): Promise<{ ok: boolean; info?: string }> {
        try {
            const client = this.client();
            const employees = await client.listRemoteEmployees();
            return { ok: true, info: `${employees.length} employé(s) distant(s)` };
        } catch (err) {
            logger.warn('[MergeConnectorProvider] ping failed', String(err));
            return { ok: false };
        }
    }

    async pushTimesheet(_employeeId: string, hours: TimesheetEntry[]): Promise<void> {
        logger.info('[MergeConnectorProvider] pushTimesheet', hours.length, 'lignes');
    }

    async fetchPayslips(tenantId: string, month: string): Promise<Payslip[]> {
        logger.info('[MergeConnectorProvider] fetchPayslips', tenantId, month);
        return [];
    }

    async fetchPayrollCost(tenantId: string, month: string): Promise<PayrollCost> {
        logger.info('[MergeConnectorProvider] fetchPayrollCost', tenantId, month);
        return { month, totalGross: 0, totalNet: 0, totalEmployerCost: 0, headcount: 0 };
    }

    async syncPeriod(summary: import('@/modules/human/remuneration/payroll/types').PayrollPeriodSummary): Promise<PayrollSyncResult> {
        const client = this.client();
        const raw = await client.syncPeriod(summary);
        return {
            success: raw.success,
            employeesUpserted: raw.synced,
            variablesAccepted: 0,   // Merge HRIS ne distingue pas les variables de paie
            errors: raw.errors,
        };
    }
}

