            </BottomSheet>

            {/* Mobile FAB for Quick Actions */}
            {isMobile && !isEditOpen && (
                <motion.button
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => {
                        const draftIds = shifts
