        const targets: { atom: import('jotai').PrimitiveAtom<import('@/store/base').NexusNode<unknown>>, path: string }[] = [
            { atom: ordersNodeAtom, path: 'operational/orders' },
            { atom: stockItemsNodeAtom, path: 'operational/stock' },
