        pendingModificationsCount,
    } = useKDSController();

    const { floorOps: _floorOps } = useNexusOps();
    const { data: recipes } = useRecipes();

    // Core State
    const [currentTime, setCurrentTime] = useState(new Date());

    // UI State
    const [showModificationAlerts, setShowModificationAlerts] = useState(false);
    const [selectedRecipe, setSelectedRecipe] = useState<Recipe | null>(null);
    const [auditTicket, setAuditTicket] = useState<AuditTicket | null>(null);
    const [isAuditOpen, setIsAuditOpen] = useState(false);

    // Settings
    const columnsFromSettings = usePageSetting('kds', 'columns', 3);
    const [gridColumns, setGridColumns] = useState(columnsFromSettings);

    // kds-6: recall mode
    const [isRecallMode, setIsRecallMode] = useState(false);
    const [recalledOrders, setRecalledOrders] = useState<Order[]>([]);
    const [isRecallLoading, setIsRecallLoading] = useState(false);
    const tenantId = useAtomValue(tenantIdAtom) as string | undefined;

    const [lastOrderCount, setLastOrderCount] = useState(orders.length);

    // Sync settings
    useEffect(() => { setGridColumns(columnsFromSettings); }, [columnsFromSettings]);

    // Clock
    useEffect(() => {
        const timer = setInterval(() => setCurrentTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    // Notification Sound — generated via Web Audio API (no CDN dependency)
    useEffect(() => {
        if (orders.length > lastOrderCount) {
            try {
                const ctx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.frequency.setValueAtTime(880, ctx.currentTime);
                osc.frequency.setValueAtTime(660, ctx.currentTime + 0.12);
                gain.gain.setValueAtTime(0.4, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.28);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.28);
            } catch { /* ignore if AudioContext unavailable */ }
        }
        setLastOrderCount(orders.length);
    }, [orders.length, lastOrderCount]);

    // kds-6: load recalled orders from Nexus when recall mode is activated
    useEffect(() => {
        if (!isRecallMode || !tenantId) return;
        setIsRecallLoading(true);
        Nexus.adapter.query<Order>(
            `tenants/${tenantId}/ops_flows`,
            {
                where: [{ field: 'attributes.status', operator: 'in', value: ['served', 'delivered'] }],
                orderBy: { field: 'updatedAt', direction: 'desc' },
                limit: 20,
            }
        ).then(results => {
            setRecalledOrders(results);
        }).catch(() => {
            // Fallback: filter from in-memory atom data
            const fallback = (orders as Order[])
                .filter(o => o.status === 'served' || o.status === 'delivered')
                .sort((a, b) => (Number(b.updatedAt ?? 0)) - (Number(a.updatedAt ?? 0)))
                .slice(0, 20);
            setRecalledOrders(fallback);
        }).finally(() => {
            setIsRecallLoading(false);
        });
    }, [isRecallMode, tenantId]);

    // kds-3: sort allergic tickets first
    const displayOrders = useMemo(() =>
        [...filteredOrders].sort((a, b) => {
            const aAllergic = hasAllergens(a.items).length > 0 ? 0 : 1;
            const bAllergic = hasAllergens(b.items).length > 0 ? 0 : 1;
            return aAllergic - bAllergic;
        }),
    [filteredOrders]);

    // kds-6: renvoyer (resend) a recalled ticket
    const handleRenvoyer = async (ticket: Order) => {
        try {
            await updateOrderStatus(ticket.id, 'preparing');
            setRecalledOrders(prev => prev.filter(t => t.id !== ticket.id));
            toast.success(`Table ${ticket.tableNumber ?? '?'} — remis en préparation`);
        } catch {
            toast.error('Impossible de renvoyer le ticket');
        }
    };

    return (
        <div className={cn(
            "h-[calc(100vh-80px)] md:h-[calc(100vh-100px)] -m-4 md:-m-8 flex flex-col overflow-hidden animate-fade-in transition-all duration-700",
            "bg-bg-primary text-text-primary",
            rushMode && "bg-error/5"
        )}>
            {/* Rush Mode Atmospheric Overlay */}
            <AnimatePresence>
                {rushMode && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 pointer-events-none z-10 bg-gradient-to-b from-error/5 to-transparent animate-pulse"
                    />
                )}
            </AnimatePresence>

            <KDSHeader
                activeStation={activeStation}
                lockedStation={lockedStation}
                setActiveStation={setActiveStation}
                ordersCount={orders.length}
                preparingOrdersCount={preparingOrdersCount}
                searchQuery={searchQuery}
                setSearchQuery={setSearchQuery}
                gridColumns={gridColumns}
                setGridColumns={setGridColumns}
                currentTime={currentTime}
                rushMode={rushMode}
                setRushMode={setRushMode}
                pendingModificationsCount={pendingModificationsCount}
                setShowModificationAlerts={setShowModificationAlerts}
                isRecallMode={isRecallMode}
                setIsRecallMode={setIsRecallMode}
            />

            {/* Production Display Area */}
            <div className="flex-1 p-4 md:p-10 overflow-auto relative custom-scrollbar bg-bg-primary">
                {/* Immersive Background Decor */}
                <div className="absolute top-[10%] left-[5%] w-[60%] h-[60%] blur-[250px] pointer-events-none rounded-full bg-success-soft/30" />
                <div className="absolute bottom-[10%] right-[5%] w-[50%] h-[50%] blur-[200px] pointer-events-none rounded-full bg-action-primary/5" />

                {/* kds-6: Recall section */}
                <AnimatePresence>
                    {isRecallMode && (
                        <motion.div
                            key="recall-section"
                            initial={{ opacity: 0, y: -20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            className="relative z-10 mb-10"
                        >
                            {/* Recall header */}
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center gap-3">
                                    <div className="w-px h-6 bg-action-primary/50" />
                                    <h2 className="text-sm font-black uppercase tracking-[0.3em] text-action-primary">
                                        Rappel — {isRecallLoading ? '…' : `${recalledOrders.length} ticket${recalledOrders.length !== 1 ? 's' : ''}`}
                                    </h2>
                                </div>
                                <button
                                    onClick={() => setIsRecallMode(false)}
                                    className="flex items-center gap-2 px-4 h-9 rounded-full text-[10px] font-black uppercase tracking-widest text-muted hover:text-primary border border-subtle hover:border-default bg-surface-card transition-all"
                                >
                                    Fermer rappel
                                </button>
                            </div>

                            {isRecallLoading ? (
                                <div className="flex items-center justify-center py-12 text-muted text-sm font-medium">
                                    Chargement…
                                </div>
                            ) : recalledOrders.length === 0 ? (
                                <div className="flex items-center justify-center py-12 text-muted text-sm font-medium">
                                    Aucun ticket servi récemment
                                </div>
                            ) : (
                                <div
                                    className="grid gap-4 relative z-10"
                                    style={{ gridTemplateColumns: `repeat(${gridColumns}, minmax(0, 1fr))` }}
                                >
                                    {recalledOrders.map(ticket => (
                                        <div
                                            key={ticket.id}
                                            className="relative flex flex-col rounded-[20px] border border-subtle bg-surface-bg/50 grayscale-[0.4] opacity-70 hover:opacity-90 hover:grayscale-0 transition-all duration-300 overflow-hidden"
                                        >
                                            {/* Muted ticket summary */}
                                            <div className="flex items-center justify-between p-4 border-b border-subtle">
                                                <div>
                                                    <span className="font-serif italic text-2xl text-primary font-medium">
                                                        Table <span className="text-accent-gold font-bold not-italic">{ticket.tableNumber ?? '?'}.</span>
                                                    </span>
                                                    <p className="text-[10px] font-black uppercase tracking-wider text-muted mt-0.5">
                                                        {ticket.items.length} article{ticket.items.length !== 1 ? 's' : ''}
                                                        {ticket.serverName ? ` · ${ticket.serverName}` : ''}
                                                    </p>
                                                </div>
                                                <span className={cn(
                                                    "px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border",
                                                    ticket.status === 'delivered'
                                                        ? "bg-status-success/10 text-status-success border-status-success/30"
                                                        : "bg-surface-card text-muted border-subtle"
                                                )}>
                                                    {ticket.status}
                                                </span>
                                            </div>

                                            {/* Item list summary */}
                                            <div className="flex-1 px-4 py-3 flex flex-col gap-1">
                                                {ticket.items.slice(0, 4).map((item, i) => (
                                                    <div key={i} className="flex items-center gap-2 text-[11px] text-secondary">
                                                        <span className="w-5 h-5 rounded-full bg-surface-card border border-subtle flex items-center justify-center text-[9px] font-black text-muted shrink-0">
                                                            {item.quantity}
                                                        </span>
                                                        <span className="truncate font-medium">{item.name}</span>
                                                    </div>
                                                ))}
                                                {ticket.items.length > 4 && (
                                                    <p className="text-[10px] text-muted mt-1">+{ticket.items.length - 4} autre{ticket.items.length - 4 > 1 ? 's' : ''}</p>
                                                )}
                                            </div>

                                            {/* Renvoyer button */}
                                            <div className="p-3 pt-0">
                                                <button
                                                    onClick={() => handleRenvoyer(ticket)}
                                                    className="w-full h-10 rounded-[14px] font-black text-[10px] uppercase tracking-[0.2em] bg-action-primary/10 text-action-primary border border-action-primary/30 hover:bg-action-primary hover:text-text-primary transition-all duration-200 active:scale-95"
                                                >
                                                    Renvoyer
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {/* Divider */}
                            <div className="mt-10 flex items-center gap-4">
                                <div className="flex-1 h-px bg-border/40" />
                                <span className="text-[9px] font-black uppercase tracking-[0.4em] text-muted">Production en cours</span>
                                <div className="flex-1 h-px bg-border/40" />
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Active ticket grid */}
                <AnimatePresence mode="popLayout">
                    {displayOrders.length === 0 ? (
                        isLoading ? (
                            <motion.div
                                key="loading"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="flex items-center justify-center py-24 gap-3"
                            >
                                <div className="w-6 h-6 rounded-full border-2 border-accent/30 border-t-accent animate-spin" />
                                <span className="text-[11px] font-black uppercase tracking-[0.3em] text-text-muted">Chargement…</span>
                            </motion.div>
                        ) : (
                            <KDSEmptyState key="empty" />
                        )
                    ) : (
                        <motion.div
                            layout
                            className="grid gap-6 md:gap-10 relative z-10"
                            style={{ gridTemplateColumns: `repeat(${gridColumns}, minmax(0, 1fr))` }}
                        >
                            {displayOrders.map(ticket => (
                                <KDSTicket
                                    key={ticket.id}
                                    ticket={ticket}
                                    fullOrder={orders.find((o: any) => o.id === ticket.id) || ticket}
                                    tenantId={tenantId ?? ''}
                                    gridColumns={gridColumns}
                                    rushMode={rushMode}
                                    updateOrderStatus={updateOrderStatus}
                                    setSelectedRecipe={setSelectedRecipe}
                                    setIsAuditOpen={setIsAuditOpen}
                                    setAuditTicket={setAuditTicket}
                                    recipes={recipes}
                                />
                            ))}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Modals */}
            <ModificationAlertsPanel
                isOpen={showModificationAlerts}
                onClose={() => setShowModificationAlerts(false)}
            />

            {selectedRecipe && (
                <RecipeDetailDialog
                    recipe={selectedRecipe}
                    isOpen={true}
                    onClose={() => setSelectedRecipe(null)}
                />
            )}

            <AnimatePresence>
                {isAuditOpen && auditTicket && (
                    <PlateAuditWizard
                        recipeName={auditTicket.recipeName}
                        standardImage={auditTicket.standardImage}
                        onClose={() => setIsAuditOpen(false)}
                        onComplete={() => {
                            void (async () => {
                                await updateOrderStatus(auditTicket.id, 'ready');
                                // not-2: Push notification when audit wizard confirms ticket ready
                                const fullTicket = displayOrders.find(o => o.id === auditTicket.id);
                                if (fullTicket) {
                                    const serverId = (fullTicket as unknown as { serverId?: string }).serverId;
                                    const pushPayload = {
                                        title: 'Plat prêt !',
                                        body: fullTicket.items.slice(0, 3).map(i => i.name).join(', '),
                                        url: '/pos',
                                    };
                                    if (serverId) {
                                        pushToUser(tenantId ?? '', serverId, pushPayload);
                                    } else {
                                        pushToRole(tenantId ?? '', 'serveur', pushPayload);
                                    }
                                    if (process.env.NODE_ENV !== 'production') {
                                        console.info('[KDS] Push envoyé pour ticket', auditTicket.id);
                                    }
                                }
                                setIsAuditOpen(false);
                                setAuditTicket(null);
                            })();
                        }}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

'use client';

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Table as TableIcon, Search, LayoutGrid, Zap, Bell, RotateCcw } from "lucide-react";
import { cn } from "@/lib/ui.foundations";
import { STATION_CONFIG, KitchenStation } from "@modules/ops/production/kds";

// ─── Types ────────────────────────────────────────────────────────────────────

const LS_KEY_BASE = 'kds-station-filter';

interface KDSHeaderProps {
    activeStation: KitchenStation;
    lockedStation?: KitchenStation | null;
    setActiveStation: (station: KitchenStation) => void;
    ordersCount: number;
    preparingOrdersCount: number;
    searchQuery: string;
    setSearchQuery: (query: string) => void;
    gridColumns: number;
    setGridColumns: (cols: number) => void;
    currentTime: Date;
    rushMode: boolean;
    setRushMode: (mode: boolean) => void;
    pendingModificationsCount: number;
    setShowModificationAlerts: (show: boolean) => void;
    /** kds-6: toggle recall mode */
    isRecallMode: boolean;
    setIsRecallMode: (v: boolean) => void;
}

export function KDSHeader({
    activeStation,
    lockedStation,
    setActiveStation,
    ordersCount,
    preparingOrdersCount,
    searchQuery,
    setSearchQuery,
    gridColumns,
    setGridColumns,
    currentTime,
    rushMode,
    setRushMode,
    pendingModificationsCount,
    setShowModificationAlerts,
    isRecallMode,
    setIsRecallMode,
}: KDSHeaderProps) {
    const [isSearchExpanded, setIsSearchExpanded] = useState(false);
    const [isGridDropdownOpen, setIsGridDropdownOpen] = useState(false);
    const searchRef = useRef<HTMLDivElement>(null);
    const gridDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
                setIsSearchExpanded(false);
            }
            if (gridDropdownRef.current && !gridDropdownRef.current.contains(event.target as Node)) {
                setIsGridDropdownOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div className="relative z-20 w-full border-b border-border/50 bg-bg-primary/60 backdrop-blur-xl shrink-0">
            <div className="w-full overflow-x-auto md:overflow-visible no-scrollbar py-6 px-4 md:px-8">
                <div className="min-w-max mx-auto flex items-center justify-center">
                    <motion.div
                        initial={{ y: -20, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        className="relative z-50 flex items-center gap-1.5 bg-surface-card/80 backdrop-blur-2xl border border-default rounded-full p-2 shadow-2xl ring-1 ring-black/5"
                    >
                        {/* 1. Station Filters */}
                        <div className="flex items-center p-1.5 bg-surface-bg/50 rounded-full border border-black/5 shadow-inner relative group/filters">
                            {(Object.keys(STATION_CONFIG) as KitchenStation[]).map(station => {
                                const config = STATION_CONFIG[station];
                                const Icon = config.icon;
                                const isActive = activeStation === station;
                                const isDisabled = lockedStation ? lockedStation !== station : false;

                                if (lockedStation && lockedStation !== station && lockedStation !== 'all') {
                                    // Optionally we could just hide them entirely if locked:
                                    // return null; 
                                }

                                return (
                                    <button
                                        key={station}
                                        onClick={() => setActiveStation(station)}
                                        disabled={isDisabled}
                                        className={cn(
                                            "relative flex items-center gap-2.5 px-6 h-11 rounded-full font-bold text-[10px] uppercase tracking-[0.2em] transition-colors duration-300 z-10",
                                            isActive ? config.activeText : "text-secondary hover:text-primary",
                                            isDisabled && "opacity-30 cursor-not-allowed hidden md:flex" // Cache sur mobile si bloqué, opaque sur desktop
                                        )}
                                    >
                                        {isActive && (
                                            <motion.div
                                                layoutId="activeFilterPill"
                                                className={cn("absolute inset-0 rounded-full z-[-1] shadow-lg", config.activeBg)}
                                                initial={false}
                                                transition={{ type: "spring", stiffness: 300, damping: 30 }}
                                            />
                                        )}
                                        <Icon className={cn("w-3.5 h-3.5 z-10", isActive ? "text-inherit" : config.iconColor)} strokeWidth={2.5} />
                                        <span className="relative z-10">{config.label}</span>
                                        {isDisabled && lockedStation && <div className="absolute inset-0 z-20 cursor-not-allowed" title="Restreint par RBAC" />}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="w-px h-8 bg-surface-bg mx-2" />

                        {/* 2. Status Badges */}
                        <div className="flex items-center gap-3 px-6 h-12 rounded-full bg-surface-bg/50 border border-black/5">
                            <div className="w-2.5 h-2.5 rounded-full bg-accent-gold animate-pulse shadow-[0_0_12px_rgba(212,175,55,0.6)]" />
                            <div className="flex items-center gap-2.5">
                                <span className="text-[12px] font-black text-accent-gold nums-proportional">
                                    {preparingOrdersCount}<span className="text-muted mx-1">/</span>{ordersCount}
                                </span>
                                <TableIcon className="w-4 h-4 text-muted" strokeWidth={2} />
                            </div>
                        </div>

                        <div className="w-px h-8 bg-surface-bg mx-2" />

                        {/* 4. Search */}
                        <div ref={searchRef} className="relative flex items-center">
                            <AnimatePresence mode="wait">
                                {isSearchExpanded ? (
                                    <motion.div
                                        initial={{ width: 0, opacity: 0 }}
                                        animate={{ width: 260, opacity: 1 }}
                                        exit={{ width: 0, opacity: 0 }}
                                        className="overflow-hidden"
                                    >
                                        <div className="relative mx-2">
                                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-accent-gold" strokeWidth={2.5} />
                                            <input
                                                autoFocus
                                                type="text"
                                                placeholder="RECHERCHER..."
                                                value={searchQuery}
                                                onChange={(e) => setSearchQuery(e.target.value)}
                                                className="w-full h-12 bg-surface-bg border border-transparent focus:border-accent-gold/50 rounded-full pl-10 pr-4 text-[11px] font-bold uppercase tracking-wider focus:outline-none focus:ring-4 focus:ring-accent-gold/10 transition-all placeholder:text-muted"
                                            />
                                        </div>
                                    </motion.div>
                                ) : (
                                    <motion.button
                                        whileHover={{ scale: 1.1 }}
                                        whileTap={{ scale: 0.95 }}
                                        onClick={() => setIsSearchExpanded(true)}
                                        className="w-12 h-12 flex items-center justify-center rounded-full text-muted hover:text-accent-gold hover:bg-surface-bg transition-colors"
                                    >
                                        <Search className="w-5 h-5" strokeWidth={2} />
                                    </motion.button>
                                )}
                            </AnimatePresence>
                        </div>

                        <div className="w-px h-8 bg-surface-bg mx-2" />

                        {/* 5. Grid Selector */}
                        <div ref={gridDropdownRef} className="relative z-[100]">
                            <button
                                onClick={() => setIsGridDropdownOpen(!isGridDropdownOpen)}
                                className={cn(
                                    "flex items-center gap-2.5 px-5 h-12 rounded-full font-bold text-[12px] transition-all border",
                                    isGridDropdownOpen
                                        ? "bg-surface-sidebar text-text-primary border-transparent shadow-lg"
                                        : "bg-transparent border-transparent hover:bg-surface-bg text-secondary"
                                )}
                            >
                                <LayoutGrid className="w-4 h-4" strokeWidth={2} />
                                <span>{gridColumns}</span>
                            </button>
                            <AnimatePresence>
                                {isGridDropdownOpen && (
                                    <motion.div
                                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                        animate={{ opacity: 1, y: 4, scale: 1 }}
                                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                                        className="absolute top-full left-1/2 -translate-x-1/2 mt-2 p-1.5 w-16 bg-surface-card border border-subtle rounded-2xl shadow-xl flex flex-col gap-1 items-center overflow-hidden z-[101]"
                                    >
                                        {[3, 4, 5, 6].map(num => (
                                            <button
                                                key={num}
                                                onClick={() => {
                                                    setGridColumns(num);
                                                    setIsGridDropdownOpen(false);
                                                }}
                                                className={cn(
                                                    "w-full h-8 rounded-xl flex items-center justify-center text-[11px] font-bold transition-all",
                                                    gridColumns === num ? "bg-accent-gold text-text-primary" : "text-secondary hover:bg-surface-bg"
                                                )}
                                            >
                                                {num}
                                            </button>
                                        ))}
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>

                        <div className="w-px h-10 bg-surface-bg mx-4" />

                        {/* 6. Production Info */}
                        <div className="flex items-center gap-4 pr-1 relative z-10">
                            <div className="flex flex-col items-center min-w-[80px]">
                                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-accent-gold mb-0.5">TIME</span>
                                <span className="font-variant-numeric text-xl font-medium tracking-tight text-primary leading-none">
                                    {currentTime.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}
                                </span>
                            </div>

                            <button
                                onClick={() => setRushMode(!rushMode)}
                                className={cn(
                                    "flex items-center gap-3 px-6 h-12 rounded-full font-black text-[10px] uppercase tracking-[0.25em] transition-all border duration-300",
                                    rushMode
                                        ? "bg-status-danger text-text-primary border-red-500 shadow-lg shadow-red-500/20"
                                        : "bg-surface-card border-subtle text-muted hover:text-accent-gold hover:border-accent-gold/50"
                                )}
                            >
                                <Zap className={cn("w-3.5 h-3.5", rushMode ? "fill-white" : "text-current")} strokeWidth={2} />
                                {rushMode ? 'RUSH' : 'NORMAL'}
                            </button>

                            {/* kds-6: Recall mode toggle */}
                            <button
                                onClick={() => setIsRecallMode(!isRecallMode)}
                                className={cn(
                                    "flex items-center gap-2.5 px-5 h-12 rounded-full font-black text-[10px] uppercase tracking-[0.2em] transition-all border duration-300",
                                    isRecallMode
                                        ? "bg-action-primary text-text-primary border-action-primary shadow-lg shadow-purple-500/20"
                                        : "bg-surface-card border-subtle text-muted hover:text-action-primary hover:border-action-primary/40"
                                )}
                            >
                                <RotateCcw className="w-3.5 h-3.5" strokeWidth={2} />
                                RAPPEL
                            </button>

                            <div className="relative pl-2 pr-1">
                                <button
                                    onClick={() => setShowModificationAlerts(true)}
                                    className={cn(
                                        "relative w-12 h-12 flex items-center justify-center rounded-full transition-all duration-300 group hover:scale-110 active:scale-95",
                                        pendingModificationsCount > 0
                                            ? "bg-status-warning text-status-warning ring-2 ring-action-primary/20"
                                            : "bg-surface-bg text-muted hover:bg-surface-bg"
                                    )}
                                >
                                    <Bell className={cn("w-5 h-5 transition-transform group-hover:rotate-12", pendingModificationsCount > 0 && "animate-pulse")} strokeWidth={2} />
                                    {pendingModificationsCount > 0 && (
                                        <span className="absolute -top-1 -right-1 w-5 h-5 bg-status-danger text-text-primary text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white shadow-sm transform group-hover:scale-110 transition-transform">
                                            {pendingModificationsCount}
                                        </span>
                                    )}
                                </button>
                            </div>
                        </div>
                    </motion.div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    Clock,
    ChefHat,
    Book,
    AlertTriangle,
    MessageSquare,
    CheckCircle2,
    Flame,
    GripVertical,
    ChevronDown,
    ChevronUp,
} from "lucide-react";
import { cn } from "@/lib/ui.foundations";
import { Order, OrderItem, OrderStatus, Recipe } from "@nexus/contracts";
import { pushToUser, pushToRole } from '@/lib/push/pushClient';
import { resolveStation } from "@modules/ops/production/kds";

function isTicketWarning(status: string, elapsedMinutes: number): boolean {
    return status !== 'ready' && elapsedMinutes >= 8 && elapsedMinutes < 15;
}
import {
    DndContext,
    closestCenter,
    DragEndEvent,
    PointerSensor,
    useSensor,
    useSensors,
} from "@dnd-kit/core";
import {
    SortableContext,
    useSortable,
    verticalListSortingStrategy,
    arrayMove,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

// ─── Types ────────────────────────────────────────────────────────────────────

interface AuditTicket {
    id: string;
    recipeName: string;
    standardImage?: string;
}

interface KDSTicketProps {
    ticket: Order;
    fullOrder?: Order; // kds-7: Context items
    tenantId: string;
    gridColumns: number;
    rushMode: boolean;
    updateOrderStatus: (id: string, status: OrderStatus) => Promise<void>;
    setSelectedRecipe: (recipe: Recipe) => void;
    setIsAuditOpen: (isOpen: boolean) => void;
    setAuditTicket: (ticket: AuditTicket) => void;
    recipes: Recipe[];
}

/** An order item with a local stable key for DnD and flattening. */
type FlatItem = OrderItem & { _key: string };

// ─── Allergen Detection (kds-3) ───────────────────────────────────────────────

const ALLERGEN_REGEX = /allergi|allergen|intolér/i;

/**
 * Returns distinct allergen strings found in an order's items.
 * Checks modifiers for allergen-related text and any `allergens` extra field.
 */
export function hasAllergens(items: Order['items']): string[] {
    const found: string[] = [];
    for (const item of items) {
        for (const mod of item.modifiers ?? []) {
            const modStr = typeof mod === 'string' ? mod : mod.name;
            if (ALLERGEN_REGEX.test(modStr)) found.push(modStr);
        }
        const extra = item as unknown as { allergens?: unknown };
        if (Array.isArray(extra.allergens)) {
            for (const a of extra.allergens) {
                if (typeof a === 'string' && a) found.push(a);
            }
        } else if (typeof extra.allergens === 'string' && extra.allergens) {
            found.push(extra.allergens);
        }
    }
    return [...new Set(found)];
}

// ─── Timer Helpers (kds-1) ────────────────────────────────────────────────────

function formatElapsed(totalSeconds: number): string {
    const m = Math.floor(Math.max(0, totalSeconds) / 60);
    const s = Math.max(0, totalSeconds) % 60;
    return `${m}m ${s}s`;
}

function timerColorClass(totalSeconds: number): string {
    const minutes = Math.floor(totalSeconds / 60);
    if (minutes < 5) return "text-status-success";
    if (minutes < 10) return "text-orange-400";
    return "text-status-danger animate-pulse";
}

// ─── Sortable Item Wrapper (kds-4) ────────────────────────────────────────────

function SortableItemWrapper({ id, children }: { id: string; children: React.ReactNode }) {
    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
    const style: React.CSSProperties = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
        position: "relative",
    };
    return (
        <div ref={setNodeRef} style={style}>
            {/* Drag handle — visible only on group hover */}
            <div
                {...attributes}
                {...listeners}
                className="absolute top-3 left-2 z-20 p-1 rounded cursor-grab active:cursor-grabbing opacity-0 group-hover:opacity-40 hover:!opacity-70 transition-opacity"
            >
                <GripVertical className="w-3 h-3 text-muted" />
            </div>
            {children}
        </div>
    );
}

// ─── Seat Badge (kds-4) ───────────────────────────────────────────────────────

function SeatBadge({ seat }: { seat: number | string }) {
    return (
        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest bg-action-primary/15 text-action-primary border border-action-primary/30">
            Siège {seat}
        </span>
    );
}

// ─── KDSTicket ────────────────────────────────────────────────────────────────

export function KDSTicket({
    ticket,
    fullOrder,
    tenantId,
    gridColumns,
    rushMode,
    updateOrderStatus,
    setSelectedRecipe,
    setIsAuditOpen,
    setAuditTicket,
    recipes,
}: KDSTicketProps) {

    // ── kds-1: Per-second elapsed timer ──────────────────────────────────────
    const getElapsed = useCallback((): number => {
        const base = ticket.createdAt as number | undefined
            ?? (ticket as unknown as { timestamp?: number | string }).timestamp;
        if (!base) return 0;
        return Math.floor((Date.now() - new Date(base).getTime()) / 1000);
    }, [ticket.createdAt]);

    const [elapsedSeconds, setElapsedSeconds] = useState<number>(getElapsed);
    const [isContextOpen, setIsContextOpen] = useState(false);

    useEffect(() => {
        const id = setInterval(() => setElapsedSeconds(getElapsed()), 1000);
        return () => clearInterval(id);
    }, [getElapsed]);

    const elapsedMinutes = Math.floor(elapsedSeconds / 60);

    // ── kds-3: Allergen detection ─────────────────────────────────────────────
    const allergens = hasAllergens(ticket.items);

    // ── kds-4: Drag-to-reorder ────────────────────────────────────────────────
    const buildFlatItems = useCallback((): FlatItem[] =>
        ticket.items.flatMap((item, ti) => {
            if (((item.modifiers?.length ?? 0) > 0 || item.notes) && item.quantity > 1) {
                return Array.from({ length: item.quantity }, (_, idx) => ({
                    ...item,
                    quantity: 1,
                    _key: `${String(item.id ?? item.name)}-${ti}-${idx}`,
                }));
            }
            return [{ ...item, _key: `${String(item.id ?? item.name)}-${ti}-0` }];
        }),
    [ticket.items]);

    const [sortedItems, setSortedItems] = useState<FlatItem[]>(buildFlatItems);

    useEffect(() => {
        setSortedItems(buildFlatItems());
    }, [buildFlatItems]);

    const sensors = useSensors(useSensor(PointerSensor));

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event;
        if (!over || active.id === over.id) return;
        setSortedItems(prev => {
            const oldIdx = prev.findIndex(i => i._key === String(active.id));
            const newIdx = prev.findIndex(i => i._key === String(over.id));
            return arrayMove(prev, oldIdx, newIdx);
        });
    }, []);

    // ── Derived urgency flags (unchanged logic) ───────────────────────────────
    const isReady   = ticket.status === 'ready';
    const isUrgent  = !isReady && elapsedMinutes >= 15;
    const isWarning = isTicketWarning(ticket.status, elapsedMinutes);

    // ── kds-7: Compute full order grouped by seat ─────────────────────────
    const fullOrderGroupedBySeat = useMemo(() => {
        if (!fullOrder) return {};
        const grouped: Record<string, any[]> = {};
        for (const item of fullOrder.items) {
            const seat = (item as any).seatNumber || 'Partagé';
            if (!grouped[seat]) grouped[seat] = [];
            grouped[seat].push(item);
        }
        return grouped;
    }, [fullOrder]);

    // ── kds-2 + not-2: Mark ticket ready + push notification to server ────────
    const handleMarkReady = useCallback(async () => {
        const itemWithStandard = ticket.items.find((item) => {
            const r = recipes.find(rec => rec.name === item.name);
            return r?.standardImage;
        });
        if (itemWithStandard) {
            setAuditTicket({
                id: ticket.id,
                recipeName: itemWithStandard.name,
                standardImage: recipes.find(r => r.name === itemWithStandard.name)?.standardImage as string,
            });
            setIsAuditOpen(true);
        } else {
            await updateOrderStatus(ticket.id, 'ready');
            const serverId = (ticket as unknown as { serverId?: string }).serverId;
            const pushPayload = {
                title: 'Plat prêt !',
                body: ticket.items.slice(0, 3).map(i => i.name).join(', '),
                url: '/pos',
            };
            if (serverId) {
                pushToUser(tenantId, serverId, pushPayload);
            } else {
                pushToRole(tenantId, 'serveur', pushPayload);
            }
            if (process.env.NODE_ENV !== 'production') {
                console.info('[KDS] Push envoyé pour ticket', ticket.id);
            }
        }
    }, [ticket, recipes, updateOrderStatus, setAuditTicket, setIsAuditOpen]);

    return (
        <motion.div
            layout
            initial={{ opacity: 0, scale: 0.9, y: 40 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.8, transition: { duration: 0.25 } }}
            className={cn(
                "group flex flex-col rounded-[24px] md:rounded-[32px] overflow-hidden border transition-all duration-700 h-fit",
                "bg-surface-card",
                gridColumns >= 5 ? "scale-[0.98]" : "",
                isReady
                    ? "border-subtle bg-surface-bg/50 grayscale-[0.5]"
                    : isUrgent
                        ? "border-error/40 shadow-[0_20px_60px_-15px_rgba(239,68,68,0.25)] ring-1 ring-error/20"
                        : isWarning
                            ? "border-warning/30 shadow-[0_20px_60px_-15px_rgba(245,158,11,0.20)]"
                            : "border border-black shadow-2xl shadow-neutral-200/50 hover:shadow-[0_25px_50px_-12px_rgba(0,0,0,0.15)] hover:border-accent-gold/40"
            )}
        >
            {/* ── Card Header ─────────────────────────────────────────────── */}
            <div className={cn(
                "flex flex-col gap-3 p-5 md:p-6 border-b transition-all duration-700 relative overflow-hidden",
                "bg-surface-bg border-border/50"
            )}>
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-accent-gold/40 to-transparent" />

                {/* kds-3: Allergen banner */}
                {allergens.length > 0 && (
                    <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-status-danger/10 border border-red-500/40 text-status-danger text-[10px] font-black uppercase tracking-wider animate-pulse">
                        <AlertTriangle className="w-3.5 h-3.5 shrink-0" strokeWidth={2.5} />
                        <span>ALLERGIE: {allergens.join(', ')}</span>
                    </div>
                )}

                <div className="relative z-10 flex flex-col gap-3">
                    {/* Row 1: Table number + kds-1 timer badge (top-right) */}
                    <div className="flex items-center justify-between w-full min-h-[40px]">
                        <div className="flex items-center gap-2 min-w-0">
                            <h3 className={cn(
                                "font-serif font-medium tracking-tight italic text-primary leading-none truncate drop-shadow-sm translate-y-0.5",
                                gridColumns >= 5 ? "text-2xl" : "text-3xl lg:text-4xl"
                            )}>
                                Table <span className="text-accent-gold not-italic font-bold">{ticket.tableNumber}.</span>
                            </h3>
                            {(isUrgent || rushMode) && (
                                <div className="flex gap-1 shrink-0 self-center mt-1">
                                    <span className="relative flex h-2.5 w-2.5">
                                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-error opacity-75" />
                                        <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-error" />
                                    </span>
                                </div>
                            )}
                        </div>

                        {/* kds-1: Live timer badge — top-right of card */}
                        <div className={cn(
                            "flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl font-mono text-[11px] font-black border border-current/20 bg-surface-card/70 backdrop-blur-sm shadow-sm shrink-0 transition-colors duration-300",
                            timerColorClass(elapsedSeconds)
                        )}>
                            <Clock className="w-3 h-3" strokeWidth={2.5} />
                            <span>{formatElapsed(elapsedSeconds)}</span>
                        </div>
                    </div>

                    {/* Row 2: Old urgency clock + server info (kept for urgency context) */}
                    <div className="flex items-center justify-between w-full gap-2 h-8">
                        <div className={cn(
                            "h-full px-3 rounded-lg font-mono border transition-all duration-500 flex items-center gap-2 shadow-sm shrink-0 whitespace-nowrap",
                            isUrgent || (rushMode && elapsedMinutes > 5)
                                ? "bg-error text-text-primary border-error shadow-error/20"
                                : isWarning
                                    ? "bg-warning text-text-primary border-warning shadow-warning/20"
                                    : "bg-surface-card text-primary border-subtle"
                        )}>
                            <Clock className={cn("w-3.5 h-3.5", (isUrgent || rushMode) && "animate-spin-slow")} strokeWidth={2.5} />
                            <span className="text-xs font-black pt-0.5">
                                {elapsedMinutes}<span className="text-[9px] opacity-70 ml-0.5 font-normal">MIN</span>
                            </span>
                        </div>

                        <div className="flex items-center gap-3 min-w-0 justify-end h-full">
                            <span className="text-[10px] font-black uppercase tracking-[0.15em] text-secondary truncate text-right leading-none pt-0.5">
                                {ticket.serverName}
                            </span>
                            <div className="w-8 h-8 rounded-full bg-surface-card flex items-center justify-center border border-subtle shrink-0 shadow-sm">
                                <ChefHat className="w-4 h-4 text-primary" strokeWidth={2} />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* ── Item List with DnD (kds-4) ─────────────────────────────── */}
            <div className={cn(
                "flex-1 flex flex-col gap-6",
                gridColumns >= 5 ? "p-4 md:p-5" : "p-5 md:p-7"
            )}>
                <DndContext
                    sensors={sensors}
                    collisionDetection={closestCenter}
                    onDragEnd={handleDragEnd}
                >
                    <SortableContext
                        items={sortedItems.map(i => i._key)}
                        strategy={verticalListSortingStrategy}
                    >
                        {sortedItems.map((item) => {
                            const itemStation = resolveStation(item.name);
                            const product = recipes.find(p =>
                                p.name.includes(item.name) || item.name.includes(p.name)
                            );
                            const imageUrl = product?.imageUrl || product?.standardImage;
                            const isDrink = itemStation === 'bar';
                            const isCold  = itemStation === 'cold';
                            const hasMods = (item.modifiers && item.modifiers.length > 0) || item.notes;

                            const badgeColor = isDrink
                                ? "bg-action-primary text-text-primary shadow-lg shadow-purple-500/20"
                                : isCold
                                    ? "bg-action-primary text-text-primary shadow-lg shadow-blue-500/20"
                                    : "bg-status-danger text-text-primary shadow-lg shadow-red-700/20";

                            const stationLabel = isDrink ? "COCKTAIL" : isCold ? "FROID" : "CHAUD";

                            // kds-4: seat number (may exist as extra field)
                            const seatNumber = (item as unknown as { seatNumber?: number | string }).seatNumber;

                            return (
                                <SortableItemWrapper key={item._key} id={item._key}>
                                    <div className={cn(
                                        "group relative bg-surface-card rounded-[20px] overflow-hidden border shadow-sm hover:shadow-md transition-all duration-500",
                                        hasMods
                                            ? "border-action-primary ring-2 ring-action-primary/50 shadow-[0_0_20px_rgba(245,158,11,0.3)] animate-pulse-slow"
                                            : "border-subtle"
                                    )}>
                                        <div className="relative h-24 w-full overflow-hidden">
                                            <div className="absolute inset-0 bg-surface-bg" />
                                            {imageUrl && (
                                                <img
                                                    src={imageUrl as string}
                                                    alt={item.name}
                                                    className="absolute inset-0 w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-700"
                                                />
                                            )}
                                            <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent opacity-40" />

                                            <div className={cn(
                                                "absolute top-3 left-3 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-default shadow-md",
                                                badgeColor
                                            )}>
                                                {stationLabel}
                                            </div>

                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    const fullRecipe: Recipe = (product || {
                                                        id: `mock_${item.name}`,
                                                        name: item.name,
                                                        category: 'general',
                                                        prepTime: 15,
                                                        cookTime: 10,
                                                        portions: 1,
                                                        difficulty: 'medium',
                                                        ingredients: [],
                                                        steps: [],
                                                        allergens: [],
                                                        dietaryInfo: [],
                                                        costPriceInCents: 0,
                                                        sellingPriceInCents: 0,
                                                        marginInCents: 0,
                                                        isActive: true,
                                                        imageUrl: imageUrl,
                                                        color: '#000000',
                                                        createdAt: new Date(),
                                                        updatedAt: new Date().toISOString(),
                                                    }) as Recipe;
                                                    setSelectedRecipe(fullRecipe);
                                                }}
                                                className="absolute bottom-3 right-3 w-8 h-8 rounded-full bg-surface-sidebar/40 hover:bg-surface-sidebar/60 backdrop-blur-md border border-white/30 flex items-center justify-center text-text-primary transition-all group-hover:scale-110 z-20 shadow-lg"
                                            >
                                                <Book className="w-4 h-4" />
                                            </button>

                                            {item.quantity > 1 && (
                                                <div className="absolute top-3 right-3 px-3 py-1.5 rounded-full bg-status-success text-text-primary flex items-center justify-center text-xs font-black shadow-lg border border-default">
                                                    X {item.quantity}
                                                </div>
                                            )}

                                            {hasMods && item.quantity === 1 && (
                                                <div className="absolute top-3 right-3 px-3 py-1.5 rounded-full bg-status-warning text-text-primary flex items-center justify-center gap-1 text-[10px] font-black shadow-lg border border-default animate-bounce">
                                                    <AlertTriangle className="w-3 h-3 fill-current text-text-primary" />
                                                    MODIF
                                                </div>
                                            )}
                                        </div>

                                        <div className="p-4 relative">
                                            <div className="flex justify-between items-start gap-2 mb-2">
                                                <h4 className="font-serif text-lg font-bold text-primary leading-tight">
                                                    {item.name}
                                                </h4>
                                                {/* kds-4: Seat badge */}
                                                {seatNumber !== undefined && seatNumber !== null && (
                                                    <SeatBadge seat={seatNumber} />
                                                )}
                                            </div>

                                            {item.modifiers && item.modifiers.length > 0 ? (
                                                <div className="flex flex-col gap-1.5 mt-2">
                                                    {item.modifiers.map((m: string | { name: string }, mi: number) => (
                                                        <span key={mi} className="text-xs font-bold text-status-warning flex items-start gap-2">
                                                            <span className="w-1.5 h-1.5 rounded-full bg-status-warning mt-1.5 shrink-0 animate-pulse" />
                                                            {typeof m === 'string' ? m : m.name}
                                                        </span>
                                                    ))}
                                                </div>
                                            ) : (
                                                <p className="text-[11px] font-bold text-muted uppercase tracking-wider mt-1">Recette standard</p>
                                            )}

                                            {item.notes && (
                                                <div className="mt-3 p-2.5 rounded-xl bg-status-warning border border-amber-200 text-status-warning text-xs font-bold leading-tight flex items-start gap-2 animate-pulse">
                                                    <MessageSquare className="w-3.5 h-3.5 shrink-0 mt-0.5 opacity-70" />
                                                    <span>&quot;{item.notes}&quot;</span>
                                                </div>
                                            )}

                                            <div className="mt-4 pt-3 border-t border-dashed border-subtle flex items-center justify-between text-[10px] font-black uppercase tracking-widest text-secondary">
                                                <div className="flex items-center gap-1.5">
                                                    <Clock className="w-3 h-3" />
                                                    <span>{product?.prepTime ?? 15} MIN</span>
                                                </div>
                                                <span>{item.modifiers?.length || 0} OPT.</span>
                                            </div>
                                        </div>
                                    </div>
                                </SortableItemWrapper>
                            );
                        })}
                    </SortableContext>
                </DndContext>
            </div>

            {/* ── kds-7: Table Context Drawer ─────────────────────────────── */}
            {Object.keys(fullOrderGroupedBySeat).length > 0 && (
                <div className="border-t border-subtle bg-surface-bg/30">
                    <button
                        onClick={() => setIsContextOpen(!isContextOpen)}
                        className="w-full flex items-center justify-between p-4 text-secondary hover:text-primary hover:bg-surface-bg transition-colors"
                    >
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black uppercase tracking-[0.15em]">Commande Complète (Accords)</span>
                            <span className="px-2 py-0.5 rounded-full bg-surface-card border border-subtle text-[9px] font-black">
                                {fullOrder?.items.length}
                            </span>
                        </div>
                        {isContextOpen ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                    </button>
                    <AnimatePresence>
                        {isContextOpen && (
                            <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: "auto", opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="overflow-hidden"
                            >
                                <div className="p-4 pt-0 flex flex-col gap-4">
                                    {Object.entries(fullOrderGroupedBySeat).map(([seat, items]) => (
                                        <div key={seat} className="flex flex-col gap-2">
                                            <div className="text-[10px] font-bold text-muted uppercase tracking-wider pl-1 border-b border-subtle pb-1">
                                                {seat === 'Partagé' ? 'À Partager' : `Convive ${seat}`}
                                            </div>
                                            {items.map((cItem: any, i: number) => {
                                                const station = resolveStation(cItem.name);
                                                // Highlight the item if it belongs to the current ticket
                                                const isActiveStation = ticket.items.some(ti => (ti.id || ti.name) === (cItem.id || cItem.name));
                                                return (
                                                    <div key={`${cItem.id || cItem.name}-${i}`} 
                                                         className={cn(
                                                             "flex items-center justify-between p-2 rounded-lg border",
                                                             isActiveStation 
                                                                 ? "bg-surface-card border-accent-gold/30 shadow-sm" 
                                                                 : "bg-surface-bg/50 border-subtle opacity-75 grayscale-[0.5]"
                                                         )}>
                                                        <div className="flex items-center gap-3">
                                                            <div className={cn("w-1.5 h-1.5 rounded-full", isActiveStation ? "bg-accent-gold" : "bg-secondary")} />
                                                            <div className="flex flex-col">
                                                                <span className={cn("text-xs font-bold", isActiveStation ? "text-primary" : "text-secondary")}>
                                                                    {cItem.quantity && cItem.quantity > 1 ? `${cItem.quantity}x ` : ''}{cItem.name}
                                                                </span>
                                                                <span className="text-[9px] text-muted uppercase tracking-wider">{station}</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    ))}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            )}

            {/* ── Action Footer ───────────────────────────────────────────── */}
            <div className="p-6 pt-0 mt-auto">
                <div className="h-px w-full bg-surface-bg mb-6" />
                <AnimatePresence mode="wait">
                    {ticket.status === "ready" ? (
                        <motion.button
                            key="delivered"
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="w-full h-16 rounded-[20px] font-black uppercase tracking-[0.3em] text-[11px] transition-all border border-subtle bg-surface-bg text-secondary hover:bg-surface-bg hover:border-default flex items-center justify-center gap-4 active:scale-[0.98] shadow-sm group"
                            onClick={() => updateOrderStatus(ticket.id, 'delivered')}
                        >
                            <CheckCircle2 className="w-5 h-5 group-hover:text-status-success transition-colors" strokeWidth={2.5} />
                            TERMINER
                        </motion.button>
                    ) : (
                        <motion.div key="progress" className="flex gap-4">
                            {ticket.status === "new" ? (
                                <button
                                    className="w-full h-16 rounded-[20px] font-black uppercase tracking-[0.3em] text-[11px] transition-all bg-surface-bg text-primary hover:bg-surface-bg active:scale-[0.98] shadow-premium flex items-center justify-center gap-3"
                                    onClick={() => updateOrderStatus(ticket.id, 'preparing')}
                                >
                                    <Flame className="w-5 h-5 text-status-warning" strokeWidth={2.5} />
                                    LANCER
                                </button>
                            ) : (
                                <button
                                    className="w-full h-16 rounded-[20px] font-black uppercase tracking-[0.3em] text-[11px] transition-all bg-status-success text-text-primary hover:bg-status-success active:scale-[0.98] shadow-xl shadow-emerald-500/20 flex items-center justify-center gap-3"
                                    onClick={() => { void handleMarkReady(); }}
                                >
                                    <span className="flex items-center gap-3">
                                        PRÊT <CheckCircle2 className="w-5 h-5" strokeWidth={2.5} />
                                    </span>
                                </button>
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </motion.div>
    );
}

'use client';

import { useMemo, useState, useEffect } from 'react';
import { useKitchen } from '@/modules/ops/providers';
import { KitchenStation, resolveStation } from '../contracts/kds-constants';
import { Order } from '@nexus/contracts';
import { useAuth } from '@/infrastructure/auth/hooks/useAuth';

function resolveLockedStation(role?: string): KitchenStation | null {
    if (!role) return null;
    const roleMap: Record<string, KitchenStation> = {
        bartender: 'bar',
        chef_grill: 'hot',
        chef_pastry: 'pastry',
        chef_cold: 'cold',
    };
    return roleMap[role] ?? null;
}

function filterOrdersByStationAndSearch(orders: Order[], station: KitchenStation, searchQuery: string): Order[] {
    let result = (orders ?? []).filter(o => o?.status !== 'delivered');

    if (station !== 'all') {
        result = result
            .filter(order => order.items.some(item => resolveStation(item.name) === station))
            .map(order => ({
                ...order,
                items: order.items.filter(item => resolveStation(item.name) === station),
            }));
    }

    if (searchQuery) {
        const query = searchQuery.toLowerCase();
        result = result.filter(o =>
            (o.tableNumber || "").toLowerCase().includes(query) ||
            (o.serverName || "").toLowerCase().includes(query)
        );
    }

    return result.sort((a, b) => {
        const isAReady = a?.status === 'ready';
        const isBReady = b?.status === 'ready';
        if (isAReady !== isBReady) return isAReady ? 1 : -1;
        return new Date(a.timestamp ?? 0).getTime() - new Date(b.timestamp ?? 0).getTime();
    });
}

/**
 * 👨‍🍳 useKDSController - Grade X Domain Logic
 */
export const useKDSController = () => {
    const { nodes: orders, updateOrderStatus, getPendingModifications, isLoading, error } = useKitchen();
    const { currentUser } = useAuth();


    // RBAC Station Locking
    const lockedStation = useMemo(
        () => resolveLockedStation(currentUser?.role),
        [currentUser?.role]
    );

    // UI State managed at domain level
    const [activeStation, _setActiveStation] = useState<KitchenStation>(() => {
        if (lockedStation) return lockedStation;
        try { return (localStorage.getItem('kds-active-station') as KitchenStation) || 'all'; } 
        catch { return 'all'; }
    });

    useEffect(() => {
        if (lockedStation && activeStation !== lockedStation) {
            _setActiveStation(lockedStation);
        }
    }, [lockedStation, activeStation]);

    const setActiveStation = (s: KitchenStation) => {
        if (lockedStation) return; // Ignore si verrouillé
        _setActiveStation(s);
        try { localStorage.setItem('kds-active-station', s); } catch {}
    };

    const [rushMode, setRushMode] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    // --- Filtering & Sorting Logic (Grade X) ---
    const filteredOrders = useMemo(
        () => filterOrdersByStationAndSearch(orders as Order[], activeStation, searchQuery),
        [orders, activeStation, searchQuery]
    );

    const preparingOrdersCount = useMemo(() => 
        orders.filter((o) => (o as { status?: string })?.status === 'preparing' || o?.status === 'new').length,
    [orders]);

    const pendingModificationsCount = useMemo(() => 
        getPendingModifications().length,
    [getPendingModifications]);

    return {
        // Data
        orders: filteredOrders,
        allOrders: orders,
        isLoading,
        error,

        // Counters
        preparingOrdersCount,
        pendingModificationsCount,

        // State & Actions
        activeStation,
        lockedStation,
        setActiveStation,
        rushMode,
        setRushMode,
        searchQuery,
        setSearchQuery,

        // Mutations
        updateOrderStatus,
        getPendingModifications
    };
};

