import { useState } from "react";
import { motion } from "framer-motion";
import { staggerContainer, fadeInUp } from "@/shared/utils/motion";
import { 
    Save, 
    ShieldCheck, 
    Activity, 
    Database, 
    Utensils, 
    TrendingUp, 
    Cpu, 
    Lock,
    Zap,
    Scale,
