export type NexusEventName = keyof NexusEvents;
export type NexusEventPayload<E extends NexusEventName> = NexusEvents[E];

type Handler<E extends NexusEventName> = (
  payload: NexusEventPayload<E>
) => Promise<void> | void;

interface RegisteredHandler<E extends NexusEventName> {
  id: string;
  event: E;
  handler: Handler<E>;
  priority: 'CRITICAL' | 'HIGH' | 'BACKGROUND';
}

// ── Bus ───────────────────────────────────────────────────────────────────────

class NexusEventBusClass {
  private handlers = new Map<NexusEventName, RegisteredHandler<NexusEventName>[]>();

  /**
   * Souscrit à un événement.
   * priority CRITICAL  → s'exécute en premier, bloquant si nécessaire
   * priority HIGH      → parallèle avec les autres HIGH
   * priority BACKGROUND → lancé après les CRITICAL/HIGH, non-bloquant
   */
  on<E extends NexusEventName>(
    event: E,
    handler: Handler<E>,
    options: { id: string; priority?: RegisteredHandler<E>['priority'] } = { id: crypto.randomUUID() }
  ): () => void {
    const registered: RegisteredHandler<E> = {
      id: options.id,
      event,
      handler,
      priority: options.priority ?? 'HIGH',
    };

    const existing = this.handlers.get(event) ?? [];
    this.handlers.set(event, [...existing, registered]);

    return () => this.off(event, options.id);
  }

  off(event: NexusEventName, id: string): void {
    const existing = this.handlers.get(event) ?? [];
    this.handlers.set(event, existing.filter(h => h.id !== id));
  }

  /**
   * Émet un événement métier de manière durable via l'EventOutbox.
   * Protège contre les crashs entre le persist state (Nexus) et l'exécution des handlers.
   */
  async emitDurable<E extends NexusEventName>(
    event: E,
    payload: NexusEventPayload<E>
  ): Promise<void> {
    const id = crypto.randomUUID();

    // 1. Outbox : Persister l'intention d'émettre
    if (typeof window !== 'undefined') {
      try {
        await db.busOutbox.put({
          id,
          eventName: event,
          payload,
          createdAt: Date.now(),
          attempts: 0,
          status: 'pending'
        });
      } catch (err) {
        logger.error(`[EventBus] Failed to write to Outbox for ${event}`, err);
      }
    }

    // 2. Émettre en RAM
    await this.emit(event, payload);

    // 3. Outbox : Marquer comme terminé
    if (typeof window !== 'undefined') {
      try {
        await db.busOutbox.update(id, { status: 'done' });
      } catch (err) {
        logger.error(`[EventBus] Failed to mark Outbox as done for ${event}`, err);
      }
    }
  }

  /**
   * Émet un événement.
   *
   * Ordre d'exécution :
   * 1. CRITICAL  → await en séquence (ordre d'inscription)
   * 2. HIGH      → Promise.allSettled (parallèle)
   * 3. BACKGROUND → fire-and-forget (microtask, non-bloquant)
   *
   * Retourne quand CRITICAL + HIGH sont résolus.
   * Les erreurs BACKGROUND sont loggées sans propager.
   *
   * @param options.skipDLQWrite — true quand appelé par DLQRetryService ou
   *   handleRetry : le service de retry gère lui-même l'état de l'entrée DLQ
   *   pour éviter une double-écriture avec attempts=1.
   */
  async emit<E extends NexusEventName>(
    event: E,
    payload: NexusEventPayload<E>,
    options?: { skipDLQWrite?: boolean }
  ): Promise<void> {
    const all = this.handlers.get(event) ?? [];
    if (all.length === 0) return;

    const critical    = all.filter(h => h.priority === 'CRITICAL');
    const high        = all.filter(h => h.priority === 'HIGH');
    const background  = all.filter(h => h.priority === 'BACKGROUND');

    const start = performance.now();

    // 1 — CRITICAL : séquentiel, bloquant
    for (const h of critical) {
      try {
        await h.handler(payload);
      } catch (err) {
        logger.error(`[EventBus][CRITICAL] ${event}#${h.id} failed`, err);
        if (typeof window !== 'undefined' && !options?.skipDLQWrite) {
          await db.deadLetterEvents.put({
            id: crypto.randomUUID(),
            eventName: event,
            payload,
            handlerId: h.id,
            error: String(err),
            failedAt: Date.now(),
            attempts: 1,
            nextRetryAt: Date.now() + 2000,
            status: 'retry'
          }).catch(e => logger.error('[EventBus] DLQ write failed', e));
        }
        throw err; // remonte — critique = non négociable
      }
    }

    // 2 — HIGH : parallèle, on attend la résolution
    if (high.length > 0) {
      const results = await Promise.allSettled(
        high.map(h => h.handler(payload))
      );
      await Promise.all(results.map(async (r, i) => {
        if (r.status === 'rejected') {
          const h = high[i];
          logger.error(`[EventBus][HIGH] ${event}#${h.id} failed`, r.reason);
          if (typeof window !== 'undefined' && !options?.skipDLQWrite) {
            await db.deadLetterEvents.put({
              id: crypto.randomUUID(),
              eventName: event,
              payload,
              handlerId: h.id,
              error: String(r.reason),
              failedAt: Date.now(),
              attempts: 1,
              nextRetryAt: Date.now() + 2000,
              status: 'retry'
            }).catch(e => logger.error('[EventBus] DLQ write failed', e));
          }
        }
      }));
    }

    // 3 — BACKGROUND : fire-and-forget
    background.forEach(h => {
      Promise.resolve().then(() => h.handler(payload)).catch(err => {
        logger.warn(`[EventBus][BACKGROUND] ${event}#${h.id} failed`, err);
      });
    });

    const ms = (performance.now() - start).toFixed(1);
    logger.info(`[EventBus] ${event} → ${all.length} handlers (${ms}ms sync)`);
  }
}

export const NexusEventBus = new NexusEventBusClass();

import { NexusEventName, NexusEventPayload } from './NexusEventBus';
import { logger } from '@/lib/logger';

/**
 * 🛠️ PayloadMigrator
 * 
 * Permet de migrer les anciens payloads (ex: ceux persistés hors-ligne dans la BusOutbox)
 * vers le schéma en vigueur dans NexusEvents, notamment l'ajout du `v: 1`.
 */
export const PayloadMigrator = {
  migrate<E extends NexusEventName>(eventName: E, rawPayload: any): NexusEventPayload<E> {
    if (!rawPayload) return rawPayload;

    // Clone pour éviter les mutations
    const payload = { ...rawPayload };

    // Si le payload n'a pas de version, on le monte en v1 par défaut
    if (!payload.v) {
      payload.v = 1;
      logger.info(`[PayloadMigrator] Upgraded legacy payload for ${eventName} to v: 1`);
    }

    return payload as NexusEventPayload<E>;
  }
};

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';
import { AggregatorMappingService } from '@/modules/commerce/relation/delivery/services/AggregatorMappingService';
import { Nexus } from '@/lib/nexus/NexusAdapter';

export function registerAggregatorMenuSyncHandler() {
  return NexusEventBus.on(
    'integration.menu_sync_requested',
    async (payload) => {
      const { tenantId, integrationId, requestedBy } = payload;

      logger.info(`[AggregatorMenuSync] Export du catalogue menu vers l'intégration ${integrationId} (demandé par ${requestedBy}).`);

      // 1. Lire les intégrations actives pour filtrer sur l'integrationId cible
      const activeIntegrations = await AggregatorMappingService.getActiveAdapters(tenantId);
      const targetIntegration = activeIntegrations.find(i => i.adapter.platformId === integrationId);

      if (!targetIntegration) {
          logger.warn(`[AggregatorMenuSync] Intégration ${integrationId} non trouvée ou inactive pour le tenant ${tenantId}.`);
          return;
      }

      // 2. Fetch du catalogue (mock)
      const recipes = await Nexus.adapter.query(`tenants/${tenantId}/recipes`);
      const payloadData = { recipes, mappings: targetIntegration.mappings };

      // 3. Pousser le catalogue vers l'API de l'agrégateur
      const success = await targetIntegration.adapter.pushMenu(tenantId, payloadData);

      empireAudit.log({
        module: 'ops',
        action: 'MENU_SYNC_PUSHED',
        details: { integrationId, requestedBy, success },
        severity: 'low',
        timestamp: new Date(),
      });
    },
    { id: 'aggregator-menu-sync', priority: 'BACKGROUND' }
  );
}

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';
import { AggregatorMappingService } from '@/modules/commerce/relation/delivery/services/AggregatorMappingService';

export function registerAggregatorStockSyncHandler() {
  return NexusEventBus.on(
    'stock.zero',
    async (payload) => {
      const { tenantId, itemId, itemName } = payload;

      logger.info(`[AggregatorStockSync] Produit "${itemName}" (${itemId}) en rupture de stock.`);
      logger.info(`[AggregatorStockSync] Transmission du statut "Indisponible" (86) aux agrégateurs...`);

      // 1. Lire les intégrations actives et leurs mappings
      const activeIntegrations = await AggregatorMappingService.getActiveAdapters(tenantId);
      let syncCount = 0;

      // 2. Transmettre le statut 86 à chaque plateforme
      for (const { adapter, mappings } of activeIntegrations) {
          const externalId = AggregatorMappingService.resolveExternalId(itemId, mappings);
          if (externalId) {
              const success = await adapter.suspendItem(tenantId, externalId);
              if (success) syncCount++;
          } else {
              logger.warn(`[AggregatorStockSync] Impossible de trouver le mapping de "${itemName}" (${itemId}) pour la plateforme ${adapter.platformId}`);
          }
      }

      empireAudit.log({
        module: 'ops',
        action: 'AGGREGATOR_STOCK_ZERO_SYNCED',
        details: { itemId, itemName, syncCount },
        severity: 'high', // Impact CA immédiat
        timestamp: new Date(),
      });
    },
    { id: 'aggregator-stock-sync', priority: 'HIGH' } // Doit être assez rapide pour éviter les rejets de commande
  );
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';

export function registerAntiCorruptionLayerHandler() {
  const unsubOrder = NexusEventBus.on(
    'integration.delivery_order_received',
    async (payload) => {
      const { tenantId, integrationId, platform, rawPayload } = payload;

      const config = await Nexus.adapter.get<any>(`tenants/${tenantId}/integrations/${integrationId}`);

      if (config && config.autoAccept) {
        logger.info(`[ACL] Auto-Accept activé pour ${platform}. Traduction du payload brut vers les événements natifs de l'Empire.`);

        const canonicalOrderId = `order_${crypto.randomUUID()}`;
        const amount = rawPayload.total_price_cents * 100 || 0; 

        await NexusEventBus.emitDurable('order.placed', {
          v: 1,
          tenantId,
          orderId: canonicalOrderId,
          tableId: null,
          operatorId: `integration_${platform}`,
          items: rawPayload.items?.map((i: any) => ({
            productId: i.external_data?.plu ?? i.id,
            name: i.title ?? i.name,
            quantity: i.quantity,
            unitPriceInMicrounits: (i.price_cents ?? 0) * 10_000,
            notes: i.special_instructions ?? '',
          })) ?? []
        });

        await NexusEventBus.emitDurable('order.paid', {
          v: 1,
          tenantId,
          orderId: canonicalOrderId,
          tableId: null,
          operatorId: `integration_${platform}`,
          items: rawPayload.items?.map((i: any) => ({
            productId: i.external_data?.plu ?? i.id,
            name: i.title ?? i.name,
            quantity: i.quantity,
            unitPriceInMicrounits: (i.price_cents ?? 0) * 10_000,
            notes: i.special_instructions ?? '',
          })) ?? [],
          totalInMicrounits: amount,
          paymentMode: platform
        });

        empireAudit.log({
          module: 'ops',
          action: 'ACL_AUTO_ACCEPT_TRANSLATED',
          details: { canonicalOrderId, platform },
          severity: 'low',
          timestamp: new Date(),
        });
      }
    },
    { id: 'anti-corruption-layer', priority: 'HIGH' }
  );

  const unsubResa = NexusEventBus.on(
    'integration.reservation_received',
    async (payload) => {
      const { tenantId, integrationId, platform, rawPayload } = payload as any;

      if (platform === 'lafourchette') {
        logger.info(`[ACL] Traduction de réservation LaFourchette vers l'Empire.`);

        await NexusEventBus.emitDurable('reservation.confirmed', {
          v: 1,
          tenantId,
          reservationId: `resa_${crypto.randomUUID()}`,
          customerName: rawPayload.customer_name || 'Inconnu',
          pax: rawPayload.pax || 2,
          date: rawPayload.date,
          time: rawPayload.time,
          channel: 'lafourchette',
        } as any);

        empireAudit.log({
          module: 'crm',
          action: 'ACL_LAFOURCHETTE_TRANSLATED',
          userId: 'system',
          instanceId: tenantId,
          details: { platform, rawPayload },
          severity: 'low',
          timestamp: new Date(),
        });
      }
    },
    { id: 'acl-reservation', priority: 'HIGH' }
  );

  return () => {
    unsubOrder();
    if (unsubResa) unsubResa();
  };
}

