import { logger } from '@/lib/logger';

export function registerCustomerRFMAnalyzerHandler() {
  return NexusEventBus.on(
    'crm.points_earned',
    async (payload) => {
      const { tenantId, customerId, points } = payload;

      const customerPath = `tenants/${tenantId}/customers/${customerId}`;

      await Nexus.adapter.runTransaction(async (tx) => {
        const customer = await Nexus.adapter.get<any>(customerPath);
        if (!customer) return;

        // Recalcul du RFM simplifié (Récence, Fréquence, Montant)
        const now = Date.now();
        const frequency = (customer.visitCount || 0) + 1;

        let segment = 'new';
        if (frequency > 10) segment = 'vip';
        else if (frequency > 3) segment = 'regular';

        await Nexus.adapter.update(customerPath, {
          lastVisitAt: now,
          visitCount: frequency,
          segment,
          updatedAt: now
        });

        logger.info(`[CustomerRFM] Client ${customerId} mis à jour. Segment actuel: ${segment}.`);
      });

      empireAudit.log({
        module: 'crm',
        action: 'CUSTOMER_RFM_UPDATED',
        details: { customerId },
        severity: 'low',
        timestamp: new Date(),
      });
    },
    { id: 'customer-rfm-analyzer', priority: 'BACKGROUND' }
  );
}

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';
import { AggregatorMappingService } from '@/modules/commerce/relation/delivery/services/AggregatorMappingService';

export function registerDeliveryRushModeHandler() {
  return NexusEventBus.on(
    'store.rush_mode_toggled',
    async (payload) => {
      const { tenantId, isPaused, requestedBy } = payload;

      logger.info(`[DeliveryRushMode] Le tenant ${tenantId} a basculé le mode Rush (Pause=${isPaused}) par ${requestedBy}.`);

      const activeIntegrations = await AggregatorMappingService.getActiveAdapters(tenantId);
      let successCount = 0;

      for (const { adapter } of activeIntegrations) {
          let success = false;
          if (isPaused) {
              success = await adapter.suspendStore(tenantId);
          } else {
              success = await adapter.resumeStore(tenantId);
          }
          if (success) successCount++;
      }

      empireAudit.log({
        module: 'ops',
        action: 'DELIVERY_RUSH_MODE_TOGGLED',
        details: { isPaused, requestedBy, successCount },
        severity: 'high',
        timestamp: new Date(),
      });
    },
    { id: 'delivery-rush-mode', priority: 'HIGH' }
  );
}

import { NexusEventBus, NexusEventPayload, NexusEventName } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

/**
 * Gère la remontée des événements critiques vers le tableau de bord global MCC.
 * Implémente le pattern Outbox pour la synchronisation asynchrone des tenants vers la flotte.
 */
export class FleetOutboxHandler {
  static register() {
    // On écoute les paiements échoués et autres événements critiques pour la flotte
    return NexusEventBus.on('finance.payment_failed', async (payload: NexusEventPayload<'finance.payment_failed'>) => {
      if (payload.isSimulation) return;
      await FleetOutboxHandler.queueEvent('finance.payment_failed', payload);
    }, { id: 'fleet-outbox-finance', priority: 'BACKGROUND' });
  }

  static async queueEvent<T extends NexusEventName>(eventName: T, payload: NexusEventPayload<T>) {
    try {
      const tenantId = (payload as any).tenantId;
      if (!tenantId) {
        logger.warn(`[FleetOutboxHandler] No tenantId on ${eventName} payload, skipping outbox`);
        return;
      }
      const outboxId = `outbox_${Date.now()}_${Math.random().toString(36).substring(7)}`;

      await Nexus.adapter.update(`tenants/${tenantId}/mcc_outbox/${outboxId}`, {
        eventName,
        payload,
        status: 'pending',
        createdAt: Date.now()
      });

      logger.info(`[FleetOutboxHandler] Événement ${eventName} placé dans l'outbox MCC du tenant ${tenantId}`);
    } catch (err) {
      logger.error(`[FleetOutboxHandler] Erreur lors de l'outboxing de ${eventName}`, String(err));
    }
  }
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';

export function registerFloorPlanCapacityHandler() {
  const handleCapacityEvent = async (payload: any, eventType: string) => {
    const { tenantId, scheduledAt, partySize } = payload;

    if (!scheduledAt) return;

    const dateStr = new Date(scheduledAt).toISOString().split('T')[0];
    const hour = new Date(scheduledAt).getHours();
    const service = hour < 16 ? 'lunch' : 'dinner';
    const capacityId = `${dateStr}-${service}`;

    const capacityPath = `tenants/${tenantId}/capacity/${capacityId}`;

    // Lire maxCovers depuis la config tenant (fallback 100)
    const tenantSettings = await Nexus.adapter.get<{ capacity?: number; maxCovers?: number }>(
      `tenants/${tenantId}/settings/general`
    );
    const configuredMaxCovers = tenantSettings?.maxCovers ?? tenantSettings?.capacity ?? 100;

    await Nexus.adapter.runTransaction(async (tx) => {
      const capacityDoc = await Nexus.adapter.get<any>(capacityPath) || { bookedCovers: 0, maxCovers: configuredMaxCovers };

      // Toujours synchroniser maxCovers depuis la config tenant
      capacityDoc.maxCovers = configuredMaxCovers;

      let diff = 0;
      if (eventType === 'reservation.created') diff = partySize;
      if (eventType === 'reservation.cancelled') diff = -partySize;
      if (eventType === 'reservation.updated') {
        diff = payload.updates?.partySizeDiff || 0;
      }

      const newTotal = Math.max(0, capacityDoc.bookedCovers + diff);

      await Nexus.adapter.set(capacityPath, {
        ...capacityDoc,
        bookedCovers: newTotal,
        updatedAt: Date.now()
      });

      // Alerte si le restaurant est complet pour ce service
      if (newTotal >= configuredMaxCovers && diff > 0) {
        logger.warn(`[FloorPlanCapacity] Restaurant complet pour ${capacityId} : ${newTotal}/${configuredMaxCovers} couverts`);
        NexusEventBus.emitDurable('notification.created', {
          v: 1,
          tenantId,
          id: `alert-capacity-full-${capacityId}`,
          type: 'warning',
          title: 'Restaurant Complet',
          message: `Le service ${service === 'lunch' ? 'du midi' : 'du soir'} du ${dateStr} est complet (${newTotal}/${configuredMaxCovers} couverts). Les nouvelles réservations risquent de dépasser la capacité.`,
          priority: 'high',
          read: false,
          timestamp: new Date().toISOString()
        });
      }

      empireAudit.log({
        module: 'ops',
        action: 'CAPACITY_UPDATED',
        details: { capacityId, oldTotal: capacityDoc.bookedCovers, newTotal, maxCovers: configuredMaxCovers },
        severity: newTotal >= configuredMaxCovers ? 'medium' : 'low',
        timestamp: new Date(),
      });
    });
  };

  const unsubCreated = NexusEventBus.on('reservation.created', (p) => handleCapacityEvent(p, 'reservation.created'), { id: 'capacity-created', priority: 'HIGH' });
  const unsubUpdated = NexusEventBus.on('reservation.updated', (p) => handleCapacityEvent(p, 'reservation.updated'), { id: 'capacity-updated', priority: 'HIGH' });
  const unsubCancelled = NexusEventBus.on('reservation.cancelled', (p) => handleCapacityEvent(p, 'reservation.cancelled'), { id: 'capacity-cancelled', priority: 'HIGH' });

  return () => {
    unsubCreated();
    unsubUpdated();
    unsubCancelled();
  };
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import type { Recipe } from '@shared/nexus/contracts/logistics';
import type { Product } from '@/domain/schemas/commerce';

type StockItem = {
  id: string;
  lastCostInMicrounits?: number;
};

function computeProductCostAndImpact(
  product: Product,
  recipesRaw: Record<string, Recipe> | null,
  costMap: Map<string, number>,
  updatedStockItemIds: Set<string>
): { totalCost: number; impacted: boolean } {
  let totalCost = 0;
  let impacted = false;

  if ((product as any).recipeId && recipesRaw) {
    const recipe = recipesRaw[(product as any).recipeId];
    if (recipe && recipe.ingredients) {
      for (const ing of recipe.ingredients) {
        const ingId = ing.ingredientId;
        if (!ingId) continue;
        if (updatedStockItemIds.has(ingId)) impacted = true;
        totalCost += (costMap.get(ingId) ?? 0) * ing.quantity;
      }
    }
  } else if ((product as any).linkedStockItemId) {
    const ingId = (product as any).linkedStockItemId;
    if (updatedStockItemIds.has(ingId)) impacted = true;
    totalCost = costMap.get(ingId) ?? 0;
  }

  return { totalCost, impacted };
}

async function evaluateProductMargin(
  product: Product,
  totalCost: number,
  tenantId: string,
  invoiceId: string
): Promise<void> {
  if (product.priceInMicrounits <= 0) return;

  const margin = product.priceInMicrounits - totalCost;
  const marginBps = Math.floor((margin / product.priceInMicrounits) * 10000);
  const thresholdBps = 2500;

  if (marginBps < thresholdBps) {
    logger.warn(`[FoodCostRecomputer] Marge critique sur ${product.name} : ${marginBps} bps (Seuil: ${thresholdBps})`);
    await NexusEventBus.emitDurable('commerce.margin_warning', {
      v: 1,
      tenantId,
      productId: product.id,
      currentMarginBps: marginBps,
      thresholdBps,
      triggerEventId: invoiceId
    });
  } else {
    logger.info(`[FoodCostRecomputer] ${product.name} marge OK : ${marginBps} bps`);
  }
}

/**
 * P2-3: Inflation Shield - FoodCostRecomputer
 * Recalcule le food cost des produits finis suite à la variation 
 * des prix fournisseurs (réception de facture).
 */
export function registerFoodCostRecomputer(): () => void {
  return NexusEventBus.on(
    'supplier.invoice_processed',
    async (payload) => {
      const { tenantId, invoiceId, lines } = payload;

      try {
        for (const line of lines) {
          await Nexus.adapter.update(
            `tenants/${tenantId}/stockItems/${line.stockItemId}`,
            { lastCostInMicrounits: line.unitCostInMicrounits }
          );
        }

        const stockItemsRaw = await Nexus.adapter.get<Record<string, StockItem>>(`tenants/${tenantId}/stockItems`);
        const stockItems = stockItemsRaw ? Object.values(stockItemsRaw) : [];
        const costMap = new Map<string, number>();
        for (const s of stockItems) {
          costMap.set(s.id, s.lastCostInMicrounits ?? 0);
        }

        const productsRaw = await Nexus.adapter.get<Record<string, Product>>(`tenants/${tenantId}/products`);
        const recipesRaw = await Nexus.adapter.get<Record<string, Recipe>>(`tenants/${tenantId}/recipes`);

        if (!productsRaw) return;
        const products = Object.values(productsRaw);
        const updatedStockItemIds = new Set(lines.map(l => l.stockItemId));

        for (const product of products) {
          const { totalCost, impacted } = computeProductCostAndImpact(product, recipesRaw, costMap, updatedStockItemIds);
          if (impacted) {
            await evaluateProductMargin(product, totalCost, tenantId, invoiceId);
          }
        }
      } catch (e) {
        logger.error('[FoodCostRecomputer] Erreur de recalcul', e);
        throw e;
      }
    },
    { id: 'food-cost-recomputer', priority: 'HIGH' }
  );
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { HermesKnowledgeManager } from '@/modules/intelligence/knowledge/rag/HermesKnowledgeManager';

import { CartItem } from '@/modules/ops/workflow/engine/types';

/**
 * Analyse intelligente BACKGROUND après chaque paiement.
 * Lance en parallèle : analyse stock prédictive + signaux d'alerte.
 * BACKGROUND : fire-and-forget, jamais bloquant.
 * P2: Coalescence (debounce) sur 30s pour limiter la charge LLM.
 */

interface PendingIntelligenceEvent {
  tenantId: string;
  items: CartItem[];
  totalInMicrounits: number;
}

let eventBuffer: PendingIntelligenceEvent[] = [];
let debounceTimeout: NodeJS.Timeout | null = null;

export function registerIntelligenceHandler(): () => void {
  return NexusEventBus.on(
    'order.paid',
    (payload) => {
      eventBuffer.push({
        tenantId: payload.tenantId,
        items: payload.items,
        totalInMicrounits: payload.totalInMicrounits,
      });

      if (!debounceTimeout) {
        debounceTimeout = setTimeout(async () => {
          const batch = [...eventBuffer];
          eventBuffer = [];
          debounceTimeout = null;

          try {
            const byTenant = new Map<string, { items: CartItem[]; totals: number[] }>();
            for (const ev of batch) {
              const existing = byTenant.get(ev.tenantId) ?? { items: [], totals: [] };
              existing.items.push(...ev.items);
              existing.totals.push(ev.totalInMicrounits);
              byTenant.set(ev.tenantId, existing);
            }

            for (const [tenantId, agg] of byTenant.entries()) {
              const promises: Promise<void>[] = [
                analyzeStockTrend(tenantId, agg.items),
              ];
              for (const t of agg.totals) {
                promises.push(analyzeRevenueSignal(tenantId, t));
              }
              await Promise.allSettled(promises);
            }
          } catch (e) {
            logger.error('[Intelligence] Batch processing failed', e);
          }
        }, 30_000);
      }
    },
    { id: 'intelligence-analysis', priority: 'BACKGROUND' }
  );
}

async function analyzeStockTrend(tenantId: string, items: import("@/modules/ops/workflow/engine/types").CartItem[]): Promise<void> {
  try {
    const zcpoState = await readZcpoState();
    if (zcpoState?.memoryPressure === 'critical') return;

    const highVelocityItems = items.filter(i => i.quantity >= 3);
    if (highVelocityItems.length === 0) return;

    const names = highVelocityItems.map((i) => i.name).join(', ');
    const hermes = new HermesKnowledgeManager(tenantId, {
      region: 'FR',
      cuisineType: 'unknown',
      sizeBand: 'small',
      priceBand: 'mid_range',
    });

    const answer = await hermes.query({
      question: `Les articles "${names}" sont commandés en grande quantité. Quel est le risque de rupture de stock et quelle quantité faut-il réapprovisionner ?`,
      focusTypes: ['product', 'supplier'],
    });

    logger.info(`[Intelligence] Stock trend — ${names} → ${answer.answer.slice(0, 120)}`);
  } catch (err) {
    logger.warn('[Intelligence] analyzeStockTrend failed', String(err));
  }
}

interface TicketZDoc {
  totalInMicrounits: number;
  ordersCount: number;
}

async function analyzeRevenueSignal(tenantId: string, totalInMicrounits: number): Promise<void> {
  try {
    // Lire les 7 derniers jours de TicketZ pour calculer moyenne + écart-type
    const today = new Date();
    const samples: number[] = [];

    for (let i = 1; i <= 7; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const doc = await Nexus.adapter.get<TicketZDoc>(`tenants/${tenantId}/ticketZ/${dateStr}`);
      if (doc && doc.ordersCount > 0) {
        // Ticket moyen du jour
        samples.push(doc.totalInMicrounits / doc.ordersCount);
      }
    }

    if (samples.length < 3) {
      logger.info(`[Intelligence] Revenue signal — pas assez d'historique (${samples.length} jours)`);
      return;
    }

    const mean = samples.reduce((a, b) => a + b, 0) / samples.length;
    const variance = samples.reduce((a, b) => a + (b - mean) ** 2, 0) / samples.length;
    const sigma = Math.sqrt(variance);
    const zScore = sigma > 0 ? (totalInMicrounits - mean) / sigma : 0;

    const ticketEur = (totalInMicrounits / 1_000_000).toFixed(2);
    const meanEur = (mean / 1_000_000).toFixed(2);

    if (Math.abs(zScore) > 2) {
      const direction = zScore > 0 ? 'exceptionnellement élevé' : 'exceptionnellement bas';
      logger.warn(
        `[Intelligence] Alerte revenue — ticket ${ticketEur}€ ${direction} (moyenne 7j: ${meanEur}€, z=${zScore.toFixed(2)})`
      );
      NexusEventBus.emitDurable('anomaly.detected', {
        v: 1,
        tenantId,
        type: 'revenue_zscore',
        message: `Ticket ${ticketEur}€ ${direction}`,
        zScore,
        metadata: { meanEur, ticketEur }
      }).catch(() => {});
    } else {
      logger.info(
        `[Intelligence] Revenue signal — ticket ${ticketEur}€ (moyenne 7j: ${meanEur}€, z=${zScore.toFixed(2)})`
      );
    }
  } catch (err) {
    logger.warn('[Intelligence] analyzeRevenueSignal failed', String(err));
  }
}

async function readZcpoState(): Promise<{ memoryPressure: string; idleSeconds: number; isVetoActive: boolean } | null> {
  if (typeof window !== 'undefined') return null;
  try {
    const { readFile } = await import('fs/promises');
    const home = process.env.HOME ?? '/Users/' + process.env.USER;
    const raw = await readFile(`${home}/Library/Application Support/ZCPO/zcpo_state.json`, 'utf-8');
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

