export class PayrollAutoCalcHandler {
  static register() {
    return NexusEventBus.on('payroll.submitted', async (payload) => {
      if (payload.isSimulation) return;
      const { tenantId, period, submissionId, employeeCount } = payload;
      logger.info(
        `[PayrollAutoCalcHandler] Calcul pré-paie déclenché pour ${period} (${employeeCount} employés, tenant: ${tenantId})`
      );

      try {
        // Construire le récapitulatif pré-paie via PrepaieBuilder
        const summary = await PrepaieBuilder.build(tenantId, period);

        // Persister le résultat dans le chemin tenant-scoped
        const periodId = period.replace('-', '');
        await Nexus.adapter.set(
          `tenants/${tenantId}/hr/payroll/${periodId}`,
          {
            ...summary,
            submissionId,
            status: 'calculated',
            calculatedAt: Date.now(),
          }
        );

        logger.info(
          `[PayrollAutoCalcHandler] Pré-paie calculée: ${summary.rows.length} lignes, brut total ${summary.totalBrut}€`
        );

        // Notifier le directeur que la pré-paie est prête
        await browserPush.sendToRole(tenantId, 'directeur', {
          title: 'Pré-paie calculée',
          body: `La pré-paie ${period} est prête : ${summary.rows.length} salariés, brut total ${summary.totalBrut.toFixed(2)}€.`,
        });

        NexusEventBus.emitDurable('notification.created', {
          v: 1,
          tenantId,
          id: `payroll-calc-${periodId}-${Date.now()}`,
          type: 'info',
          title: 'Pré-paie calculée',
          message: `Le calcul pré-paie pour la période ${period} est terminé. ${summary.rows.length} salariés traités, brut total ${summary.totalBrut.toFixed(2)}€.`,
          priority: 'medium',
          read: false,
          timestamp: new Date().toISOString(),
        });

        empireAudit.log({
          action: 'hr.payroll_auto_calc_completed',
          module: 'human',
          userId: 'system',
          instanceId: tenantId,
          details: {
            period,
            submissionId,
            employeeCount: summary.rows.length,
            totalBrutEur: summary.totalBrut,
            totalHeures: summary.totalHeures,
          },
          severity: 'high',
          timestamp: new Date(),
        });
      } catch (error) {
        logger.error(
          `[PayrollAutoCalcHandler] Erreur calcul pré-paie ${period}:`,
          String(error)
        );

        empireAudit.log({
          action: 'hr.payroll_auto_calc_failed',
          module: 'human',
          userId: 'system',
          instanceId: tenantId,
          details: {
            period,
            submissionId,
            error: String(error),
          },
          severity: 'critical',
          timestamp: new Date(),
        });
      }
    }, { id: 'payroll-auto-calc', priority: 'HIGH' });
  }
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';

export function registerPayrollComplianceHandler() {
  return NexusEventBus.on(
    'hr.payroll_exported',
    async (payload) => {
      const { tenantId, periodStart, periodEnd, exportedBy } = payload;

      logger.info(`[PayrollCompliance] Export de paie détecté. Verrouillage des pointages du ${new Date(periodStart).toISOString()} au ${new Date(periodEnd).toISOString()}`);

      // Transaction pour verrouiller tous les shifts de la période.
      // Cela garantit l'immuabilité RH post-export (anti-falsification).

      const shiftsPath = `tenants/${tenantId}/shifts`;
      // Dans une implémentation Firestore réelle, on ferait une query: where('endedAt', '>=', periodStart) ...
      // Pour ce boilerplate, on simule l'obtention de la collection.
      const allShifts = await Nexus.adapter.query(shiftsPath) || [];

      const shiftsToLock = allShifts.filter((s: any) => 
        s.endedAt && s.endedAt >= periodStart && s.endedAt <= periodEnd && !s.locked
      );

      // Verrouillage en batch
      for (const shift of shiftsToLock) {
        await Nexus.adapter.update(`${shiftsPath}/${shift.id}`, {
          locked: true,
          lockedAt: Date.now(),
          lockedByExport: exportedBy
        });
      }

      logger.info(`[PayrollCompliance] ${shiftsToLock.length} pointages ont été définitivement verrouillés.`);

      empireAudit.log({
        module: 'human',
        action: 'PAYROLL_LOCKED',
        details: { periodStart, periodEnd, lockedShiftsCount: shiftsToLock.length, exportedBy },
        severity: 'medium', // Elevé car c'est une action légale structurante
        timestamp: new Date(),
      });
    },
    { id: 'payroll-compliance', priority: 'HIGH' }
  );
}

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { PayrollConnectorFactory } from '@/modules/human/connectors/payroll/PayrollConnectorFactory';
import { PrepaieBuilder } from '@/modules/human/remuneration/payroll/PrepaieBuilder';
import type { PayrollProviderConfig } from '@/modules/human/remuneration/payroll/types';

export class PayrollExportHandler {
  static register() {
    return NexusEventBus.on('hr.preroll_validated', async (payload) => {
      if (payload.isSimulation) return;
      const { tenantId, periodId, validatedBy, totalEmployees } = payload;

      try {
        const providerConfig = await Nexus.adapter.get<PayrollProviderConfig>(
          `tenants/${tenantId}/settings/payroll`
        );

        const providerId = providerConfig?.provider ?? process.env.PAYROLL_DEFAULT_PROVIDER;

        if (!providerId) {
          logger.warn(`[PayrollExportHandler] Aucun provider configuré pour ${tenantId}. Mise en file d'attente.`);
          await Nexus.adapter.update(`tenants/${tenantId}/hr/pendingExports/${periodId}`, {
            periodId, status: 'queued', totalEmployees, queuedAt: Date.now(),
          });
          return;
        }

        logger.info(`[PayrollExportHandler] Export via provider "${providerId}" pour ${periodId}`);
        const connector = PayrollConnectorFactory.get(providerId);
        const summary = await PrepaieBuilder.build(tenantId, periodId);
        const result = await connector.syncPeriod(summary);

        await Nexus.adapter.update(`tenants/${tenantId}/hr/payroll_exports/${periodId}`, {
          periodId,
          provider: connector.id,
          status: result.success ? 'completed' : 'partial',
          employeesUpserted: result.employeesUpserted,
          variablesAccepted: result.variablesAccepted,
          errors: result.errors,
          externalRef: result.externalRef,
          exportedAt: Date.now(),
        });

        empireAudit.log({
          action: 'hr.payroll_export_success',
          module: 'human',
          userId: validatedBy || 'system',
          instanceId: tenantId,
          details: {
            periodId, provider: connector.id, validatedBy, totalEmployees,
            employeesUpserted: result.employeesUpserted,
            variablesAccepted: result.variablesAccepted,
            errors: result.errors,
          },
          severity: 'high',
          timestamp: new Date(),
        });

      } catch (error) {
        logger.error(`[PayrollExportHandler] Erreur export:`, String(error));

        await Nexus.adapter.update(`tenants/${tenantId}/hr/pendingExports/${periodId}`, {
          periodId, status: 'error_queued',
          error: String(error), totalEmployees, queuedAt: Date.now(),
        });

        empireAudit.log({
          action: 'hr.payroll_export_failed',
          module: 'human',
          userId: validatedBy || 'system',
          instanceId: tenantId,
          details: { periodId, error: String(error) },
          severity: 'critical',
          timestamp: new Date(),
        });
      }
    }, { id: 'payroll-export', priority: 'HIGH' });
  }
}

