import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';

export function registerReconciliationEngineHandler() {
  const unsubCompleted = NexusEventBus.on(
    'finance.reconciliation_completed',
    async (payload) => {
      const { tenantId, reconciliationId, bankTransactionId, matchedEntityId, matchedEntityType, reconciledBy } = payload;

      logger.info(`[ReconciliationEngine] Lettrage validé par ${reconciledBy}. Transaction ${bankTransactionId} matchée avec ${matchedEntityType} ${matchedEntityId}.`);

      // Scellement du lettrage
      // La transaction passe à 'reconciled'
      await Nexus.adapter.update(`tenants/${tenantId}/bankTransactions/${bankTransactionId}`, {
        status: 'reconciled',
        reconciliationId,
        reconciledAt: Date.now()
      });

      // L'entité cible (Ticket Z ou Invoice) passe aussi à 'reconciled'
      let targetPath = '';
      if (matchedEntityType === 'invoice') targetPath = `tenants/${tenantId}/fiscalLedger/ap_entry_${matchedEntityId}`;
      else if (matchedEntityType === 'ticket_z') targetPath = `tenants/${tenantId}/fiscalLedger/ticket_z_${matchedEntityId}`;

      if (targetPath) {
        await Nexus.adapter.update(targetPath, {
          status: 'reconciled',
          reconciliationId
        });
      }

      empireAudit.log({
        module: 'finance',
        action: 'RECONCILIATION_SEALED',
        details: { reconciliationId, bankTransactionId, matchedEntityId, matchedEntityType },
        severity: 'high', // Impact comptable NF525 majeur
        timestamp: new Date(),
      });
    },
    { id: 'reconciliation-engine-completed', priority: 'HIGH' }
  );

  const unsubSync = NexusEventBus.on(
    'finance.bank_transaction_synced',
    async (payload) => {
      const { tenantId, transactionId, amountInMicrounits, syncedAt } = payload;
      logger.info(`[ReconciliationEngine] Bank transaction synced: ${transactionId} for ${amountInMicrounits}µ. Running heuristics...`);

      // 1. Chercher un journal entry non lettré avec montant exact
      let matchedEntityId: string | null = null;
      let matchedEntityType: 'ticket_z' | 'invoice' = 'ticket_z';

      // Pour les montants positifs (recettes), chercher dans les journalEntries
      if (amountInMicrounits > 0) {
        const unreconciledEntries = await Nexus.adapter.query<{
          id?: string;
          totalInMicrounits: number;
          status: string;
        }>(`tenants/${tenantId}/journalEntries`, {
          where: [
            { field: 'status', operator: '!=', value: 'reconciled' }
          ]
        });

        const exactMatch = unreconciledEntries.find(
          (entry) => entry.totalInMicrounits === amountInMicrounits
        );
        if (exactMatch) {
          matchedEntityId = exactMatch.id ?? null;
          matchedEntityType = 'ticket_z';
        }
      }

      // Pour les montants négatifs (décaissements), chercher dans les factures fournisseurs
      if (!matchedEntityId && amountInMicrounits < 0) {
        const supplierInvoices = await Nexus.adapter.query<{
          id?: string;
          totalInMicrounits: number;
          status: string;
        }>(`tenants/${tenantId}/supplierInvoices`, {
          where: [
            { field: 'status', operator: '!=', value: 'reconciled' }
          ]
        });

        const invoiceMatch = supplierInvoices.find(
          (inv) => inv.totalInMicrounits === Math.abs(amountInMicrounits)
        );
        if (invoiceMatch) {
          matchedEntityId = invoiceMatch.id ?? null;
          matchedEntityType = 'invoice';
        }
      }

      if (matchedEntityId) {
        logger.info(`[ReconciliationEngine] Exact match found for transaction ${transactionId} -> ${matchedEntityType} ${matchedEntityId}`);

        // Auto-emit le rapprochement
        NexusEventBus.emitDurable('finance.reconciliation_completed', {
          v: 1,
          tenantId,
          reconciliationId: `recon_${Date.now()}`,
          bankTransactionId: transactionId,
          matchedEntityId,
          matchedEntityType,
          reconciledBy: 'system_heuristic'
        });
      } else {
        logger.info(`[ReconciliationEngine] No exact match for ${transactionId}. Added to manual queue.`);

        // Notification pour le DAF
        NexusEventBus.emitDurable('notification.created', {
          v: 1,
          tenantId,
        id: `recon-manual-${transactionId}`,
          type: 'info',
          title: 'Transaction à lettrer',
          message: `Une nouvelle transaction bancaire de ${(amountInMicrounits / 1000000).toFixed(2)}€ nécessite un rapprochement manuel.`,
          priority: 'low',
          read: false,
          timestamp: new Date().toISOString()
        });
      }
    },
    { id: 'reconciliation-engine-synced', priority: 'BACKGROUND' }
  );

  return () => {
    unsubCompleted();
    unsubSync();
  };
}

import { NexusEventBus, NexusEventPayload } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { NotificationGateway } from '@/infrastructure/adapters/NotificationGateway';

export function registerReservationNotifierHandler() {
  const sendNotification = async (tenantId: string, reservationId: string, eventType: string, payload: any) => {
    if (payload.isSimulation) return;
    try {
      // Récupérer le nom du restaurant depuis la config tenant
      const tenantSettings = await Nexus.adapter.get<{ name?: string }>(`tenants/${tenantId}/settings/general`);
      const restaurantName = tenantSettings?.name || 'Notre restaurant';

      const customerName = payload.customerName || 'Client';
      const date = payload.date || '';
      const time = payload.time || '';
      const covers = payload.covers || payload.partySize || '';

      let subject: string;
      let text: string;

      switch (eventType) {
        case 'reservation.confirmed':
          subject = `${restaurantName} — Confirmation de votre réservation`;
          text = [
            `Bonjour ${customerName},`,
            ``,
            `Votre réservation au ${restaurantName} est confirmée :`,
            `  - Date : ${date}`,
            `  - Heure : ${time}`,
            `  - Couverts : ${covers}`,
            `  - Référence : ${reservationId}`,
            ``,
            `Nous avons hâte de vous accueillir. En cas d'empêchement, merci d'annuler au plus tôt.`,
            ``,
            `À bientôt,`,
            `L'équipe ${restaurantName}`
          ].join('\n');
          break;

        case 'reservation.cancelled':
          subject = `${restaurantName} — Annulation de votre réservation`;
          text = [
            `Bonjour ${customerName},`,
            ``,
            `Votre réservation du ${date} à ${time} (${covers} couverts, réf. ${reservationId}) a été annulée.`,
            ``,
            `N'hésitez pas à réserver à nouveau sur notre site.`,
            ``,
            `L'équipe ${restaurantName}`
          ].join('\n');
          break;

        case 'reservation.created':
          subject = `${restaurantName} — Demande de réservation reçue`;
          text = [
            `Bonjour ${customerName},`,
            ``,
            `Nous avons bien reçu votre demande de réservation :`,
            `  - Date : ${date}`,
            `  - Heure : ${time}`,
            `  - Couverts : ${covers}`,
            `  - Référence : ${reservationId}`,
            ``,
            `Vous recevrez une confirmation dès validation par notre équipe.`,
            ``,
            `L'équipe ${restaurantName}`
          ].join('\n');
          break;

        default:
          subject = `${restaurantName} — Mise à jour de votre réservation`;
          text = [
            `Bonjour ${customerName},`,
            ``,
            `Votre réservation du ${date} à ${time} (${covers} couverts, réf. ${reservationId}) a été mise à jour.`,
            `Nouveau statut : ${eventType.replace('reservation.', '')}.`,
            ``,
            `L'équipe ${restaurantName}`
          ].join('\n');
          break;
      }

      await NotificationGateway.send({
          tenantId,
          to: payload.customerId || 'unknown_customer',
          subject,
          text
      });

      // Enregistrement en base de l'envoi de la notification pour traçabilité
      await Nexus.adapter.update(`tenants/${tenantId}/crm/reservations/${reservationId}`, {
          lastNotificationSent: eventType,
          lastNotificationAt: Date.now()
      });
    } catch (err) {
      logger.error(`[ReservationNotifier] Erreur envoi notif pour ${reservationId}`, String(err));
    }
  };

  const unsubCreated = NexusEventBus.on('reservation.created', async (payload) => {
    const { tenantId, reservationId } = payload;
    logger.info(`[ReservationNotifier] Envoi notification client pour reservation.created sur réservation ${reservationId}`);
    await sendNotification(tenantId, reservationId, 'reservation.created', payload);
    empireAudit.log({
      module: 'crm',
      action: 'RESERVATION_NOTIFIED',
      details: { reservationId, eventType: 'reservation.created' },
      severity: 'low',
      timestamp: new Date(),
    });
  }, { id: 'reservation-notifier-created', priority: 'BACKGROUND' });

  const unsubUpdated = NexusEventBus.on('reservation.updated', async (payload) => {
    const { tenantId, reservationId } = payload;
    logger.info(`[ReservationNotifier] Envoi notification client pour reservation.updated sur réservation ${reservationId}`);
    await sendNotification(tenantId, reservationId, 'reservation.updated', payload);
    empireAudit.log({
      module: 'crm',
      action: 'RESERVATION_NOTIFIED',
      details: { reservationId, eventType: 'reservation.updated' },
      severity: 'low',
      timestamp: new Date(),
    });
  }, { id: 'reservation-notifier-updated', priority: 'BACKGROUND' });

  const unsubCancelled = NexusEventBus.on('reservation.cancelled', async (payload) => {
    const { tenantId, reservationId } = payload;
    logger.info(`[ReservationNotifier] Envoi notification client pour reservation.cancelled sur réservation ${reservationId}`);
    await sendNotification(tenantId, reservationId, 'reservation.cancelled', payload);
    empireAudit.log({
      module: 'crm',
      action: 'RESERVATION_NOTIFIED',
      details: { reservationId, eventType: 'reservation.cancelled' },
      severity: 'low',
      timestamp: new Date(),
    });
  }, { id: 'reservation-notifier-cancelled', priority: 'BACKGROUND' });

  const unsubConfirmed = NexusEventBus.on('reservation.confirmed', async (payload: NexusEventPayload<'reservation.confirmed'>) => {
    const { tenantId, reservationId } = payload;
    logger.info(`[ReservationNotifier] Envoi notification client pour reservation.confirmed sur réservation ${reservationId}`);
    await sendNotification(tenantId, reservationId, 'reservation.confirmed', payload);
    empireAudit.log({
      module: 'crm',
      action: 'RESERVATION_NOTIFIED',
      details: { reservationId, eventType: 'reservation.confirmed' },
      severity: 'low',
      timestamp: new Date(),
    });
  }, { id: 'reservation-notifier-confirmed', priority: 'BACKGROUND' });

  return () => {
    unsubCreated();
    unsubUpdated();
    unsubCancelled();
    unsubConfirmed();
  };
}

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/infrastructure/services/audit';
import { logger } from '@/lib/logger';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { SilaeClient } from '@/modules/human/remuneration/payroll/SilaeClient';
import { MergePayrollClient } from '@/modules/human/remuneration/payroll/MergePayrollClient';
import { PrepaieBuilder } from '@/modules/human/remuneration/payroll/PrepaieBuilder';
import type { PayrollProviderConfig } from '@/modules/human/remuneration/payroll/types';

export class SilaeExportHandler {
  static register() {
    return NexusEventBus.on('hr.preroll_validated', async (payload) => {
      if (payload.isSimulation) return;
      const { tenantId, periodId, validatedBy, totalEmployees } = payload;
      logger.info(`[SilaeExportHandler] Exporting payroll for period ${periodId} (Tenant: ${tenantId})`);

      try {
        // Charger la config provider du tenant
        const providerConfig = await Nexus.adapter.get<PayrollProviderConfig>(
          `tenants/${tenantId}/settings/payroll`
        );

        // Construire le summary pré-paie pour la période
        const summary = await PrepaieBuilder.build(tenantId, periodId);

        const silaeKey = providerConfig?.silaeApiKey ?? process.env.SILAE_API_KEY;
        const mergeKey = process.env.MERGE_API_KEY;

        // --- Route 1 : Silae (prioritaire) ---
        if (silaeKey) {
          logger.info(`[SilaeExportHandler] Sync via SilaeClient pour ${periodId}`);
          const silaeClient = new SilaeClient({
            provider: 'silae',
            silaeApiKey: silaeKey,
            silaeDossierId: providerConfig?.silaeDossierId,
            silaeBaseUrl: providerConfig?.silaeBaseUrl,
          });

          const result = await silaeClient.syncPeriod(summary);

          await Nexus.adapter.update(`tenants/${tenantId}/hr/payroll_exports/${periodId}`, {
            periodId,
            provider: 'silae',
            status: result.success ? 'completed' : 'partial',
            employeesUpserted: result.employeesUpserted,
            variablesAccepted: result.variablesAccepted,
            errors: result.errors,
            exportedAt: Date.now(),
          });

          empireAudit.log({
            action: 'hr.silae_export_success',
            module: 'human',
            userId: validatedBy || 'system',
            instanceId: tenantId,
            details: {
              periodId,
              provider: 'silae',
              validatedBy,
              totalEmployees,
              employeesUpserted: result.employeesUpserted,
              variablesAccepted: result.variablesAccepted,
              errors: result.errors,
            },
            severity: 'high',
            timestamp: new Date(),
          });
          return;
        }

        // --- Route 2 : Merge.dev (fallback si clé Merge disponible) ---
        if (mergeKey && providerConfig?.mergeAccountToken) {
          logger.info(`[SilaeExportHandler] Fallback Merge.dev pour ${periodId}`);
          const mergeClient = new MergePayrollClient({
            provider: 'merge',
            mergeAccountToken: providerConfig.mergeAccountToken,
          });

          const result = await mergeClient.syncPeriod(summary);

          await Nexus.adapter.update(`tenants/${tenantId}/hr/payroll_exports/${periodId}`, {
            periodId,
            provider: 'merge',
            status: result.success ? 'completed' : 'partial',
            synced: result.synced,
            errors: result.errors,
            exportedAt: Date.now(),
          });

          empireAudit.log({
            action: 'hr.merge_export_success',
            module: 'human',
            userId: validatedBy || 'system',
            instanceId: tenantId,
            details: {
              periodId,
              provider: 'merge',
              validatedBy,
              totalEmployees,
              synced: result.synced,
              errors: result.errors,
            },
            severity: 'high',
            timestamp: new Date(),
          });
          return;
        }

        // --- Route 3 : Aucune clé, mise en file d'attente ---
        logger.warn(`[SilaeExportHandler] Aucune clé paie configurée. Mode dégradé: mise en file d'attente (pendingExports)`);
        await Nexus.adapter.update(`tenants/${tenantId}/hr/pendingExports/${periodId}`, {
          periodId,
          status: 'queued',
          totalEmployees,
          queuedAt: Date.now(),
        });

      } catch (error) {
        logger.error(`[SilaeExportHandler] Erreur lors de l'export:`, String(error));

        // Mode dégradé en cas d'erreur API
        await Nexus.adapter.update(`tenants/${tenantId}/hr/pendingExports/${periodId}`, {
            periodId,
            status: 'error_queued',
            error: String(error),
            totalEmployees,
            queuedAt: Date.now()
        });

        empireAudit.log({
          action: 'hr.payroll_export_failed',
          module: 'human',
          userId: validatedBy || 'system',
          instanceId: tenantId,
          details: {
            periodId: periodId,
            error: String(error)
          },
          severity: 'critical',
          timestamp: new Date(),
        });
      }
    }, { id: 'silae-export', priority: 'HIGH' });
  }
}

import { NexusEventBus } from '../NexusEventBus';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { empireAudit } from '@/infrastructure/services/audit';
import type { Order } from '@nexus/contracts';
import type { CartItem } from '@/modules/ops/workflow/engine/types';
import { FinancialNexusBridge } from '@/infrastructure/adapters/FinancialNexusBridge';

/**
 * StockRestitutionHandler (P1)
 * Consomme les événements 'order.cancelled' et restitue les stocks au gramme
 * en re-parcourant la BOM des items de la commande (effet inverse de StockDeductionHandler).
 */
export function registerStockRestitutionHandler(): () => void {
  return NexusEventBus.on(
    'order.cancelled',
    async (payload) => {
      const { tenantId, orderId, operatorId, reason } = payload;

      // 1. Lire la commande annulée pour récupérer ses items
      const order = await Nexus.adapter.get<Order>(`tenants/${tenantId}/flows/${orderId}`) 
                 || await Nexus.adapter.get<Order>(`tenants/${tenantId}/deliveryOrders/${orderId}`);

      if (!order || !order.items) {
        logger.warn(`[StockRestitution] Impossible de restituer le stock: commande ${orderId} introuvable ou sans items.`);
        return;
      }

      // 2. Agréger les ingrédients à recréditer via les BOMs (simplifié: on prend les items direct s'ils ont une BOM)
      const restitutions = new Map<string, { qty: number; name: string }>();

      for (const item of order.items) {
        const product = await Nexus.adapter.get<any>(`tenants/${tenantId}/products/${item.productId}`);
        if (!product || !product.recipe || !product.recipe.ingredients) continue;

        for (const ing of product.recipe.ingredients) {
          const needed = (ing.quantity ?? 0) * (item.quantity ?? 1);
          if (needed > 0) {
            const current = restitutions.get(ing.id) ?? { qty: 0, name: ing.name };
            restitutions.set(ing.id, { ...current, qty: current.qty + needed });
          }
        }
      }

      // 3. Appliquer la restitution sur chaque stock item
      for (const [stockItemId, data] of restitutions.entries()) {
        const path = `tenants/${tenantId}/stockItems/${stockItemId}`;
        const stockItem = await Nexus.adapter.get<any>(path);
        if (!stockItem) continue;

        const newQty = (stockItem.quantity ?? 0) + data.qty;

        await Nexus.adapter.update(path, {
          quantity: newQty,
          updatedAt: new Date().toISOString(),
        });

        logger.info(`[StockRestitution] ${data.name} +${data.qty} → nouveau stock ${newQty} (Annulation ${orderId})`);

        empireAudit.log({
          module: 'inventory',
          action: 'STOCK_RESTITUTED',
          details: { orderId, stockItemId, added: data.qty, newQty, reason },
          severity: 'low',
          timestamp: new Date(),
        });
      }

      // 4. (P01-I) Création de l'avoir comptable
      try {
        const cartItemsForRefund = order.items.map(i => ({
          productId: i.productId,
          name: i.name,
          quantity: -1 * (i.quantity ?? 1), // Quantité négative = Avoir
          unitPriceInMicrounits: i.unitPriceInMicrounits ?? 0,
          categoryId: i.categoryId,
          taxRate: i.taxRate
        })) as unknown as CartItem[];

        await FinancialNexusBridge.processOrder({
          cartItems: cartItemsForRefund,
          operatorId,
          tableId: order.tableId ?? null,
          tenantId,
          paymentMode: (order as any).paymentMode ?? 'card', // Remboursement sur le mode original
        });

        // Avoir document for traceability
        await Nexus.adapter.update(`tenants/${tenantId}/avoirs/avoir_${orderId}`, {
          type: 'CREDIT_NOTE',
          orderId,
          operatorId,
          reason,
          totalInMicrounits: cartItemsForRefund.reduce((acc, i) => acc + (i.unitPriceInMicrounits * i.quantity), 0),
          createdAt: Date.now(),
        });

        logger.info(`[StockRestitution] Avoir comptable généré avec succès pour l'annulation ${orderId}`);
      } catch (err) {
        logger.error(`[StockRestitution] Erreur lors de la génération de l'avoir pour ${orderId}`, err);
      }
    },
    { id: 'stock-restitution', priority: 'HIGH' }
  );
}

