"use client";

import React, { useState } from 'react';
import { ShieldAlert, DatabaseBackup, ActivitySquare, Loader2, RotateCcw } from 'lucide-react';
import { useFleet } from '@/shared/contexts/FleetContext';
import { useAuth } from '@/shared/providers/NexusCoreProvider';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

export function DisasterRecoveryPanel() {
  const { instances } = useFleet();
  const { currentUser } = useAuth();
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  const toggleShadowMode = async (tenantId: string) => {
    setLoadingAction(`shadow-${tenantId}`);
    try {
      // Pour la démo, on bascule en 'local_survival' (Offline Cloud)
      const res = await authedFetch('/api/admin/fleet/shadow-mode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, mode: 'local_survival' })
      });
      if (!res.ok) throw new Error('Shadow mode error');
      toast.success(`Shadow Mode activé pour ${tenantId} (Local Survival)`);
    } catch (e) {
      toast.error('Erreur lors de la bascule en Shadow Mode');
    } finally {
      setLoadingAction(null);
    }
  };

  const triggerGlobalBackup = async () => {
    setLoadingAction('backup');
    try {
      const res = await authedFetch('/api/admin/fleet/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
      if (!res.ok) throw new Error('Backup error');
      const data = await res.json();
      toast.success(`Sauvegarde globale déclenchée (${data.succeeded} succès)`);
    } catch (e) {
      toast.error('Erreur lors du déclenchement de la sauvegarde');
    } finally {
      setLoadingAction(null);
    }
  };

  const triggerRestore = async (tenantId: string) => {
    // Dans la vraie vie on demanderait l'heure cible et la raison. Pour la démo :
    const targetTimestamp = new Date(Date.now() - 3600 * 1000).toISOString(); // 1h PITR window
    const reason = 'PRA Automatique (1-Click Restore)';
    const operatorId = currentUser?.id ?? currentUser?.email ?? 'mcc_unknown';

    if (!confirm(`Restauration PITR pour ${tenantId} ? (Attention, annule les écritures depuis 1h)`)) {
      return;
    }

    setLoadingAction(`restore-${tenantId}`);
    try {
      const res = await authedFetch('/api/admin/fleet/restore', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, targetTimestamp, reason, operatorId })
      });
      if (!res.ok) throw new Error('Restore error');
      toast.success(`Restauration initiée pour ${tenantId}`);
    } catch (e) {
      toast.error('Erreur lors de la restauration');
    } finally {
      setLoadingAction(null);
    }
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-rose-500/30 rounded-2xl relative overflow-hidden">
      <div className="absolute top-0 right-0 p-8 opacity-5">
        <ShieldAlert className="w-48 h-48 text-rose-500" />
      </div>

      <div className="flex items-center justify-between mb-6 relative z-10">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-500">
            <ShieldAlert className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-sm font-bold uppercase tracking-widest text-text-primary">Plan de Reprise d'Activité (PRA)</h3>
            <p className="text-xs text-secondary">Restauration Firestore PITR & Sauvegarde Globale</p>
          </div>
        </div>

        <button 
          onClick={triggerGlobalBackup}
          disabled={loadingAction === 'backup'}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white text-xs font-bold uppercase tracking-wider rounded-xl transition-colors disabled:opacity-50"
        >
          {loadingAction === 'backup' ? <Loader2 className="w-4 h-4 animate-spin" /> : <DatabaseBackup className="w-4 h-4" />}
          Sauvegarde Globale
        </button>
      </div>

      <div className="space-y-3 relative z-10">
        {instances.map(inst => (
          <div key={inst.id} className="flex items-center justify-between p-4 bg-surface-card border border-border-subtle rounded-xl">
            <div className="flex items-center gap-3">
              <ActivitySquare className="w-5 h-5 text-secondary" />
              <div>
                <div className="text-sm font-bold">{inst.name || inst.id}</div>
                <div className="text-[10px] text-secondary font-mono">ID: {inst.id}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => toggleShadowMode(inst.id)}
                disabled={loadingAction === `shadow-${inst.id}`}
                className="px-3 py-1.5 flex items-center gap-2 bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 text-[10px] font-black uppercase tracking-widest rounded-lg border border-amber-500/20 transition-colors disabled:opacity-50"
              >
                {loadingAction === `shadow-${inst.id}` ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ShieldAlert className="w-3.5 h-3.5" />}
                Mode Survie
              </button>
              <button
                onClick={() => triggerRestore(inst.id)}
                disabled={loadingAction === `restore-${inst.id}`}
                className="px-3 py-1.5 flex items-center gap-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 text-[10px] font-black uppercase tracking-widest rounded-lg border border-rose-500/20 transition-colors disabled:opacity-50"
              >
                {loadingAction === `restore-${inst.id}` ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />}
                Restauration 1-Clic
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ShieldCheck, Link, Database, Search, CheckCircle2, Lock } from 'lucide-react';
import { useCompliance } from '@/modules/finance/providers/NexusFiscalProvider';
import { format } from 'date-fns';

import { FiscalSeal } from '@modules/finance/types';

interface HashNode {
  index: number;
  hash: string;
  previousHash: string;
  timestamp: string;
  status: 'verified' | 'tampered' | 'pending';
}

export function FiscalChainExplorer({ instanceId }: { instanceId?: string }) {
  const { seals: fiscalSeals = [] } = useCompliance();

  // Memotize the chain nodes from real fiscal seals
  const nodes = useMemo(() => {
    // Filter by instance if provided
    const filteredSeals = instanceId 
      ? (fiscalSeals as unknown as FiscalSeal[]).filter(s => s.instanceId === instanceId)
      : (fiscalSeals as unknown as FiscalSeal[]);

    return filteredSeals
      .sort((a, b) => (b.sequence || 0) - (a.sequence || 0)) // Most recent first
      .map((seal: FiscalSeal): HashNode => ({
        index: seal.sequence || 0,
        hash: seal.hash,
        previousHash: seal.previousHash || 'GENESIS_BLOCK',
        timestamp: format(new Date(seal.timestamp || Date.now()), 'yyyy-MM-dd HH:mm:ss'),
        status: 'verified' // In this view, we show signed seals
      }));
  }, [fiscalSeals, instanceId]);

  const lastUpdate = nodes.length > 0 ? nodes[0].timestamp : 'No data';

  return (
    <div className="bg-surface-card border border-border-subtle rounded-3xl p-6 h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-action-primary/10 rounded-xl">
            <Link className="w-5 h-5 text-brand" />
          </div>
          <div>
            <h3 className="text-sm font-bold uppercase tracking-widest text-muted">Fiscal Chain Explorer</h3>
            <p className="text-[10px] text-secondary font-medium">Node: {instanceId || 'Global Fleet'}</p>
          </div>
        </div>

        <div className="flex items-center gap-2 px-3 py-1 bg-status-success/5 border border-emerald-500/10 rounded-full">
          <div className="w-1.5 h-1.5 rounded-full bg-status-success animate-pulse" />
          <span className="text-[10px] font-bold text-status-success uppercase tracking-tighter">Live Chain</span>
        </div>
      </div>

      <div className="relative flex-1 overflow-y-auto pr-2 space-y-4 scrollbar-hide">
        <AnimatePresence initial={false}>
          {nodes.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-secondary opacity-50 py-12">
              <Lock className="w-8 h-8 mb-3 stroke-1" />
              <p className="text-[11px] uppercase tracking-[0.2em] text-center">
                Waiting for first<br/>cryptographic seal...
              </p>
            </div>
          ) : (
            nodes.map((node, i) => (
              <motion.div 
                key={`${node.index}-${node.hash}`}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.4, delay: i * 0.05 }}
                className="p-4 bg-surface-card border border-border-subtle rounded-2xl relative group hover:border-focus/30 transition-all cursor-crosshair"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-brand/50 uppercase tracking-tighter">Sequence</span>
                    <span className="text-[12px] font-mono text-muted">BLOCK_#{node.index.toString().padStart(6, '0')}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[9px] font-bold text-status-success/70 border border-emerald-500/20 px-1.5 py-0.5 rounded uppercase tracking-tighter bg-status-success/5">Signed</span>
                    <CheckCircle2 className="w-4 h-4 text-status-success" />
                  </div>
                </div>

                <div className="space-y-3 mt-4">
                  <div className="flex flex-col space-y-1">
                    <div className="flex items-center justify-between text-[9px] font-black text-secondary uppercase tracking-tighter">
                      <span>Hash Actuel</span>
                      <span className="text-primary italic">SHA-256</span>
                    </div>
                    <div className="p-2 bg-surface-card rounded-lg border border-border-subtle font-mono text-[10px] text-brand break-all leading-tight relative overflow-hidden group-hover:text-brand transition-colors">
                      {node.hash}
                      <motion.div 
                        initial={{ x: '-100%' }}
                        whileHover={{ x: '100%' }}
                        transition={{ duration: 0.5 }}
                        className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent"
                      />
                    </div>
                  </div>

                  <div className="flex flex-col space-y-1">
                    <span className="text-[9px] font-black text-secondary uppercase tracking-tighter">Back-Link Pointer</span>
                    <div className="font-mono text-[10px] text-secondary truncate opacity-60 group-hover:opacity-100 transition-opacity">
                      {node.previousHash}
                    </div>
                  </div>
                </div>

                <div className="mt-4 pt-3 border-t border-border-subtle flex justify-between items-center">
                  <div className="flex items-center gap-2">
                    <Search className="w-3 h-3 text-secondary" />
                    <span className="text-[9px] text-secondary font-medium">{node.timestamp}</span>
                  </div>
                  <ShieldCheck className="w-3 h-3 text-brand/50" />
                </div>

                {/* Visual Continuity Link with Electron Flow */}
                {i < nodes.length - 1 && (
                  <div className="absolute -bottom-4 left-6 w-0.5 h-4 bg-surface-card z-0">
                    <motion.div 
                      animate={{ top: ['0%', '100%'], opacity: [0, 1, 0] }}
                      transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }}
                      className="absolute inset-0 bg-gradient-to-b from-transparent via-action-primary to-transparent"
                    />
                  </div>
                )}
              </motion.div>
            ))
          )}
        </AnimatePresence>
