                              {device.status}
                            </span>
                            {device.trackingNumber && (
                              <span className="text-[9px] text-secondary font-mono flex items-center gap-1">
                                <Truck className="w-3 h-3" /> {device.trackingNumber}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        {device.status === 'SHIPPED' && (
                          <button onClick={() => setPendingDelivery({ tenantId: row.tenantId, device })} className="p-2 bg-emerald-500/10 text-status-success rounded-lg hover:bg-emerald-500/20 transition-all border border-emerald-500/20" title="Confirmer Livraison (Déclenche Stripe)">
                            <CheckCircle className="w-4 h-4" />
                          </button>
                        )}
                        <button onClick={() => toggleKillSwitch(row.tenantId, device)} className={`p-2 rounded-lg transition-all border ${device.status === 'LOCKED' ? 'bg-status-danger text-white border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'bg-surface-card text-status-danger hover:bg-status-danger/10 border-red-500/20'}`} title="Kill Switch (Verrouillage MDM)">
                          <PowerOff className="w-4 h-4" />
                        </button>
                        <button onClick={() => removeDevice(row.tenantId, device.serialNumber)} className="p-2 bg-surface-card text-muted rounded-lg hover:text-status-danger hover:bg-status-danger/10 transition-all">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {row.devices.length === 0 && !row.error && (
                <p className="text-[11px] text-secondary italic text-center py-2">Aucun matériel affecté à cette instance.</p>
              )}

              {/* Add Device Form */}
              <div className="mt-4 p-3 bg-surface-bg border border-border-subtle rounded-xl space-y-3">
                <div className="flex items-center gap-2">
                  <select 
                    value={input.type} 
                    onChange={e => setInputMap(m => ({ ...m, [row.tenantId]: { ...input, type: e.target.value as EnrollmentType } }))}
                    className="bg-surface-card border border-border-subtle rounded-lg px-2 py-1.5 text-xs text-text-primary focus:outline-none focus:border-brand"
                  >
                    <option value="NATIVE_ABM">ABM (Neuf)</option>
                    <option value="SOFTWARE_MDM">MDM (Recond.)</option>
                  </select>
                  <input
                    value={input.sn}
                    onChange={e => setInputMap(m => ({ ...m, [row.tenantId]: { ...input, sn: e.target.value } }))}
                    placeholder="S/N (ex: C07X...)"
                    className="flex-1 bg-surface-card border border-border-subtle rounded-lg px-3 py-1.5 text-xs font-mono placeholder:text-secondary/40 focus:outline-none focus:border-brand"
                  />
                </div>
                <div className="flex gap-2">
                  <input
                    value={input.tracking}
                    onChange={e => setInputMap(m => ({ ...m, [row.tenantId]: { ...input, tracking: e.target.value } }))}
                    placeholder="N° Suivi Transporteur (Optionnel)"
                    className="flex-1 bg-surface-card border border-border-subtle rounded-lg px-3 py-1.5 text-[10px] font-mono placeholder:text-secondary/40 focus:outline-none focus:border-brand"
                  />
                  <button
                    onClick={() => addDevice(row.tenantId)}
                    disabled={saving[row.tenantId] || !input.sn.trim()}
                    className="flex items-center gap-1 bg-brand text-white text-xs font-bold px-4 py-1.5 rounded-lg hover:bg-brand/90 transition-all disabled:opacity-40"
                  >
                    <Plus className="w-3 h-3" /> Ajouter
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>

    {pendingDelivery && (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-surface-sidebar/80 backdrop-blur-sm" onClick={() => !confirming && setPendingDelivery(null)} />
        <div className="relative w-full max-w-sm bg-surface-bg border border-border-subtle rounded-2xl p-6 shadow-2xl">
          <div className="flex items-start gap-3 mb-4">
            <div className="w-10 h-10 rounded-xl bg-status-success/10 border border-emerald-500/20 flex items-center justify-center shrink-0">
              <Truck className="w-5 h-5 text-status-success" />
            </div>
            <div>
              <h3 className="text-sm font-bold uppercase tracking-widest mb-1">Confirmer la livraison</h3>
              <p className="text-xs text-secondary leading-relaxed">
                Cette action démarre la <span className="text-text-primary font-semibold">facturation Stripe</span> pour l&apos;appareil{' '}
                <span className="font-mono text-brand">{pendingDelivery.device.serialNumber}</span>.
                Elle ne peut pas être annulée.
              </p>
            </div>
          </div>
          <div className="flex gap-3 mt-6">
            <button
              onClick={() => setPendingDelivery(null)}
              disabled={confirming}
              className="flex-1 py-2.5 text-xs font-bold uppercase tracking-widest text-secondary hover:text-text-primary transition-colors disabled:opacity-40"
            >
              Annuler
            </button>
            <button
              onClick={async () => {
                setConfirming(true);
                await simulateDelivery(pendingDelivery.tenantId, pendingDelivery.device);
                setConfirming(false);
                setPendingDelivery(null);
              }}
              disabled={confirming}
              className="flex-1 py-2.5 bg-status-success text-white text-xs font-bold uppercase tracking-widest rounded-xl hover:opacity-90 transition-all active:scale-95 disabled:opacity-50"
            >
              {confirming ? 'Facturation…' : 'Confirmer & Facturer'}
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Activity, AlertTriangle, Wifi, WifiOff } from 'lucide-react';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

export function FleetTelemetryPanel() {
  const [devices, setDevices] = useState<any[]>([]);
  const [crashes, setCrashes] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    const fetchTelemetry = async () => {
      try {
        const [devs, crs] = await Promise.all([
          Nexus.adapter.query('mcc/telemetry/devices'),
          Nexus.adapter.query('mcc/telemetry/crashes')
        ]);
        if (!active) return;
        setDevices(devs as any[]);
        setCrashes(crs as any[]);
      } catch (e) {
        logger.error('Failed to fetch telemetry', { error: e });
      } finally {
        if (active) setLoading(false);
      }
    };

    fetchTelemetry();
    const id = setInterval(fetchTelemetry, 30000); // refresh every 30s
    return () => { active = false; clearInterval(id); };
  }, []);

  const now = new Date().getTime();

  // Heartbeat > 3 minutes (180000 ms) = Offline
  const offlineDevices = devices.filter(d => {
    if (!d.lastSeen) return true;
    return (now - new Date(d.lastSeen).getTime()) > 180000;
  });

  const onlineDevices = devices.length - offlineDevices.length;

  return (
    <div className="bg-surface-card border border-border-subtle rounded-3xl p-6 relative overflow-hidden">
      <div className="absolute top-0 right-0 p-8 opacity-5">
        <Activity className="w-32 h-32" />
      </div>

      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 bg-indigo-500/10 rounded-xl border border-indigo-500/20 text-indigo-400">
          <Activity className="w-5 h-5" />
        </div>
        <div>
          <h3 className="text-sm font-bold uppercase tracking-widest">Télémétrie de la Flotte</h3>
          <p className="text-xs text-secondary">Signaux de vie & Rapports de plantage en temps réel</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="p-4 bg-surface-card border border-border-subtle rounded-2xl flex flex-col">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-black uppercase tracking-widest text-secondary">Pouls Réseau</span>
            {offlineDevices.length === 0 ? (
              <Wifi className="w-4 h-4 text-emerald-500" />
            ) : (
              <WifiOff className="w-4 h-4 text-rose-500" />
            )}
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-bold tabular-nums">{onlineDevices}</span>
            <span className="text-xs text-secondary">/ {devices.length} En Ligne</span>
          </div>
          {offlineDevices.length > 0 && (
            <div className="mt-2 text-[10px] text-rose-500 font-bold uppercase tracking-widest">
              {offlineDevices.length} Instance(s) Hors Ligne
            </div>
          )}
        </div>

        <div className="p-4 bg-surface-card border border-border-subtle rounded-2xl flex flex-col">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-black uppercase tracking-widest text-secondary">Rapports de Plantage</span>
            <AlertTriangle className={`w-4 h-4 ${crashes.length > 0 ? 'text-amber-500' : 'text-emerald-500'}`} />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-bold tabular-nums">{crashes.length}</span>
            <span className="text-xs text-secondary">Enregistrés</span>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        <div>
          <h4 className="text-[10px] font-black uppercase tracking-widest text-secondary mb-3">Nœuds Critiques Hors Ligne</h4>
          {loading ? (
            <div className="text-xs text-muted animate-pulse">Analyse en cours...</div>
          ) : offlineDevices.length === 0 ? (
            <div className="text-xs text-emerald-500 font-medium">Tous les nœuds transmettent un signal nominal.</div>
          ) : (
            <div className="space-y-2">
              {offlineDevices.slice(0, 5).map(d => (
                <div key={d.deviceId} className="flex items-center justify-between p-3 bg-rose-500/5 border border-rose-500/20 rounded-xl">
                  <div>
                    <div className="text-xs font-bold text-text-primary">{d.tenantId}</div>
                    <div className="text-[10px] text-secondary">Appareil : {d.deviceId}</div>
                  </div>
                  <div className="text-[10px] text-rose-500 font-bold uppercase">
                    Vu le : {d.lastSeen ? new Date(d.lastSeen).toLocaleTimeString() : 'Inconnu'}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {crashes.length > 0 && (
          <div className="pt-4 border-t border-border-subtle">
            <h4 className="text-[10px] font-black uppercase tracking-widest text-secondary mb-3">Derniers Plantages</h4>
            <div className="space-y-2">
              {crashes.slice(0, 5).map(c => (
                <div key={c.id} className="flex items-center justify-between p-3 bg-amber-500/5 border border-amber-500/20 rounded-xl">
                  <div className="truncate pr-4">
                    <div className="text-xs font-bold text-amber-500">{c.errorName}</div>
                    <div className="text-[10px] text-secondary truncate">{c.errorMessage}</div>
                  </div>
                  <div className="text-[10px] text-secondary whitespace-nowrap">
                    {c.tenantId}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Package, Plus, Trash2, Edit2, Loader2, Save, X } from 'lucide-react';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

interface CatalogItem {
  id: string;
  name: string;
  basePrice: number;
  category: string;
}

export function PluginCatalogManager() {
  const [catalog, setCatalog] = useState<CatalogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<CatalogItem>>({});

  const [isCreating, setIsCreating] = useState(false);

  const loadCatalog = async () => {
    setLoading(true);
    try {
      const res = await authedFetch('/api/admin/fleet/catalog');
      if (!res.ok) throw new Error('Erreur de chargement');
      const data = await res.json();
      const itemsArray = Object.entries(data.catalog || {}).map(([id, val]: any) => ({
        id,
        ...val
      }));
      setCatalog(itemsArray);
    } catch (e) {
      toast.error('Impossible de charger le catalogue');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadCatalog();
  }, []);

  const handleSave = async (id: string, form: Partial<CatalogItem>) => {
    if (!id.trim()) { toast.error('L\'identifiant du plugin est obligatoire'); return; }
    if (!form.name?.trim()) { toast.error('Le nom du plugin est obligatoire'); return; }
    try {
      const payload = { id: id.trim(), ...form };
      const res = await authedFetch('/api/admin/fleet/catalog', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error('Save error');
      toast.success('Offre sauvegardée avec succès');
      setEditingId(null);
      setIsCreating(false);
      await loadCatalog();
    } catch (e) {
      toast.error('Erreur lors de la sauvegarde');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Voulez-vous vraiment supprimer cette offre du catalogue ?')) return;
    try {
      const res = await authedFetch(`/api/admin/fleet/catalog?id=${encodeURIComponent(id)}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error('Delete error');
      toast.success('Offre supprimée');
      await loadCatalog();
    } catch (e) {
      toast.error('Erreur lors de la suppression');
    }
  };

  const startEdit = (item: CatalogItem) => {
    setEditingId(item.id);
    setEditForm(item);
  };

  const startCreate = () => {
    setIsCreating(true);
    setEditForm({ id: '', name: '', basePrice: 0, category: 'General' });
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-border-subtle rounded-2xl">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Package className="w-5 h-5 text-brand" />
          <h3 className="text-sm font-bold uppercase tracking-widest text-text-secondary">Gestion du Catalogue</h3>
        </div>
        <button
          onClick={startCreate}
          className="flex items-center gap-2 px-3 py-1.5 bg-brand/10 hover:bg-brand/20 text-brand text-xs font-bold rounded-lg transition-colors"
        >
          <Plus className="w-3.5 h-3.5" /> Nouvelle Offre
        </button>
      </div>

      {loading ? (
        <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-brand" /></div>
      ) : (
        <div className="space-y-4">
          {isCreating && (
            <div className="p-4 bg-brand/5 border border-brand/20 rounded-xl space-y-3">
              <div className="grid grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="ID Unique (ex: my_plugin)"
                  value={editForm.id || ''}
                  onChange={e => setEditForm({ ...editForm, id: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="text" 
                  placeholder="Nom de l'offre"
                  value={editForm.name || ''}
                  onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="number" 
                  placeholder="Prix mensuel (€)"
                  value={editForm.basePrice || ''}
                  onChange={e => setEditForm({ ...editForm, basePrice: parseFloat(e.target.value) })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="text" 
                  placeholder="Catégorie (ex: Marketing)"
                  value={editForm.category || ''}
                  onChange={e => setEditForm({ ...editForm, category: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
              </div>
              <div className="flex justify-end gap-2">
                <button onClick={() => setIsCreating(false)} className="px-3 py-1.5 text-xs text-secondary hover:text-text-primary">Annuler</button>
                <button onClick={() => handleSave(editForm.id!, editForm)} className="px-3 py-1.5 bg-brand text-white text-xs font-bold rounded-lg flex items-center gap-1">
                  <Save className="w-3.5 h-3.5" /> Sauvegarder
                </button>
              </div>
            </div>
          )}

          {catalog.map(item => (
            <div key={item.id} className="flex items-center justify-between p-4 bg-surface-card border border-border-subtle rounded-xl group hover:border-focus/30 transition-all">
              {editingId === item.id ? (
                <div className="flex-1 grid grid-cols-4 gap-4 mr-4">
                  <input 
                    type="text" 
                    value={editForm.name || ''}
                    onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm col-span-2"
                  />
                  <input 
                    type="number" 
                    value={editForm.basePrice !== undefined ? editForm.basePrice : ''}
                    onChange={e => setEditForm({ ...editForm, basePrice: parseFloat(e.target.value) })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm"
                  />
                  <input 
                    type="text" 
                    value={editForm.category || ''}
                    onChange={e => setEditForm({ ...editForm, category: e.target.value })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm"
                  />
                </div>
              ) : (
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-text-primary">{item.name}</span>
                    <span className="px-2 py-0.5 bg-brand/10 text-brand text-[10px] font-black rounded uppercase tracking-widest">{item.category}</span>
                  </div>
                  <div className="text-[10px] text-secondary font-mono mt-1">ID: {item.id}</div>
                </div>
              )}

              <div className="flex items-center gap-4">
                {editingId !== item.id && (
                  <div className="text-sm font-bold">{item.basePrice.toFixed(2)} € <span className="text-[10px] text-secondary font-normal">/ mois</span></div>
                )}

                <div className="flex items-center gap-2">
                  {editingId === item.id ? (
                    <>
                      <button onClick={() => setEditingId(null)} className="p-1.5 text-secondary hover:text-text-primary"><X className="w-4 h-4" /></button>
                      <button onClick={() => handleSave(item.id, editForm)} className="p-1.5 bg-emerald-500/10 text-emerald-500 rounded"><Save className="w-4 h-4" /></button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => startEdit(item)} className="p-1.5 text-secondary hover:text-text-primary opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 className="w-4 h-4" /></button>
                      <button onClick={() => handleDelete(item.id)} className="p-1.5 text-rose-500 hover:bg-rose-500/10 rounded opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-4 h-4" /></button>
                    </>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { PackageOpen, ToggleLeft, ToggleRight, Loader2, ServerCog, Store } from 'lucide-react';
import { useFleet } from '@/shared/contexts/FleetContext';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

interface CatalogItem {
  name: string;
  basePrice: number;
  category?: string;
}

interface TenantPluginState {
  tenantId: string;
  activePlugins: Record<string, { active: boolean, activatedAt?: string }>;
}

export function PluginEnginePanel() {
  const { instances } = useFleet();
  const [pluginsByTenant, setPluginsByTenant] = useState<TenantPluginState[]>([]);
  const [dynamicCatalog, setDynamicCatalog] = useState<Record<string, CatalogItem>>({});
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    try {
      let latestCatalog = {};
      const results = await Promise.allSettled(
        instances.map(async inst => {
          const res = await authedFetch(`/api/admin/fleet/plugins?tenantId=${encodeURIComponent(inst.id)}`);
          return res.ok ? (await res.json()) : null;
        })
      );

      const parsedResults = results
        .filter((r): r is PromiseFulfilledResult<any> => r.status === 'fulfilled' && r.value !== null)
        .map(r => {
          latestCatalog = { ...latestCatalog, ...r.value.catalog };
          return { tenantId: r.value.tenantId, activePlugins: r.value.activePlugins };
        });

      setDynamicCatalog(latestCatalog);
      setPluginsByTenant(parsedResults);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (instances.length > 0) void load();
  }, [instances]);

  const togglePlugin = async (tenantId: string, pluginId: string, currentlyActive: boolean) => {
    setActionLoading(`${tenantId}-${pluginId}`);
    try {
      const method = currentlyActive ? 'DELETE' : 'POST';
      const res = await authedFetch('/api/admin/fleet/plugins', {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, pluginId })
      });

      if (!res.ok) throw new Error('API Error');

      toast.success(`Plugin ${currentlyActive ? 'désactivé' : 'activé'} avec succès`);
      await load(); // Refresh data
    } catch (e) {
      toast.error('Erreur lors du changement de statut');
    } finally {
      setActionLoading(null);
    }
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-border-subtle rounded-2xl">
      <div className="flex items-center gap-3 mb-6">
        <ServerCog className="w-5 h-5 text-brand" />
        <h3 className="text-sm font-bold uppercase tracking-widest text-text-secondary">Moteur de Plugins (Marketplace)</h3>
      </div>

      {loading ? (
        <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-brand" /></div>
      ) : instances.length === 0 ? (
        <p className="text-xs text-secondary text-center py-6">Aucun tenant trouvé.</p>
      ) : (
        <div className="space-y-6">
          {pluginsByTenant.map(tenant => (
            <div key={tenant.tenantId} className="border border-focus/10 rounded-xl overflow-hidden">
              <div className="bg-surface-card border-b border-focus/10 p-3 flex items-center gap-2">
                <Store className="w-4 h-4 text-brand" />
                <span className="text-xs font-bold">{tenant.tenantId}</span>
              </div>
              <div className="p-4 grid grid-cols-1 lg:grid-cols-2 gap-4 bg-background/50">
                {Object.entries(dynamicCatalog).map(([pluginId, info]) => {
                  const isActive = tenant.activePlugins[pluginId]?.active === true;
                  const isActionLoading = actionLoading === `${tenant.tenantId}-${pluginId}`;

                  return (
                    <div key={pluginId} className="flex items-center justify-between p-3 bg-surface-card border border-border-subtle rounded-xl">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${isActive ? 'bg-emerald-500/10 text-emerald-500' : 'bg-surface-card border border-border-subtle text-secondary'}`}>
                          <PackageOpen className="w-4 h-4" />
                        </div>
                        <div>
                          <div className="text-xs font-bold">{info.name}</div>
                          <div className="text-[10px] text-secondary font-mono">+{info.basePrice}€/mois</div>
                        </div>
                      </div>

                      <button 
                        disabled={isActionLoading}
                        onClick={() => togglePlugin(tenant.tenantId, pluginId, isActive)}
                        className="p-1 transition-transform active:scale-95 disabled:opacity-50"
                      >
                        {isActionLoading ? (
                          <Loader2 className="w-6 h-6 animate-spin text-brand" />
                        ) : isActive ? (
                          <ToggleRight className="w-8 h-8 text-emerald-500" />
                        ) : (
                          <ToggleLeft className="w-8 h-8 text-secondary" />
                        )}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

/**
 * MFAGate — mcc-core-3
 *
 * Enforces TOTP 2FA enrollment for fleet_admin accounts.
 * Wraps MCC pages with an enrollment modal when the Firebase user has no MFA factor.
 *
 * Flow:
 *  1. On mount: check multiFactor(user).enrolledFactors
 *  2. If none → show enrollment modal (blocks the page)
 *  3. User opens Google Authenticator, enters manual key (or scans otpauth:// URI)
 *  4. User enters 6-digit OTP → completeTOTPEnrollment
 *  5. On success → gate dissolves, children render
 */

import React, { useCallback, useEffect, useState } from 'react';
import { useAuth } from '@/shared/hooks';
import { ShieldAlert, ShieldCheck, Copy, Check, Loader2, AlertCircle } from 'lucide-react';
import {
    isMFAEnrolled,
    startTOTPEnrollment,
    completeTOTPEnrollment,
    type MFAEnrollmentSession,
} from '@/lib/auth/mfa';

type GateStatus = 'checking' | 'enrolled' | 'needs_enrollment' | 'enrolling' | 'verifying' | 'error';

interface MFAGateProps {
    /** Role required to trigger the MFA check — defaults to fleet_admin */
    role?: string;
    children: React.ReactNode;
}

/** Point d'entrée public — délègue à l'implémentation complète ou au bypass dev */
export function MFAGate({ role = 'fleet_admin', children }: MFAGateProps) {
    if (process.env.NEXT_PUBLIC_MCC_DEV_BYPASS === 'true') {
        return <>{children}</>;
    }
    return <MFAGateImpl role={role}>{children}</MFAGateImpl>;
}

function MFAGateImpl({ role = 'fleet_admin', children }: MFAGateProps) {
    const [status, setStatus] = useState<GateStatus>('checking');
    const [session, setSession] = useState<MFAEnrollmentSession | null>(null);
    const [otp, setOtp] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [copied, setCopied] = useState<'url' | 'key' | null>(null);

    // Determine the current user's role from the DB-Agnostic Nexus Auth
    const { currentUser } = useAuth();
    const [userRole, setUserRole] = useState<string | null>(null);

    useEffect(() => {
        if (!currentUser) {
            setStatus('enrolled'); // Auth guard upstream will block non-authed users
            return;
        }
        setUserRole(currentUser.role || null);
    }, [currentUser]);

    useEffect(() => {
        if (userRole === null) return;
        // Only gate fleet_admin (or the specified role)
        if (userRole !== role && role === 'fleet_admin' && userRole !== 'SUPER_ADMIN') {
            setStatus('enrolled');
            return;
        }
        setStatus(isMFAEnrolled() ? 'enrolled' : 'needs_enrollment');
    }, [userRole, role]);

    const handleStartEnrollment = useCallback(async () => {
        setStatus('enrolling');
        setError(null);
        try {
            const accountName = currentUser?.email || currentUser?.name || currentUser?.id || 'Admin';
            const sess = await startTOTPEnrollment(accountName);
            setSession(sess);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Erreur lors de la génération du secret TOTP');
            setStatus('needs_enrollment');
        }
    }, []);

    const handleVerifyOTP = useCallback(async () => {
        if (!session || otp.length !== 6) return;
        setStatus('verifying');
        setError(null);
        try {
            await completeTOTPEnrollment(session.secret, otp);
            setStatus('enrolled');
        } catch (err) {
            setError("Code incorrect ou expiré. Vérifiez l'heure système et réessayez.");
            setStatus('enrolling');
        }
    }, [session, otp]);

    const copy = useCallback(async (text: string, field: 'url' | 'key') => {
        await navigator.clipboard.writeText(text);
        setCopied(field);
        setTimeout(() => setCopied(null), 2000);
    }, []);

    if (status === 'checking') {
        return (
            <div className="flex items-center justify-center min-h-screen bg-black">
                <Loader2 className="animate-spin text-orange-500" size={32} />
            </div>
        );
    }

    if (status === 'enrolled') {
        return <>{children}</>;
    }

    // -- Enrollment gate --
    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/95 backdrop-blur-sm">
            <div className="w-full max-w-lg mx-4 bg-surface-bg border border-orange-500/40 rounded-2xl shadow-2xl shadow-orange-900/20 p-8">

                {/* Header */}
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-orange-500/10 rounded-lg">
                        <ShieldAlert className="text-orange-400" size={24} />
                    </div>
                    <div>
                        <h2 className="text-text-primary font-semibold text-lg">Authentification 2 facteurs requise</h2>
                        <p className="text-text-secondary text-sm">Accès MCC — fleet_admin</p>
                    </div>
                </div>

                <p className="text-text-secondary text-sm mb-6 leading-relaxed">
                    Un compte admin compromis donne accès à <strong className="text-orange-400">tous les restaurants</strong> de la flotte.
                    Vous devez activer le TOTP (Google Authenticator, Authy, 1Password) pour continuer.
                </p>

                {status === 'needs_enrollment' && (
                    <div className="space-y-4">
                        <button
                            onClick={handleStartEnrollment}
                            className="w-full py-3 px-4 bg-orange-500 hover:bg-orange-600 text-text-primary font-medium rounded-xl transition-colors"
                        >
                            Configurer l&apos;authentificateur
                        </button>
                        {error && (
                            <div className="flex items-center gap-2 text-status-danger text-sm bg-status-danger/10 p-3 rounded-lg border border-status-danger/20">
                                <AlertCircle size={14} />
                                <span>{error}</span>
                            </div>
                        )}
                    </div>
                )}

                {status === 'enrolling' && session && (
                    <div className="space-y-5">
                        <div className="bg-surface-card rounded-xl p-4 space-y-4">
                            <p className="text-text-secondary text-sm font-medium">
                                1 — Ouvrez votre application (Google Authenticator · Authy · 1Password)
                            </p>
                            <p className="text-text-secondary text-sm font-medium">
                                2 — Ajoutez un compte manuellement et copiez cette clé secrète :
                            </p>

                            {/* Manual key */}
                            <div className="flex items-center gap-2">
                                <code className="flex-1 bg-surface-bg text-orange-300 text-xs font-mono px-3 py-2 rounded-lg break-all select-all">
                                    {session.manualKey}
                                </code>
                                <button
                                    onClick={() => copy(session.manualKey, 'key')}
                                    className="shrink-0 p-2 bg-surface-elevated hover:bg-zinc-600 rounded-lg transition-colors"
                                    title="Copier la clé"
                                >
                                    {copied === 'key' ? <Check size={14} className="text-green-400" /> : <Copy size={14} className="text-text-secondary" />}
                                </button>
                            </div>

                            <p className="text-text-muted text-xs">
                                Type : TOTP · Algorithme : SHA-1 · Période : 30 s · Chiffres : 6
                            </p>

                            <p className="text-text-secondary text-sm font-medium mt-2">
                                Ou scannez l&apos;URI otpauth (mode avancé) :
                            </p>
                            <div className="flex items-center gap-2">
                                <code className="flex-1 bg-surface-bg text-text-secondary text-xs font-mono px-3 py-2 rounded-lg break-all select-all">
                                    {session.qrUrl}
                                </code>
                                <button
                                    onClick={() => copy(session.qrUrl, 'url')}
                                    className="shrink-0 p-2 bg-surface-elevated hover:bg-zinc-600 rounded-lg transition-colors"
                                    title="Copier l'URI"
                                >
                                    {copied === 'url' ? <Check size={14} className="text-green-400" /> : <Copy size={14} className="text-text-secondary" />}
                                </button>
                            </div>
                        </div>

                        {/* OTP input */}
                        <div className="space-y-2">
                            <label className="text-text-secondary text-sm font-medium">
                                3 — Entrez le code à 6 chiffres affiché dans l&apos;app :
                            </label>
                            <input
                                type="text"
                                inputMode="numeric"
                                maxLength={6}
                                pattern="\d{6}"
                                placeholder="000000"
                                value={otp}
                                onChange={e => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                onKeyDown={e => e.key === 'Enter' && handleVerifyOTP()}
                                className="w-full bg-surface-card border border-zinc-600 text-text-primary text-center text-xl font-mono tracking-widest rounded-xl px-4 py-3 focus:outline-none focus:border-orange-500 transition-colors"
                            />
                        </div>

                        {error && (
                            <div className="flex items-center gap-2 text-status-danger text-sm">
                                <AlertCircle size={14} />
                                <span>{error}</span>
                            </div>
                        )}

                        <button
                            onClick={handleVerifyOTP}
                            disabled={otp.length !== 6}
                            className="w-full py-3 px-4 bg-orange-500 hover:bg-orange-600 disabled:bg-surface-elevated disabled:cursor-not-allowed text-text-primary font-medium rounded-xl transition-colors"
                        >
                            Vérifier et activer le 2FA
                        </button>
                    </div>
                )}

                {status === 'verifying' && (
                    <div className="flex items-center justify-center gap-3 py-8 text-text-secondary">
                        <Loader2 className="animate-spin" size={20} />
                        <span>Vérification en cours…</span>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-6 pt-4 border-t border-zinc-800">
                    <div className="flex items-center gap-2 text-text-muted text-xs">
                        <ShieldCheck size={12} />
                        <span>Le secret TOTP n&apos;est jamais stocké sur nos serveurs — clé locale dans l&apos;app uniquement.</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";
import { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useSearchParams } from 'next/navigation';
import { useSetAtom } from 'jotai';
import { NexusSutures } from '@/store/nexusSutures';
import { getTenantConfig } from '@/instances';
import { DEFAULT_TENANT_ID } from '@/config/instance';
import { logger } from '@/lib/axiom';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { FirestoreAdapter } from '@/infrastructure/adapters/FirestoreAdapter';
import { LLMManager } from '@/modules/intelligence/ia/ai/LLMManager';
import { GeminiProvider } from '@/infrastructure/adapters/GeminiProvider';
import { StorageManager } from '@/infrastructure/services/storage';
import { FirebaseStorageProvider } from '@/infrastructure/services/storage/FirebaseStorageProvider';
import { NexusTelemetryEngine } from '@shared/nexus/engines/NexusTelemetryEngine';
import { tenantConfigAtom } from '@/store/pillars/sovereign';
import { DemoSeeder } from '@/infrastructure/services/demo/DemoSeeder';
import type { TenantConfig } from '@/shared/nexus-contract';
import type { NexusTenantState } from '@nexus/contracts/nexus.types';

/**
 * Tenant module (Digital Twin context) extracted from NexusCoreProvider.
 * Owns: tenant state, Firestore adapter bootstrap, telemetry + sutures lifecycle,
 * and the switchTenant flow. Runtime behaviour is identical to the inlined version.
 */
export function useNexusTenantLogic(): NexusTenantState {
    const searchParams = useSearchParams();
    const hasInitialized = useRef(false);
    const setGlobalTenantConfig = useSetAtom(tenantConfigAtom);

    const [activeTenantId, setActiveTenantId] = useState<string | null>(null);
    const [activeTenantConfig, setActiveTenantConfig] = useState<TenantConfig | null>(null);

    useEffect(() => {
        try {
            Nexus.adapter = new FirestoreAdapter();
            LLMManager.provider = new GeminiProvider();
            StorageManager.provider = new FirebaseStorageProvider();
        } catch { }
    }, []);

    useEffect(() => {
        NexusTelemetryEngine.mountChaosMonkeys();
        NexusSutures.init();
        return () => {
            NexusTelemetryEngine.unmountChaosMonkeys();
            NexusSutures.stop();
        };
    }, []);

    const switchTenant = useCallback((tenantIdRaw: string) => {
        const tenantId = tenantIdRaw.replace(/['"]+/g, '');
        logger.info('NexusCore: Switching Digital Twin context', { tenantId });
        const config = getTenantConfig(tenantId);
        if (!config) return;

        setActiveTenantId(tenantId);
        setActiveTenantConfig(config);
        setGlobalTenantConfig(config);
        Nexus.tenantOverride = tenantId;
        NexusTelemetryEngine.initSession(tenantId);

        // Auto-provision Demo Mode if requested via URL
        if (typeof window !== 'undefined') {
            const isSimulacra = new URLSearchParams(window.location.search).get('simulacra') === 'true';
            if (isSimulacra) {
                Nexus.activateSimulacraMode(tenantId).then(() => {
                    DemoSeeder.provision(tenantId).catch(err => {
                        logger.error('Failed to provision demo data', { error: err.message });
                    });
                });
            }
        }
    }, [setGlobalTenantConfig]);

    useEffect(() => {
        if (!activeTenantId && !hasInitialized.current) {
            const targetTenant = searchParams.get('tenant') || DEFAULT_TENANT_ID;
            hasInitialized.current = true;
            switchTenant(targetTenant);
        }
    }, [activeTenantId, searchParams, switchTenant]);

    return useMemo(() => ({
        activeTenantId, activeTenantConfig, switchTenant,
        isTenantLoading: !activeTenantId, tenantId: activeTenantId || undefined
    }), [activeTenantId, activeTenantConfig, switchTenant]);
}
